// Khoá TỰ SOẠN cho CIC302 — trường chưa công bố syllabus trên FLM (dò 09/11/2026). Soạn theo _HOP-DONG-TU-SOAN.md.
// Khung nối tiếp CIC301 (HSK 3 → đầu HSK 4): CIC302 đưa người học lên HSK 4 vững → HSK 5, bám thứ tự "HSK Standard Course 5A/5B"
// (Jiang Liping, BLCU Press) và danh mục ngữ pháp HSK 5 của Chinese Grammar Wiki. Không lặp mẫu câu đã học ở CIC301.
// Mọi link ngoài đã mở thử (HTTP 200 + tiêu đề đúng chủ đề). Pinyin theo quy ước CIC301: có dấu thanh, 不/一 ghi theo biến điệu.
// ⚠️ File này KHÔNG dùng chuỗi nội suy (dấu đô-la + ngoặc nhọn); bài được dựng bằng hàm L() từ dữ liệu.

const zhTag = (s) => s.replace(/⟦([^⟧]*)⟧/g, '<span lang="zh">$1</span>');
const pick = (a, i) => zhTag(Array.isArray(a) ? a[i] : a);
const LAB = [
  { goals: 'Lesson goals', lesson: 'Lesson', vocab: 'Vocabulary', dia: 'Model dialogue / text', pit: 'Common mistakes', sum: '📌 Summary', more: '🔗 Learn more', prac: '🧪 Practice', ans: 'Answer', pat: 'Pattern', h: ['Hanzi', 'Pinyin', 'Meaning'], hd: ['Who', 'Hanzi', 'Pinyin', 'Meaning'] },
  { goals: 'Mục tiêu bài', lesson: 'Bài giảng', vocab: 'Từ vựng', dia: 'Hội thoại / bài khoá mẫu', pit: 'Lỗi hay gặp', sum: '📌 Tóm tắt', more: '🔗 Học thêm', prac: '🧪 Tự luyện', ans: 'Đáp án', pat: 'Mẫu', h: ['Hán tự', 'Pinyin', 'Nghĩa'], hd: ['Ai', 'Hán tự', 'Pinyin', 'Nghĩa'] },
];
function render(key, d, i) {
  const t = LAB[i];
  let h = '<span class="eyebrow">CIC302 · ' + (key.charAt(0) === '0' ? 'Section 0' : 'Chapter ' + key.split('.')[0]) + ' · Lesson ' + key + '</span>\n';
  if (i === 1) h = h.replace('Section 0', 'Mục 0').replace('Chapter', 'Chương').replace('Lesson', 'Bài');
  h += '<h3>' + t.goals + '</h3><ul>' + d.goals.map((g) => '<li>' + pick(g, i) + '</li>').join('') + '</ul>\n';
  h += '<h3>' + t.lesson + '</h3>';
  for (const s of d.sec) {
    if (s.h) h += '<h4>' + pick(s.h, i) + '</h4>';
    if (s.box) h += '<div class="callout">' + pick(s.box, i) + '</div>';
    if (s.p) h += '<p>' + pick(s.p, i) + '</p>';
    if (s.f) h += '<div class="formula"><span class="lbl">' + t.pat + '</span>' + zhTag(s.f) + '</div>';
    if (s.ul) h += '<ul>' + s.ul.map((x) => '<li>' + pick(x, i) + '</li>').join('') + '</ul>';
    if (s.ex) h += '<ul>' + s.ex.map((x) => '<li><span lang="zh">' + x[0] + '</span><br><em>' + x[1] + '</em><br>' + x[2 + i] + '</li>').join('') + '</ul>';
  }
  if (d.vocab) {
    h += '\n<h3>' + t.vocab + '</h3><table><thead><tr>' + t.h.map((x) => '<th>' + x + '</th>').join('') + '</tr></thead><tbody>' +
      d.vocab.map((v) => '<tr><td><span lang="zh">' + v[0] + '</span></td><td>' + v[1] + '</td><td>' + v[2 + i] + '</td></tr>').join('') + '</tbody></table>';
  }
  if (d.dia) {
    h += '\n<h3>' + t.dia + '</h3><table><thead><tr>' + t.hd.map((x) => '<th>' + x + '</th>').join('') + '</tr></thead><tbody>' +
      d.dia.map((v) => '<tr><td>' + v[0] + '</td><td><span lang="zh">' + v[1] + '</span></td><td>' + v[2] + '</td><td>' + v[3 + i] + '</td></tr>').join('') + '</tbody></table>';
  }
  if (d.pit) h += '\n<div class="pitfall"><strong>' + t.pit + '.</strong> ' + pick(d.pit, i) + '</div>';
  h += '\n<h3>' + t.sum + '</h3><ul>' + d.sum.map((x) => '<li>' + pick(x, i) + '</li>').join('') + '</ul>';
  h += '\n<h3>' + t.more + '</h3><ul>' + d.links.map((l) => '<li><a href="' + l[0] + '" target="_blank" rel="noopener">' + l[1 + i] + '</a></li>').join('') + '</ul>';
  h += '\n<h3>' + t.prac + '</h3><ol>' + d.prac.map((p) => '<li>' + pick([p[0], p[1]], i) + '<div class="dap-an"><strong>' + t.ans + ':</strong> ' + pick([p[2], p[3]], i) + '</div></li>').join('') + '</ol>';
  return h;
}
const L = (key, title, desc, d) => ({
  title: key + ' ' + title[0] + '|||' + key + ' ' + title[1], slug: 'cic302-ts-' + key.replace('.', '-'), type: 'DOCUMENT', description: desc,
  content: '<div class="ml-en">' + render(key, d, 0) + '</div>\n<div class="ml-vi">' + render(key, d, 1) + '</div>',
});
const bq = (s) => (Array.isArray(s) ? s[0] + '|||' + s[1] : s + '|||' + s).replace(/[⟦⟧]/g, '');
const Q = (id, q, opts, ci, ex) => ({ id, question: bq(q), options: opts.map(bq), correctIndex: ci, points: 1, explanation: bq(ex) });
const QZ = (ch, desc, questions) => ({
  title: 'Quiz — Chapter ' + ch + '|||Quiz chương ' + ch, slug: 'cic302-ts-quiz-' + ch, type: 'QUIZ', description: desc,
  quiz: { timeLimitSeconds: 600, questions },
});
const CH = (n, en, vi, desc, lessons) => ({ title: 'Chapter ' + n + ' — ' + en + '|||Chương ' + n + ' — ' + vi, description: desc, lessons });
const GW = 'https://resources.allsetlearning.com/chinese/grammar/';

const m01 = L('0.1', ['Welcome to CIC302 — Intensive Chinese 4', 'Giới thiệu CIC302 — Tiếng Trung tổng hợp tăng cường 4'],
  'CIC302 học gì, để làm gì, 8 chuẩn đầu ra tự soạn, nối tiếp CIC301 thế nào, cảnh báo: trường chưa công bố syllabus trên FLM.', {
  goals: [['Know what CIC302 covers and how it continues CIC301', 'Biết CIC302 học gì và nối tiếp CIC301 ra sao'], ['Read the 8 self-authored learning outcomes', 'Đọc 8 chuẩn đầu ra tự soạn'], ['Plan a weekly study routine', 'Lập thói quen học theo tuần']],
  sec: [
    { box: [`<strong>⚠️ Please read.</strong> FPT University has <strong>not published a syllabus for CIC302 on FLM</strong> (we searched the code, its variants and the course name on 09/11/2026). This framework is <strong>self-authored</strong>, following the order of the standard textbook series <em>HSK Standard Course 5A/5B</em> and the HSK 5 grammar list. <strong>Grading weights, assessment format and exam dates are decided by your lecturer</strong> — follow the outline given in class.`,
      `<strong>⚠️ Vui lòng đọc.</strong> Trường ĐH FPT <strong>chưa công bố syllabus của CIC302 trên FLM</strong> (đã dò mã, mã biến thể và tên môn ngày 09/11/2026). Khung này do chúng tôi <strong>tự soạn</strong>, bám thứ tự bộ giáo trình chuẩn <em>HSK Standard Course 5A/5B</em> và danh mục ngữ pháp HSK 5. <strong>Cách tính điểm, hình thức kiểm tra, lịch thi do giảng viên quyết định</strong> — hãy theo đề cương thầy cô phát trên lớp.`] },
    { h: ['What is CIC302?', 'CIC302 là gì?'], p: [`CIC302 (Intensive Chinese 4) is the fourth intensive Chinese course of the Chinese Language programme. It continues <strong>CIC301</strong>, which ended around the middle of HSK 4 (about 1,000–1,200 words). CIC302 consolidates HSK 4 and moves you towards <strong>HSK 5</strong> (about 2,500 words in total): you learn roughly 500–600 new words and about 50 new patterns, nearly all of them <em>new</em> — patterns you met in CIC301 (⟦无论…都⟧, ⟦连…都⟧, ⟦即使…也⟧, ⟦把⟧ and passives…) are reviewed, not retaught.`,
      `CIC302 (Tiếng Trung tổng hợp tăng cường 4) là học phần tổng hợp thứ tư của ngành Ngôn ngữ Trung. Nó nối tiếp <strong>CIC301</strong>, vốn dừng ở khoảng giữa HSK 4 (chừng 1.000–1.200 từ). CIC302 củng cố HSK 4 và đưa bạn tiến tới <strong>HSK 5</strong> (khoảng 2.500 từ tích luỹ): học thêm khoảng 500–600 từ và 50 mẫu câu, hầu hết là <em>mới</em> — các mẫu đã học ở CIC301 (⟦无论…都⟧, ⟦连…都⟧, ⟦即使…也⟧, câu ⟦把⟧, bị động…) chỉ được ôn, không dạy lại.`] },
    { h: ['Why it matters', 'Vì sao quan trọng'], ul: [
      [`<strong>Study and work:</strong> HSK 5 is the usual threshold for Chinese-medium university programmes and for office work with Chinese partners.`, `<strong>Học và làm việc:</strong> HSK 5 là ngưỡng thường gặp cho chương trình học bằng tiếng Trung và công việc văn phòng với đối tác Trung Quốc.`],
      [`<strong>Real texts:</strong> from this level you read newspaper articles, follow TV news and write 80-character essays with logical connectors.`, `<strong>Văn bản thật:</strong> ở trình độ này bạn đọc được báo, nghe được tin tức và viết đoạn 80 chữ có từ nối logic.`],
      [`<strong>Style:</strong> you learn the difference between spoken and written Chinese (⟦书面语⟧ vs ⟦口语⟧) and four-character idioms (⟦成语⟧).`, `<strong>Văn phong:</strong> bạn học phân biệt khẩu ngữ và văn viết (⟦口语⟧ / ⟦书面语⟧) và thành ngữ bốn chữ (⟦成语⟧).`]] },
    { h: ['Learning outcomes (self-authored)', 'Chuẩn đầu ra (tự soạn)'], ul: [
      ['Use about 550 new words and 50 new patterns (HSK 4 → 5) accurately.', 'Dùng đúng khoảng 550 từ mới và 50 mẫu câu mới (HSK 4 → 5).'],
      ['Express comparison, preference and choice: ⟦与其…不如…⟧, ⟦宁可…也不…⟧, ⟦何况⟧.', 'Diễn đạt so sánh, ưa thích, lựa chọn: ⟦与其…不如…⟧, ⟦宁可…也不…⟧, ⟦何况⟧.'],
      ['Express purpose, hypothesis and result: ⟦以便⟧, ⟦一旦⟧, ⟦万一⟧, ⟦从而⟧.', 'Diễn đạt mục đích, giả thiết, kết quả: ⟦以便⟧, ⟦一旦⟧, ⟦万一⟧, ⟦从而⟧.'],
      ['Give opinions and advice politely: ⟦不妨⟧, ⟦何必⟧, ⟦未必⟧, ⟦对…而言⟧.', 'Nêu ý kiến, lời khuyên lịch sự: ⟦不妨⟧, ⟦何必⟧, ⟦未必⟧, ⟦对…而言⟧.'],
      ['Use evaluative adverbs: ⟦毕竟⟧, ⟦反正⟧, ⟦简直⟧, ⟦偏偏⟧, ⟦恰恰⟧.', 'Dùng phó từ đánh giá: ⟦毕竟⟧, ⟦反正⟧, ⟦简直⟧, ⟦偏偏⟧, ⟦恰恰⟧.'],
      ['Understand and use about 40 common ⟦成语⟧ and a few proverbs.', 'Hiểu và dùng khoảng 40 ⟦成语⟧ thông dụng cùng vài tục ngữ.'],
      ['Read a 500–600 character passage and answer questions (HSK 5 reading).', 'Đọc đoạn văn 500–600 chữ và trả lời câu hỏi (đọc hiểu HSK 5).'],
      ['Write an 80-character composition with the given words (HSK 5 writing).', 'Viết đoạn văn 80 chữ với các từ cho trước (viết HSK 5).']] },
    { h: ['Related courses at FPTU', 'Môn liên quan trong khung FPTU'], p: [`Prerequisite in practice: <strong>CIC301</strong> (and CIC102 before it). The course after CIC302 in the Chinese Language programme builds on HSK 5 — check the exact code in your study plan on FLM. Reading, writing, listening and speaking courses of the programme run in parallel and use the same vocabulary.`, `Môn tiên quyết trên thực tế: <strong>CIC301</strong> (và CIC102 trước đó). Học phần sau CIC302 trong ngành Ngôn ngữ Trung xây tiếp trên nền HSK 5 — xem mã chính xác trong chương trình học trên FLM. Các môn đọc, viết, nghe, nói của ngành chạy song song và dùng chung từ vựng.`] },
    { h: ['Weekly routine', 'Thói quen theo tuần'], p: [`Each chapter: read one lesson a day, copy the example sentences by hand, then write <strong>three own sentences</strong> for every new pattern. End the week with the chapter quiz. Keep an error notebook and a word list with ⟦汉字 + pinyin + meaning + one sentence⟧.`, `Mỗi chương: đọc một bài mỗi ngày, chép tay các câu ví dụ, rồi viết <strong>ba câu của riêng bạn</strong> cho mỗi mẫu mới. Cuối tuần làm quiz chương. Giữ sổ lỗi sai và sổ từ gồm ⟦汉字 + pinyin + nghĩa + một câu⟧.`] }],
  pit: [`Memorising patterns as English glosses. Learn each pattern inside a full Chinese sentence, otherwise you will not know which half takes ⟦也⟧, ⟦都⟧ or ⟦就⟧.`, `Học mẫu câu bằng nghĩa tiếng Việt rời rạc. Hãy học trong câu Hán trọn vẹn, nếu không bạn sẽ không biết vế nào đi với ⟦也⟧, ⟦都⟧ hay ⟦就⟧.`],
  sum: [['CIC302 = HSK 4 consolidated + HSK 5 patterns and vocabulary.', 'CIC302 = củng cố HSK 4 + mẫu câu và từ vựng HSK 5.'], ['Nine chapters, 27 lessons, a quiz per chapter.', 'Chín chương, 27 bài, mỗi chương một quiz.'], ['The FLM syllabus is not published: grading follows your lecturer.', 'Chưa có syllabus FLM: điểm số theo giảng viên.']],
  links: [[GW + 'HSK_5_grammar_points', 'Chinese Grammar Wiki — HSK 5 grammar points', 'Chinese Grammar Wiki — ngữ pháp HSK 5'], ['https://www.hsk.academy/en/hsk-5-vocabulary-list', 'HSK Academy — HSK 5 vocabulary list', 'HSK Academy — từ vựng HSK 5'], ['https://en.wikipedia.org/wiki/Hanyu_Shuiping_Kaoshi', 'Wikipedia — HSK test overview', 'Wikipedia — tổng quan kỳ thi HSK']],
  prac: [['Name two patterns from CIC301 that are reviewed, not retaught, here.', 'Kể hai mẫu của CIC301 chỉ được ôn lại ở đây.', '⟦无论…都⟧ and ⟦连…都⟧ (also ⟦即使…也⟧, ⟦把⟧).', '⟦无论…都⟧ và ⟦连…都⟧ (còn có ⟦即使…也⟧, ⟦把⟧).'], ['Who decides the grading weights of CIC302?', 'Ai quyết định cách tính điểm CIC302?', 'Your lecturer — FLM has no syllabus.', 'Giảng viên — FLM không có syllabus.']] });

