const c1 = CH(1, 'Consumption and shopping', 'Tiêu dùng và mua sắm',
  'Từ vựng tiêu dùng, lựa chọn (与其…不如, 宁可…也不), so sánh mức độ (何况, 别说), phó từ đánh giá (毕竟, 反正, 简直).', [
  L('1.1', ['Consumer choices: 与其…不如…, 宁可…也不…', 'Lựa chọn của người tiêu dùng: 与其…不如…, 宁可…也不…'], 'Từ vựng mua sắm và hai mẫu so sánh lựa chọn: bỏ A chọn B, và chịu A còn hơn B.', {
    goals: [['Say “rather than A, better B” with ⟦与其…不如…⟧', 'Nói “thà B còn hơn A” bằng ⟦与其…不如…⟧'], ['Say “would rather A than B” with ⟦宁可…也不…⟧', 'Nói “thà chịu A chứ không B” bằng ⟦宁可…也不…⟧'], ['Learn 10 shopping words', 'Học 10 từ về mua sắm']],
    sec: [
      { h: ['与其 A，不如 B — B is the better choice', '与其 A，不如 B — B là lựa chọn tốt hơn'], p: [`Both A and B are possible, but the speaker judges <strong>B better</strong> and drops A. Note the logic: you are not choosing A; ⟦与其⟧ introduces what you give up.`, `Cả A và B đều làm được, nhưng người nói cho rằng <strong>B tốt hơn</strong> và bỏ A. Lưu ý logic: bạn không chọn A; ⟦与其⟧ dẫn ra điều bị bỏ.`], f: '与其 + A，不如 + B',
        ex: [['与其花钱买名牌，不如把钱存起来。', 'Yǔqí huā qián mǎi míngpái, bùrú bǎ qián cún qǐlái.', 'Rather than spend money on brand names, better to save it.', 'Thay vì tiêu tiền mua đồ hiệu, tốt hơn là để dành.'], ['与其在家抱怨，不如出去找工作。', 'Yǔqí zài jiā bàoyuàn, bùrú chūqù zhǎo gōngzuò.', 'Rather than complain at home, go out and look for a job.', 'Thay vì than phiền ở nhà, chi bằng ra ngoài tìm việc.'], ['与其等打折，不如现在就买。', 'Yǔqí děng dǎzhé, bùrú xiànzài jiù mǎi.', 'Rather than wait for a sale, buy now.', 'Thay vì chờ giảm giá, mua luôn bây giờ còn hơn.']] },
      { h: ['宁可 A，也不 B — accept A to avoid B', '宁可 A，也不 B — chịu A để khỏi B'], p: [`Here the speaker <strong>chooses A</strong> (the lesser evil or a sacrifice) so as to avoid B. ⟦宁可⟧ also has the forms ⟦宁愿⟧ and ⟦宁肯⟧. For a positive sacrifice use ⟦宁可 A，也要 B⟧: “prepared to A in order to B”.`, `Ở đây người nói <strong>chọn A</strong> (điều đỡ tệ hơn hoặc sự hy sinh) để tránh B. ⟦宁可⟧ còn có dạng ⟦宁愿⟧ và ⟦宁肯⟧. Muốn nói sẵn sàng hy sinh để đạt B dùng ⟦宁可 A，也要 B⟧.`], f: '宁可 + A，也不 / 也要 + B',
        ex: [['我宁可多走路，也不想坐拥挤的地铁。', 'Wǒ nìngkě duō zǒulù, yě bù xiǎng zuò yōngjǐ de dìtiě.', 'I would rather walk more than ride the crowded metro.', 'Tôi thà đi bộ nhiều còn hơn đi tàu điện đông nghẹt.'], ['他宁可不吃饭，也要把这双鞋买下来。', 'Tā nìngkě bù chī fàn, yě yào bǎ zhè shuāng xié mǎi xiàlái.', 'He would skip meals to be able to buy these shoes.', 'Anh ấy thà nhịn ăn cũng phải mua đôi giày này.'], ['宁可多花一点钱，也不能买质量差的东西。', 'Nìngkě duō huā yìdiǎn qián, yě bù néng mǎi zhìliàng chà de dōngxi.', 'Better to pay a bit more than buy poor quality.', 'Thà tốn thêm chút tiền còn hơn mua đồ kém chất lượng.']] }],
    vocab: [['消费', 'xiāofèi', 'to consume; spending', 'tiêu dùng'], ['品牌', 'pǐnpái', 'brand', 'thương hiệu'], ['打折', 'dǎ zhé', 'to give a discount (五折 = 50% off)', 'giảm giá (五折 = giảm 50%)'], ['优惠', 'yōuhuì', 'preferential; special offer', 'ưu đãi'], ['性价比', 'xìngjiàbǐ', 'value for money', 'tỉ lệ giá/chất lượng'], ['退货', 'tuì huò', 'to return goods', 'trả hàng'], ['浪费', 'làngfèi', 'to waste', 'lãng phí'], ['网购', 'wǎnggòu', 'online shopping', 'mua sắm trực tuyến'], ['拥挤', 'yōngjǐ', 'crowded', 'chen chúc, đông nghẹt'], ['抱怨', 'bàoyuàn', 'to complain', 'than phiền']],
    dia: [['A', '这件外套打五折，你不买吗？', 'Zhè jiàn wàitào dǎ wǔ zhé, nǐ bù mǎi ma?', 'This coat is half price. Aren’t you buying it?', 'Cái áo khoác này giảm một nửa, bạn không mua à?'], ['B', '我宁可不买，也不想买用不着的东西。', 'Wǒ nìngkě bù mǎi, yě bù xiǎng mǎi yòng bu zháo de dōngxi.', 'I’d rather not buy than buy things I don’t need.', 'Tôi thà không mua còn hơn mua đồ không dùng đến.'], ['A', '可是性价比很高啊。', 'Kěshì xìngjiàbǐ hěn gāo a.', 'But the value for money is great.', 'Nhưng tỉ lệ giá/chất lượng rất tốt mà.'], ['B', '与其买便宜的，不如买合适的。', 'Yǔqí mǎi piányi de, bùrú mǎi héshì de.', 'Rather than buy cheap, buy what suits you.', 'Thay vì mua đồ rẻ, hãy mua đồ hợp với mình.']],
    pit: [`Using ⟦不如⟧ without a real alternative (⟦与其买书，不如买书⟧ is meaningless), and mixing the two patterns: in ⟦宁可 A，也不 B⟧ the speaker <em>accepts</em> A, while in ⟦与其 A，不如 B⟧ the speaker <em>rejects</em> A.`, `Dùng ⟦不如⟧ mà không có lựa chọn thật sự, và lẫn hai mẫu: ở ⟦宁可 A，也不 B⟧ người nói <em>chấp nhận</em> A, còn ở ⟦与其 A，不如 B⟧ người nói <em>bác bỏ</em> A.`],
    sum: [['⟦与其 A，不如 B⟧: drop A, B is better.', '⟦与其 A，不如 B⟧: bỏ A, B tốt hơn.'], ['⟦宁可 A，也不 B⟧: accept A to avoid B.', '⟦宁可 A，也不 B⟧: chịu A để tránh B.'], ['⟦五折⟧ means 50% off, not 5% off.', '⟦五折⟧ là giảm 50%, không phải 5%.']],
    links: [[GW + 'ASGF3F2Y', 'Chinese Grammar Wiki — “would rather” with 宁可', 'Chinese Grammar Wiki — “thà…” với 宁可'], [GW + 'ASGE4B94', 'Chinese Grammar Wiki — comparisons with 比起', 'Chinese Grammar Wiki — so sánh với 比起'], ['https://www.hsk.academy/en/hsk-5-vocabulary-list', 'HSK Academy — HSK 5 vocabulary list', 'HSK Academy — từ vựng HSK 5']],
    prac: [['Say: “Rather than eat out, it is better to cook at home.”', 'Nói: “Thay vì ăn ngoài, nấu ở nhà còn hơn.”', '⟦与其在外面吃，不如在家做饭。⟧ Yǔqí zài wàimiàn chī, bùrú zài jiā zuòfàn.', '⟦与其在外面吃，不如在家做饭。⟧ Yǔqí zài wàimiàn chī, bùrú zài jiā zuòfàn.'], ['Say: “I would rather stay up late than hand in the work late.”', 'Nói: “Tôi thà thức khuya còn hơn nộp bài muộn.”', '⟦我宁可熬夜，也不想迟交作业。⟧ Wǒ nìngkě áoyè, yě bù xiǎng chí jiāo zuòyè.', '⟦我宁可熬夜，也不想迟交作业。⟧ Wǒ nìngkě áoyè, yě bù xiǎng chí jiāo zuòyè.']] }),
  L('1.2', ['Even more so: 何况, 况且, 别说…', 'Huống chi: 何况, 况且, 别说…'], 'Ba cách nói “huống chi/đã thế lại”: 何况 (suy từ dễ đến khó), 况且 (thêm lý do), 别说…连…都 / 更不用说.', {
    goals: [['Use ⟦何况⟧ for an a-fortiori argument', 'Dùng ⟦何况⟧ cho lập luận “đến… còn… huống chi”'], ['Add a further reason with ⟦况且⟧', 'Thêm lý do bổ sung bằng ⟦况且⟧'], ['Use ⟦别说…⟧ and ⟦更不用说⟧ to “let alone”', 'Dùng ⟦别说…⟧ và ⟦更不用说⟧ để nói “nói chi”']],
    sec: [
      { h: ['何况 — if the easy case holds, the hard one surely does', '何况 — việc dễ còn thế, huống chi việc khó'], p: [`First state an easy or extreme case that is already true, then use ⟦何况⟧ for the harder case, usually ending in ⟦呢⟧ (a rhetorical question). The first part often has ⟦都⟧ or ⟦尚且⟧.`, `Nêu trước một trường hợp dễ hoặc cực đoan đã đúng, rồi dùng ⟦何况⟧ cho trường hợp khó hơn, thường kết thúc bằng ⟦呢⟧ (câu hỏi tu từ). Vế đầu hay có ⟦都⟧ hoặc ⟦尚且⟧.`], f: 'A 都 / 尚且 …，何况 B 呢？',
        ex: [['这么简单的题，小孩子都会做，何况你呢？', 'Zhème jiǎndān de tí, xiǎoháizi dōu huì zuò, hékuàng nǐ ne?', 'Even a child can do such an easy question, let alone you.', 'Câu dễ thế trẻ con còn làm được, huống chi bạn.'], ['平时都买不起，何况现在涨价了？', 'Píngshí dōu mǎi bù qǐ, hékuàng xiànzài zhǎng jià le?', 'We couldn’t afford it even normally, let alone now the price has risen.', 'Ngày thường còn không mua nổi, huống chi giờ đã tăng giá.']] },
      { h: ['况且 — “besides, moreover”', '况且 — “hơn nữa, vả lại”'], p: [`⟦况且⟧ simply adds a <em>further</em> reason in the second clause; there is no easy-to-hard comparison. Put it after the main reason.`, `⟦况且⟧ chỉ đơn giản thêm một lý do <em>nữa</em> ở vế sau; không có so sánh từ dễ đến khó. Đặt sau lý do chính.`], f: '理由 1，况且 + 理由 2',
        ex: [['这家店太远了，况且价格也不便宜，我们别去了。', 'Zhè jiā diàn tài yuǎn le, kuàngqiě jiàgé yě bù piányi, wǒmen bié qù le.', 'This shop is too far, and the prices aren’t cheap either — let’s not go.', 'Cửa hàng này xa quá, vả lại giá cũng không rẻ, mình đừng đi.']] },
      { h: ['别说 A，连 B 都 … — “let alone”', '别说 A，连 B 都 … — “nói chi”'], p: [`The impossible big case comes first: ⟦别说 A⟧ (A is out of the question), and the smaller case B is also not satisfied (⟦连 B 都 / 也 …⟧, reviewed from CIC301). ⟦更不用说⟧ is a more formal alternative placed after the small case.`, `Trường hợp lớn, bất khả đặt trước: ⟦别说 A⟧ (A khỏi bàn), và cả trường hợp nhỏ B cũng không đạt (⟦连 B 都 / 也 …⟧, ôn từ CIC301). ⟦更不用说⟧ là cách trang trọng hơn, đặt sau trường hợp nhỏ.`], f: '别说 A，(就) 连 B 都 …',
        ex: [['别说买车，他连自行车都买不起。', 'Bié shuō mǎi chē, tā lián zìxíngchē dōu mǎi bù qǐ.', 'Let alone a car, he can’t even afford a bicycle.', 'Nói chi mua ô tô, đến xe đạp anh ấy cũng không mua nổi.'], ['他连自己的家人都不认识，更不用说外人了。', 'Tā lián zìjǐ de jiārén dōu bú rènshi, gèng búyòng shuō wàirén le.', 'He doesn’t even know his own family, let alone outsiders.', 'Anh ấy còn chẳng biết người nhà, nói chi người ngoài.']] }],
    vocab: [['何况', 'hékuàng', 'let alone; moreover', 'huống chi'], ['况且', 'kuàngqiě', 'besides', 'vả lại'], ['别说', 'biéshuō', 'let alone', 'nói chi'], ['尚且', 'shàngqiě', 'even (used before 何况)', 'còn… (đi với 何况)'], ['奢侈', 'shēchǐ', 'luxurious; extravagant', 'xa xỉ'], ['价格', 'jiàgé', 'price', 'giá cả'], ['昂贵', 'ángguì', 'expensive', 'đắt đỏ'], ['实惠', 'shíhuì', 'good value', 'thiết thực, giá hời'], ['促销', 'cùxiāo', 'sales promotion', 'khuyến mãi'], ['涨价', 'zhǎng jià', 'price rise', 'tăng giá']],
    dia: [['A', '这个包的价格太昂贵了。', 'Zhège bāo de jiàgé tài ángguì le.', 'This bag is far too expensive.', 'Cái túi này đắt quá.'], ['B', '别说你，我连一个钱包都舍不得买。', 'Bié shuō nǐ, wǒ lián yí gè qiánbāo dōu shěbude mǎi.', 'Never mind you, I can’t bring myself to buy even a wallet.', 'Khỏi nói bạn, đến cái ví tôi cũng tiếc không dám mua.'], ['A', '况且我们是学生，没有收入。', 'Kuàngqiě wǒmen shì xuésheng, méiyǒu shōurù.', 'Besides, we are students with no income.', 'Vả lại chúng ta là sinh viên, không có thu nhập.'], ['B', '对，学生尚且要省钱，何况是奢侈品呢？', 'Duì, xuésheng shàngqiě yào shěng qián, hékuàng shì shēchǐpǐn ne?', 'Right, students have to save, let alone buy luxury goods.', 'Đúng, sinh viên còn phải tiết kiệm, huống chi hàng xa xỉ.']],
    pit: [`Ending a ⟦何况⟧ sentence as a plain statement without ⟦呢⟧ or a rhetorical tone, and using ⟦何况⟧ when the second case is <em>easier</em> than the first (the logic must go from easy to hard).`, `Dùng ⟦何况⟧ như câu khẳng định thường, không có ⟦呢⟧ hay giọng tu từ, và dùng khi trường hợp sau lại <em>dễ hơn</em> trường hợp trước (logic phải đi từ dễ đến khó).`],
    sum: [['⟦何况⟧: easy case true ⇒ hard case certainly.', '⟦何况⟧: việc dễ còn đúng ⇒ việc khó càng đúng.'], ['⟦况且⟧: just adds another reason.', '⟦况且⟧: chỉ thêm một lý do.'], ['⟦别说 A，连 B 都…⟧: “let alone”.', '⟦别说 A，连 B 都…⟧: “nói chi”.']],
    links: [[GW + 'ASGR6Q2J', 'Chinese Grammar Wiki — “let alone” with 别说', 'Chinese Grammar Wiki — “nói chi” với 别说'], [GW + 'ASGHOI8S', 'Chinese Grammar Wiki — “let alone” with 更不用说', 'Chinese Grammar Wiki — “nói chi” với 更不用说'], [GW + 'ASGF9320', 'Chinese Grammar Wiki — 不但…甚至连…', 'Chinese Grammar Wiki — 不但…甚至连…']],
    prac: [['Join: 我不会游泳 / 他连水都怕 — with 别说.', 'Nối bằng 别说: 我不会游泳 / 他连水都怕.', '⟦别说游泳，他连水都怕。⟧ Bié shuō yóuyǒng, tā lián shuǐ dōu pà.', '⟦别说游泳，他连水都怕。⟧ Bié shuō yóuyǒng, tā lián shuǐ dōu pà.'], ['Complete: 老师都不知道，____ 我们呢？', 'Điền: 老师都不知道，____ 我们呢？', '⟦何况⟧ — hékuàng.', '⟦何况⟧ — hékuàng.']] }),
  L('1.3', ['Evaluative adverbs: 毕竟, 反正, 简直', 'Phó từ đánh giá: 毕竟, 反正, 简直'], 'Ba phó từ thể hiện thái độ người nói: sau cùng/dù sao (毕竟), dù thế nào cũng (反正), quả thực/y như (简直).', {
    goals: [['Use ⟦毕竟⟧ to stress a basic fact', 'Dùng ⟦毕竟⟧ để nhấn một sự thật căn bản'], ['Use ⟦反正⟧ for “anyway/in any case”', 'Dùng ⟦反正⟧ cho “dù sao cũng”'], ['Use ⟦简直⟧ for exaggeration', 'Dùng ⟦简直⟧ cho cách nói phóng đại']],
    sec: [
      { h: ['毕竟 — after all', '毕竟 — suy cho cùng'], p: [`⟦毕竟⟧ reminds the listener of a fundamental fact that explains or excuses the situation. It goes before the verb or adjective of the clause, usually the first clause.`, `⟦毕竟⟧ nhắc người nghe một sự thật căn bản giải thích hoặc bào chữa cho tình huống. Đặt trước động từ hoặc tính từ của vế, thường ở vế đầu.`],
        ex: [['他毕竟还是个孩子，别要求太高。', 'Tā bìjìng hái shì ge háizi, bié yāoqiú tài gāo.', 'After all he is still a child, so don’t expect too much.', 'Suy cho cùng cậu bé vẫn là trẻ con, đừng đòi hỏi quá cao.'], ['网上买东西毕竟不能试穿，退货的人很多。', 'Wǎngshàng mǎi dōngxi bìjìng bù néng shìchuān, tuì huò de rén hěn duō.', 'You can’t try things on online, after all, so many people return goods.', 'Mua trên mạng suy cho cùng không thử đồ được nên nhiều người trả hàng.']] },
      { h: ['反正 — anyway, whatever happens', '反正 — dù sao cũng'], p: [`⟦反正⟧ says the result stays the same whatever the circumstances. It often follows a clause with ⟦不管 / 无论⟧ or a plain “whether or not”, and justifies a decision.`, `⟦反正⟧ nói kết quả vẫn thế bất kể hoàn cảnh. Thường đi sau vế có ⟦不管 / 无论⟧ hoặc một “dù có hay không”, và dùng để biện minh cho quyết định.`],
        ex: [['反正明天不上课，我们今晚多逛一会儿吧。', 'Fǎnzhèng míngtiān bú shàngkè, wǒmen jīnwǎn duō guàng yíhuìr ba.', 'Anyway there’s no class tomorrow, so let’s wander a little longer tonight.', 'Dù sao mai không có tiết, tối nay mình đi dạo thêm một lúc nhé.'], ['不管你信不信，反正我信了。', 'Bùguǎn nǐ xìn bu xìn, fǎnzhèng wǒ xìn le.', 'Whether or not you believe it, I do.', 'Bạn tin hay không thì tôi tin rồi.']] },
      { h: ['简直 — simply, practically', '简直 — quả thực, y như'], p: [`⟦简直⟧ expresses a strong, exaggerated impression. It is followed by an evaluation (⟦太…了⟧, ⟦像…一样⟧). Never use it for neutral facts.`, `⟦简直⟧ thể hiện ấn tượng mạnh, phóng đại. Theo sau là một đánh giá (⟦太…了⟧, ⟦像…一样⟧). Không dùng cho sự thật trung tính.`],
        ex: [['这个价格简直太便宜了！', 'Zhège jiàgé jiǎnzhí tài piányi le!', 'This price is just unbelievably cheap!', 'Giá này rẻ không thể tin nổi!'], ['他说得简直像真的一样。', 'Tā shuō de jiǎnzhí xiàng zhēn de yíyàng.', 'The way he tells it, it’s practically real.', 'Anh ta kể y như thật vậy.']] }],
    vocab: [['毕竟', 'bìjìng', 'after all', 'suy cho cùng'], ['反正', 'fǎnzhèng', 'anyway; in any case', 'dù sao'], ['简直', 'jiǎnzhí', 'simply; virtually', 'quả thực'], ['试穿', 'shìchuān', 'to try on', 'mặc thử'], ['逛街', 'guàng jiē', 'to stroll and shop', 'đi dạo phố'], ['在乎', 'zàihu', 'to care about', 'để ý, bận tâm'], ['质量', 'zhìliàng', 'quality', 'chất lượng'], ['包装', 'bāozhuāng', 'packaging', 'bao bì'], ['快递', 'kuàidì', 'express delivery', 'chuyển phát nhanh'], ['评价', 'píngjià', 'review; to evaluate', 'đánh giá']],
    dia: [['A', '你的快递怎么还没到？', 'Nǐ de kuàidì zěnme hái méi dào?', 'Why hasn’t your parcel arrived yet?', 'Sao bưu kiện của bạn vẫn chưa tới?'], ['B', '毕竟是双十一，快递简直堆成山了。', 'Bìjìng shì Shuāng Shíyī, kuàidì jiǎnzhí duī chéng shān le.', 'It’s Singles’ Day after all; parcels are piled up like mountains.', 'Dù sao cũng là ngày 11/11, bưu kiện chất như núi.'], ['A', '你不着急吗？', 'Nǐ bù zháojí ma?', 'Aren’t you worried?', 'Bạn không sốt ruột à?'], ['B', '反正不是急用的东西，慢慢等吧。', 'Fǎnzhèng bú shì jí yòng de dōngxi, mànmàn děng ba.', 'Anyway it’s not something I need urgently; I’ll wait.', 'Dù sao cũng không phải đồ cần gấp, cứ từ từ đợi.']],
    pit: [`Using ⟦简直⟧ with a neutral fact (⟦他简直是学生⟧ is wrong), and putting ⟦反正⟧ at the very end of a sentence. Also: ⟦毕竟⟧ needs the reason it stresses; it does not stand alone.`, `Dùng ⟦简直⟧ cho sự thật trung tính (⟦他简直是学生⟧ sai), và đặt ⟦反正⟧ ở cuối câu. Lưu ý: ⟦毕竟⟧ cần đi kèm lý do mà nó nhấn mạnh, không đứng một mình.`],
    sum: [['⟦毕竟⟧ = after all (basic fact).', '⟦毕竟⟧ = suy cho cùng (sự thật căn bản).'], ['⟦反正⟧ = in any case (same result).', '⟦反正⟧ = dù sao (kết quả không đổi).'], ['⟦简直⟧ = exaggerated evaluation.', '⟦简直⟧ = đánh giá phóng đại.']],
    links: [[GW + 'ASG4V36Q', 'Chinese Grammar Wiki — “after all” with 毕竟', 'Chinese Grammar Wiki — “suy cho cùng” với 毕竟'], [GW + 'ASGZVM27', 'Chinese Grammar Wiki — “anyway” with 反正', 'Chinese Grammar Wiki — “dù sao” với 反正'], [GW + 'ASG8OLAE', 'Chinese Grammar Wiki — “simply” with 简直', 'Chinese Grammar Wiki — “quả thực” với 简直']],
    prac: [['Choose 毕竟/反正/简直: 这家餐厅的菜 ____ 太好吃了！', 'Chọn 毕竟/反正/简直: 这家餐厅的菜 ____ 太好吃了！', '⟦简直⟧ — jiǎnzhí.', '⟦简直⟧ — jiǎnzhí.'], ['Say: “After all he is a beginner, so mistakes are normal.”', 'Nói: “Suy cho cùng anh ấy là người mới, mắc lỗi là bình thường.”', '⟦他毕竟是新手，出错很正常。⟧ Tā bìjìng shì xīnshǒu, chūcuò hěn zhèngcháng.', '⟦他毕竟是新手，出错很正常。⟧ Tā bìjìng shì xīnshǒu, chūcuò hěn zhèngcháng.']] }),
  QZ(1, 'Kiểm tra nhanh chương 1: 与其…不如, 宁可…也不, 何况, 况且, 别说, 毕竟, 反正, 简直.', [
    Q('q1', ['Which means “Rather than A, better B”?', 'Mẫu nào nghĩa “thay vì A thì B hơn”?'], ['与其…不如…', '宁可…也不…', '何况…呢', '反正…'], 0, ['⟦与其 A，不如 B⟧ drops A in favour of B.', '⟦与其 A，不如 B⟧ bỏ A chọn B.']),
    Q('q2', ['在拥挤的地铁里站两个小时，我 ____ 走路回家，也不想坐。', 'Điền: 在拥挤的地铁里站两个小时，我 ____ 走路回家，也不想坐。'], ['与其', '宁可', '何况', '简直'], 1, ['⟦宁可…也不…⟧: accept walking to avoid the metro.', '⟦宁可…也不…⟧: chịu đi bộ để khỏi đi tàu.']),
    Q('q3', ['“打三折” means …', '“打三折” nghĩa là …'], [['30% off', 'Giảm 30%'], ['70% off', 'Giảm 70%'], ['3% off', 'Giảm 3%'], ['300% more', 'Tăng 300%']], 1, ['⟦三折⟧ = pay 30% of the price, i.e. 70% off.', '⟦三折⟧ = trả 30% giá, tức giảm 70%.']),
    Q('q4', ['小孩子都能做，____ 你呢？', 'Điền: 小孩子都能做，____ 你呢？'], ['何况', '反正', '毕竟', '简直'], 0, ['Easy case then ⟦何况…呢⟧.', 'Trường hợp dễ rồi ⟦何况…呢⟧.']),
    Q('q5', ['Which adds “a further reason” only?', 'Từ nào chỉ thêm “một lý do nữa”?'], ['况且', '何况', '别说', '简直'], 0, ['⟦况且⟧ = besides; no easy-to-hard comparison.', '⟦况且⟧ = vả lại; không có so sánh dễ → khó.']),
    Q('q6', ['别说买车，他 ____ 自行车都买不起。', 'Điền: 别说买车，他 ____ 自行车都买不起。'], ['连', '把', '被', '比'], 0, ['⟦别说 A，连 B 都…⟧.', '⟦别说 A，连 B 都…⟧.']),
    Q('q7', ['Which one stresses a basic fact (“after all”)?', 'Từ nào nhấn sự thật căn bản (“suy cho cùng”)?'], ['毕竟', '反正', '简直', '况且'], 0, ['⟦毕竟⟧ = after all.', '⟦毕竟⟧ = suy cho cùng.']),
    Q('q8', ['这个价格 ____ 太便宜了！(strong exaggeration)', 'Điền: 这个价格 ____ 太便宜了！(phóng đại)'], ['简直', '反正', '毕竟', '何况'], 0, ['⟦简直⟧ expresses an exaggerated impression.', '⟦简直⟧ thể hiện ấn tượng phóng đại.']),
  ]) ]);

const c2 = CH(2, 'Education and self-development', 'Giáo dục và phát triển bản thân',
  'Từ vựng học tập; mục đích (以便, 以免, 免得, 好), giả thiết (一旦, 万一, 倘若), song song và kết quả (一面…一面, 同时, 顺便, 从而).', [
  L('2.1', ['Purpose and avoidance: 以便, 以免, 免得, 好', 'Mục đích và tránh: 以便, 以免, 免得, 好'], 'Hai nhóm liên từ nối vế hành động với mục đích (以便, 好) hoặc điều cần tránh (以免, 免得).', {
    goals: [['Link an action to its purpose with ⟦以便⟧ and ⟦好⟧', 'Nối hành động với mục đích bằng ⟦以便⟧ và ⟦好⟧'], ['Say “so as not to” with ⟦以免⟧ and ⟦免得⟧', 'Nói “để khỏi” bằng ⟦以免⟧ và ⟦免得⟧'], ['Learn 10 study words', 'Học 10 từ về học tập']],
    sec: [
      { h: ['以便 / 好 — so that (a positive purpose)', '以便 / 好 — để (mục đích tích cực)'], p: [`The action comes first, the purpose second. ⟦以便⟧ is neutral/written; ⟦好⟧ is the spoken version and goes before the verb of the purpose clause. Unlike ⟦为了⟧ (CIC301), the purpose clause follows the main action.`, `Hành động đứng trước, mục đích đứng sau. ⟦以便⟧ trung tính/văn viết; ⟦好⟧ là khẩu ngữ và đặt trước động từ của vế mục đích. Khác ⟦为了⟧ (CIC301), vế mục đích ở <em>sau</em> hành động chính.`], f: '做法，以便 / 好 + 目的',
        ex: [['我提前预习课文，以便上课时能听懂。', 'Wǒ tíqián yùxí kèwén, yǐbiàn shàngkè shí néng tīng dǒng.', 'I preview the text in advance so that I can follow in class.', 'Tôi xem trước bài để lên lớp nghe hiểu được.'], ['请把重点记在笔记本上，以便考试前复习。', 'Qǐng bǎ zhòngdiǎn jì zài bǐjìběn shàng, yǐbiàn kǎoshì qián fùxí.', 'Please note down the key points so you can review before the exam.', 'Hãy ghi ý chính vào vở để ôn trước kỳ thi.'], ['你把地址写下来，我好去找你。', 'Nǐ bǎ dìzhǐ xiě xiàlái, wǒ hǎo qù zhǎo nǐ.', 'Write the address down so I can come find you.', 'Bạn ghi địa chỉ ra để tôi tiện đến tìm.']] },
      { h: ['以免 / 免得 — so as to avoid', '以免 / 免得 — để khỏi, kẻo'], p: [`Both introduce a bad result that the first clause is meant to prevent. ⟦以免⟧ is more written; ⟦免得⟧ is spoken and may take a new subject. Never put a good result here.`, `Cả hai dẫn ra kết quả xấu mà vế đầu nhằm ngăn chặn. ⟦以免⟧ thiên văn viết; ⟦免得⟧ khẩu ngữ và có thể đổi chủ ngữ. Không đặt kết quả tốt ở đây.`], f: '做法，以免 / 免得 + 坏结果',
        ex: [['早点儿出门，以免迟到。', 'Zǎo diǎnr chūmén, yǐmiǎn chídào.', 'Leave a bit earlier so as not to be late.', 'Ra khỏi nhà sớm một chút để khỏi trễ.'], ['把手机调成静音，免得影响别人。', 'Bǎ shǒujī tiáo chéng jìngyīn, miǎnde yǐngxiǎng biérén.', 'Put your phone on silent so you don’t disturb others.', 'Chuyển điện thoại sang im lặng kẻo ảnh hưởng người khác.'], ['多检查几遍，免得交上去以后发现错误。', 'Duō jiǎnchá jǐ biàn, miǎnde jiāo shàngqù yǐhòu fāxiàn cuòwù.', 'Check it a few more times so you won’t find mistakes after handing it in.', 'Kiểm tra thêm vài lần kẻo nộp rồi mới thấy lỗi.']] }],
    vocab: [['以便', 'yǐbiàn', 'so that', 'để (tiện)'], ['以免', 'yǐmiǎn', 'so as not to', 'để khỏi'], ['免得', 'miǎnde', 'lest', 'kẻo'], ['预习', 'yùxí', 'to preview a lesson', 'xem trước bài'], ['复习', 'fùxí', 'to review', 'ôn tập'], ['笔记', 'bǐjì', 'notes', 'ghi chép'], ['重点', 'zhòngdiǎn', 'key point', 'trọng điểm'], ['提前', 'tíqián', 'in advance', 'sớm hơn, trước'], ['报名', 'bào míng', 'to sign up', 'đăng ký tham gia'], ['奖学金', 'jiǎngxuéjīn', 'scholarship', 'học bổng']],
    dia: [['A', '你为什么每天都早起？', 'Nǐ wèishénme měi tiān dōu zǎo qǐ?', 'Why do you get up early every day?', 'Sao ngày nào bạn cũng dậy sớm?'], ['B', '我想去图书馆占座位，以便专心复习。', 'Wǒ xiǎng qù túshūguǎn zhàn zuòwèi, yǐbiàn zhuānxīn fùxí.', 'I go to the library to grab a seat so I can revise in peace.', 'Tôi đến thư viện giữ chỗ để ôn bài cho tập trung.'], ['A', '那你要带水，免得口渴。', 'Nà nǐ yào dài shuǐ, miǎnde kǒu kě.', 'Then bring water so you don’t get thirsty.', 'Vậy mang theo nước kẻo khát.'], ['B', '好的，我还要带充电器，以免手机没电。', 'Hǎo de, wǒ hái yào dài chōngdiànqì, yǐmiǎn shǒujī méi diàn.', 'OK, I’ll also bring a charger so the phone doesn’t run out.', 'Ừ, tôi còn mang sạc để điện thoại khỏi hết pin.']],
    pit: [`Using ⟦以免⟧ for a good result (⟦我早起，以免有时间学习⟧ is wrong — use ⟦以便⟧), and putting the purpose clause <em>before</em> the action as with ⟦为了⟧.`, `Dùng ⟦以免⟧ cho kết quả tốt (⟦我早起，以免有时间学习⟧ sai — phải dùng ⟦以便⟧), và đặt vế mục đích <em>trước</em> hành động như ⟦为了⟧.`],
    sum: [['⟦以便 / 好⟧: action, then positive purpose.', '⟦以便 / 好⟧: hành động rồi mục đích tốt.'], ['⟦以免 / 免得⟧: action to prevent a bad result.', '⟦以免 / 免得⟧: hành động để ngăn kết quả xấu.']],
    links: [[GW + 'ASG18JOA', 'Chinese Grammar Wiki — purpose with 好', 'Chinese Grammar Wiki — mục đích với 好'], [GW + 'ASGINBWJ', 'Chinese Grammar Wiki — “as much as possible” with 尽量', 'Chinese Grammar Wiki — “hết sức có thể” với 尽量'], [GW + 'HSK_5_grammar_points', 'Chinese Grammar Wiki — HSK 5 grammar points', 'Chinese Grammar Wiki — ngữ pháp HSK 5']],
    prac: [['Complete: 出门带伞，____ 淋雨。', 'Điền: 出门带伞，____ 淋雨。', '⟦以免⟧ or ⟦免得⟧ (bad result).', '⟦以免⟧ hoặc ⟦免得⟧ (kết quả xấu).'], ['Say: “Take notes so that I can review later.”', 'Nói: “Ghi chép để sau này tôi ôn tập.”', '⟦做笔记，以便以后复习。⟧ Zuò bǐjì, yǐbiàn yǐhòu fùxí.', '⟦做笔记，以便以后复习。⟧ Zuò bǐjì, yǐbiàn yǐhòu fùxí.']] }),
  L('2.2', ['Serious hypotheses: 一旦, 万一, 倘若', 'Giả thiết nghiêm trọng: 一旦, 万一, 倘若'], 'Ba cách nói “nếu”: 一旦 (khi đã xảy ra thì không đổi được), 万一 (rủi ro thấp nhưng nặng), 倘若 (nếu — văn viết).', {
    goals: [['Use ⟦一旦…就…⟧ for “once… then…”', 'Dùng ⟦一旦…就…⟧ cho “một khi… thì…”'], ['Use ⟦万一⟧ for unlikely risks', 'Dùng ⟦万一⟧ cho rủi ro ít khả năng'], ['Use ⟦倘若⟧ as formal “if”', 'Dùng ⟦倘若⟧ như “nếu” trang trọng']],
    sec: [
      { h: ['一旦…就… — once it happens', '一旦…就… — một khi đã…'], p: [`⟦一旦⟧ sets a condition whose consequence is serious or hard to reverse. The result clause almost always has ⟦就⟧. It is more forceful than ⟦如果⟧.`, `⟦一旦⟧ đặt điều kiện mà hậu quả nghiêm trọng hoặc khó đảo ngược. Vế kết quả hầu như luôn có ⟦就⟧. Mạnh hơn ⟦如果⟧.`], f: '一旦 + 条件，(就) + 结果',
        ex: [['一旦养成坏习惯，就很难改掉。', 'Yídàn yǎngchéng huài xíguàn, jiù hěn nán gǎidiào.', 'Once a bad habit forms, it is hard to get rid of.', 'Một khi đã có thói quen xấu thì rất khó bỏ.'], ['一旦错过报名时间，你就不能参加考试了。', 'Yídàn cuòguò bàomíng shíjiān, nǐ jiù bù néng cānjiā kǎoshì le.', 'Once you miss the sign-up deadline, you can’t take the exam.', 'Một khi lỡ hạn đăng ký thì bạn không thể dự thi.']] },
      { h: ['万一 — what if (a small chance of a bad event)', '万一 — nhỡ (khả năng nhỏ, hậu quả xấu)'], p: [`⟦万一⟧ talks about an event that is unlikely but unwelcome, and is used for precautions. It can also begin a question: ⟦万一…呢？⟧.`, `⟦万一⟧ nói về sự việc ít khả năng nhưng không mong muốn, dùng khi phòng ngừa. Cũng có thể mở đầu câu hỏi: ⟦万一…呢？⟧.`], f: '万一 + 坏事，(就) + 怎么办 / 对策',
        ex: [['万一考试没通过，你打算怎么办？', 'Wànyī kǎoshì méi tōngguò, nǐ dǎsuàn zěnme bàn?', 'What if you fail the exam — what will you do?', 'Nhỡ thi không đậu, bạn định làm sao?'], ['多带一份复印件，万一弄丢了呢。', 'Duō dài yí fèn fùyìnjiàn, wànyī nòng diū le ne.', 'Bring an extra copy, in case you lose it.', 'Mang thêm một bản photo, nhỡ làm mất thì sao.']] },
      { h: ['倘若 — formal “if”', '倘若 — “nếu” trang trọng'], p: [`⟦倘若⟧ = ⟦如果⟧ in written Chinese (speeches, essays). It pairs with ⟦就 / 那么 / 便⟧. Do not use it in casual chat.`, `⟦倘若⟧ = ⟦如果⟧ trong văn viết (diễn văn, bài luận), đi với ⟦就 / 那么 / 便⟧. Không dùng khi nói chuyện thân mật.`],
        ex: [['倘若你有困难，随时来找我。', 'Tǎngruò nǐ yǒu kùnnan, suíshí lái zhǎo wǒ.', 'Should you have difficulty, come to me at any time.', 'Nếu bạn gặp khó khăn, cứ đến tìm tôi bất cứ lúc nào.']] }],
    vocab: [['一旦', 'yídàn', 'once; in case', 'một khi'], ['万一', 'wànyī', 'in case; if by chance', 'nhỡ, lỡ'], ['倘若', 'tǎngruò', 'if (formal)', 'nếu (văn viết)'], ['养成', 'yǎngchéng', 'to form (a habit)', 'hình thành'], ['习惯', 'xíguàn', 'habit', 'thói quen'], ['错过', 'cuòguò', 'to miss', 'bỏ lỡ'], ['挂科', 'guà kē', 'to fail a course (colloq.)', 'rớt môn'], ['补考', 'bǔkǎo', 'resit exam', 'thi lại'], ['后果', 'hòuguǒ', 'consequence', 'hậu quả'], ['毕业', 'bì yè', 'to graduate', 'tốt nghiệp']],
    dia: [['A', '我不想每天复习，反正考前再突击。', 'Wǒ bù xiǎng měi tiān fùxí, fǎnzhèng kǎo qián zài tūjī.', 'I don’t want to revise daily; I’ll cram before the exam.', 'Tôi không muốn ôn mỗi ngày, trước thi nước rút là được.'], ['B', '万一来不及呢？', 'Wànyī lái bu jí ne?', 'What if you run out of time?', 'Nhỡ không kịp thì sao?'], ['A', '那我就得补考了。', 'Nà wǒ jiù děi bǔkǎo le.', 'Then I’d have to resit.', 'Thì tôi phải thi lại.'], ['B', '一旦挂科，毕业时间就会推迟，后果很严重。', 'Yídàn guà kē, bìyè shíjiān jiù huì tuīchí, hòuguǒ hěn yánzhòng.', 'Once you fail, graduation is delayed — serious consequences.', 'Một khi rớt môn, thời gian tốt nghiệp sẽ bị lùi, hậu quả nghiêm trọng.']],
    pit: [`Using ⟦万一⟧ for a likely, welcome event (⟦万一明天放假⟧ sounds odd if you hope for it), and forgetting ⟦就⟧ after ⟦一旦⟧.`, `Dùng ⟦万一⟧ cho việc dễ xảy ra hay đáng mong (⟦万一明天放假⟧ nghe lạ nếu bạn mong nghỉ), và quên ⟦就⟧ sau ⟦一旦⟧.`],
    sum: [['⟦一旦…就…⟧: once it happens, serious result.', '⟦一旦…就…⟧: một khi xảy ra thì hậu quả nặng.'], ['⟦万一⟧: unlikely bad event, precaution.', '⟦万一⟧: việc xấu ít khả năng, phòng ngừa.'], ['⟦倘若⟧: formal “if”.', '⟦倘若⟧: “nếu” trang trọng.']],
    links: [[GW + 'ASGU3ZV1', 'Chinese Grammar Wiki — 一旦…就…', 'Chinese Grammar Wiki — 一旦…就…'], [GW + 'ASG25773', 'Chinese Grammar Wiki — “what if” with 万一', 'Chinese Grammar Wiki — “nhỡ” với 万一'], [GW + 'ASGHNDX4', 'Chinese Grammar Wiki — “if… then…” with 假如', 'Chinese Grammar Wiki — “nếu… thì…” với 假如']],
    prac: [['Say: “Once you start, you must finish.”', 'Nói: “Một khi đã bắt đầu thì phải làm cho xong.”', '⟦一旦开始，就要做完。⟧ Yídàn kāishǐ, jiù yào zuò wán.', '⟦一旦开始，就要做完。⟧ Yídàn kāishǐ, jiù yào zuò wán.'], ['Say: “Bring a pen, in case the exam room has none.”', 'Nói: “Mang bút theo, nhỡ phòng thi không có.”', '⟦带支笔吧，万一考场没有呢。⟧ Dài zhī bǐ ba, wànyī kǎochǎng méiyǒu ne.', '⟦带支笔吧，万一考场没有呢。⟧ Dài zhī bǐ ba, wànyī kǎochǎng méiyǒu ne.']] }),
  L('2.3', ['Doing two things and linking results: 一面…一面…, 同时, 顺便, 从而', 'Làm hai việc và nối kết quả: 一面…一面…, 同时, 顺便, 从而'], 'Diễn đạt hai hành động song song (一面…一面, 同时), làm thêm việc tiện thể (顺便) và kết quả suy ra (从而).', {
    goals: [['Describe parallel actions with ⟦一面…一面…⟧ and ⟦同时⟧', 'Miêu tả hành động song song với ⟦一面…一面…⟧ và ⟦同时⟧'], ['Say “while at it” with ⟦顺便⟧', 'Nói “tiện thể” bằng ⟦顺便⟧'], ['Show a result with ⟦从而⟧', 'Chỉ kết quả bằng ⟦从而⟧']],
    sec: [
      { h: ['一面…一面… and 同时', '一面…一面… và 同时'], p: [`⟦一面 A，一面 B⟧ puts two actions side by side by the same subject (like ⟦一边…一边…⟧ but more written). ⟦同时⟧ means “at the same time”, and can link two clauses or give the time of a second job.`, `⟦一面 A，一面 B⟧ đặt hai hành động song song cùng chủ ngữ (giống ⟦一边…一边…⟧ nhưng văn viết hơn). ⟦同时⟧ nghĩa “đồng thời”, nối hai vế hoặc nêu thời điểm của việc thứ hai.`], f: '一面 + 动作 1，一面 + 动作 2',
        ex: [['她一面上学，一面打工。', 'Tā yímiàn shàngxué, yímiàn dǎgōng.', 'She studies while working part-time.', 'Cô ấy vừa đi học vừa làm thêm.'], ['这门课提高听力，同时也练习口语。', 'Zhè mén kè tígāo tīnglì, tóngshí yě liànxí kǒuyǔ.', 'This course improves listening and, at the same time, practises speaking.', 'Môn này nâng cao nghe, đồng thời luyện nói.']] },
      { h: ['顺便 — while you are at it', '顺便 — tiện thể'], p: [`⟦顺便⟧ introduces a minor extra action done on the way. It goes before the second verb.`, `⟦顺便⟧ dẫn ra việc phụ làm thêm trên đường. Đặt trước động từ thứ hai.`],
        ex: [['我去图书馆还书，顺便借了两本小说。', 'Wǒ qù túshūguǎn huán shū, shùnbiàn jièle liǎng běn xiǎoshuō.', 'I went to return books and borrowed two novels while there.', 'Tôi đến thư viện trả sách, tiện thể mượn hai cuốn tiểu thuyết.']] },
      { h: ['从而 — thereby', '从而 — do đó, nhờ vậy'], p: [`⟦从而⟧ links a result to the previous action, usually with the <em>same subject</em> and in written style (articles, reports). The result is a consequence, often an improvement.`, `⟦从而⟧ nối kết quả với hành động trước, thường <em>cùng chủ ngữ</em> và phong cách văn viết (bài báo, báo cáo). Kết quả là hệ quả, thường là sự cải thiện.`], f: '做法，从而 + 结果',
        ex: [['老师改变了教学方法，从而提高了学生的兴趣。', 'Lǎoshī gǎibiànle jiàoxué fāngfǎ, cóng’ér tígāole xuésheng de xìngqù.', 'The teacher changed the method, thereby raising interest.', 'Thầy đổi phương pháp dạy, nhờ đó nâng cao hứng thú của sinh viên.'], ['多读多写，从而提高写作能力。', 'Duō dú duō xiě, cóng’ér tígāo xiězuò nénglì.', 'Read and write more, thereby improving writing ability.', 'Đọc nhiều viết nhiều để nâng cao khả năng viết.']] }],
    vocab: [['一面', 'yímiàn', 'on the one hand / while', 'một mặt, vừa'], ['同时', 'tóngshí', 'at the same time', 'đồng thời'], ['顺便', 'shùnbiàn', 'in passing', 'tiện thể'], ['从而', 'cóng’ér', 'thereby', 'do đó'], ['提高', 'tígāo', 'to raise; improve', 'nâng cao'], ['兴趣', 'xìngqù', 'interest', 'hứng thú'], ['教学', 'jiàoxué', 'teaching', 'giảng dạy'], ['方法', 'fāngfǎ', 'method', 'phương pháp'], ['打工', 'dǎ gōng', 'to work part-time', 'làm thêm'], ['实习', 'shíxí', 'internship', 'thực tập']],
    dia: [['A', '你一面实习，一面写毕业论文，累不累？', 'Nǐ yímiàn shíxí, yímiàn xiě bìyè lùnwén, lèi bu lèi?', 'Doing an internship and writing a thesis — aren’t you tired?', 'Vừa thực tập vừa viết luận văn, bạn có mệt không?'], ['B', '有点累，但我可以积累经验，同时也赚一点钱。', 'Yǒudiǎn lèi, dàn wǒ kěyǐ jīlěi jīngyàn, tóngshí yě zhuàn yìdiǎn qián.', 'A bit, but I gain experience and earn a little at the same time.', 'Hơi mệt, nhưng tôi tích luỹ kinh nghiệm, đồng thời kiếm chút tiền.'], ['A', '下班后你能顺便帮我买本词典吗？', 'Xiàbān hòu nǐ néng shùnbiàn bāng wǒ mǎi běn cídiǎn ma?', 'After work, could you buy me a dictionary on your way?', 'Tan làm bạn tiện thể mua giúp tôi cuốn từ điển được không?'], ['B', '没问题。', 'Méi wèntí.', 'No problem.', 'Không vấn đề.']],
    pit: [`Using ⟦从而⟧ with a different subject in speech (⟦我迟到了，从而老师生气了⟧ is unnatural); and using ⟦顺便⟧ for the main purpose of a trip — it marks only a side action.`, `Dùng ⟦从而⟧ với chủ ngữ khác trong lời nói (⟦我迟到了，从而老师生气了⟧ không tự nhiên); và dùng ⟦顺便⟧ cho mục đích chính của chuyến đi — nó chỉ chỉ việc phụ.`],
    sum: [['⟦一面 A，一面 B⟧: two parallel actions.', '⟦一面 A，一面 B⟧: hai hành động song song.'], ['⟦顺便⟧: a minor extra action.', '⟦顺便⟧: một việc phụ làm thêm.'], ['⟦从而⟧: written “thereby”.', '⟦从而⟧: “do đó” trong văn viết.']],
    links: [[GW + 'ASG1QB4K', 'Chinese Grammar Wiki — simultaneous actions with 一面', 'Chinese Grammar Wiki — hành động đồng thời với 一面'], [GW + 'ASG5334C', 'Chinese Grammar Wiki — “while you’re at it” with 顺便', 'Chinese Grammar Wiki — “tiện thể” với 顺便'], ['https://www.hsk.academy/en/hsk-5-vocabulary-list', 'HSK Academy — HSK 5 vocabulary list', 'HSK Academy — từ vựng HSK 5']],
    prac: [['Say: “She watches videos while doing her homework.”', 'Nói: “Cô ấy vừa xem video vừa làm bài tập.”', '⟦她一面看视频，一面做作业。⟧ Tā yímiàn kàn shìpín, yímiàn zuò zuòyè.', '⟦她一面看视频，一面做作业。⟧ Tā yímiàn kàn shìpín, yímiàn zuò zuòyè.'], ['Join with 从而: 他每天练习 / 他的发音进步了.', 'Nối bằng 从而: 他每天练习 / 他的发音进步了.', '⟦他每天练习，从而使发音进步了。⟧ Tā měi tiān liànxí, cóng’ér shǐ fāyīn jìnbù le.', '⟦他每天练习，从而使发音进步了。⟧ Tā měi tiān liànxí, cóng’ér shǐ fāyīn jìnbù le.']] }),
  QZ(2, 'Kiểm tra nhanh chương 2: 以便, 以免, 免得, 一旦, 万一, 倘若, 一面…一面, 顺便, 从而.', [
    Q('q1', ['Which word introduces a purpose AFTER the main action?', 'Từ nào dẫn mục đích đứng SAU hành động chính?'], ['以便', '为了', '万一', '倘若'], 0, ['⟦以便⟧ follows the action.', '⟦以便⟧ đứng sau hành động.']),
    Q('q2', ['带伞吧，____ 下雨淋湿。', 'Điền: 带伞吧，____ 下雨淋湿。'], ['以便', '以免', '从而', '同时'], 1, ['Bad result to avoid: ⟦以免⟧.', 'Kết quả xấu cần tránh: ⟦以免⟧.']),
    Q('q3', ['____ 养成坏习惯，就很难改掉。', 'Điền: ____ 养成坏习惯，就很难改掉。'], ['一旦', '万一', '以便', '顺便'], 0, ['⟦一旦…就…⟧ = once… then.', '⟦一旦…就…⟧ = một khi… thì.']),
    Q('q4', ['Which suits “What if I lose the key?”', 'Từ nào hợp “Nhỡ tôi làm mất chìa khoá thì sao?”'], ['万一', '从而', '同时', '以便'], 0, ['⟦万一⟧ for unlikely risks.', '⟦万一⟧ cho rủi ro ít khả năng.']),
    Q('q5', ['Which is formal “if”?', 'Từ nào là “nếu” trang trọng?'], ['倘若', '好', '顺便', '免得'], 0, ['⟦倘若⟧ is formal.', '⟦倘若⟧ trang trọng.']),
    Q('q6', ['她 ____ 上学，一面打工。', 'Điền: 她 ____ 上学，一面打工。'], ['一面', '一旦', '一共', '一定'], 0, ['⟦一面…一面…⟧.', '⟦一面…一面…⟧.']),
    Q('q7', ['去超市时 ____ 买了点水果。', 'Điền: 去超市时 ____ 买了点水果。'], ['顺便', '从而', '万一', '以免'], 0, ['Minor extra action: ⟦顺便⟧.', 'Việc phụ làm thêm: ⟦顺便⟧.']),
    Q('q8', ['多练习，____ 提高口语水平。', 'Điền: 多练习，____ 提高口语水平。'], ['从而', '万一', '倘若', '免得'], 0, ['⟦从而⟧ = thereby (result).', '⟦从而⟧ = do đó (kết quả).']),
  ]) ]);

const c3 = CH(3, 'Workplace and career', 'Công việc và nghề nghiệp',
  'Từ vựng nơi làm việc; đề xuất và nghi ngờ (不妨, 何必, 未必), nhấn mạnh toàn thể và lý do (凡是, 之所以, 非…不可), nêu góc nhìn (对…而言, 就…而言, 在…看来, 至于).', [
  L('3.1', ['Suggesting and doubting: 不妨, 何必, 未必', 'Đề xuất và nghi ngờ: 不妨, 何必, 未必'], 'Ba phó từ giọng điệu: khuyên nhẹ (不妨), phản bác “cần gì” (何必), nghi ngờ “chưa chắc” (未必).', {
    goals: [['Give gentle advice with ⟦不妨⟧', 'Khuyên nhẹ nhàng bằng ⟦不妨⟧'], ['Argue “no need to” with ⟦何必⟧', 'Phản bác “cần gì phải” bằng ⟦何必⟧'], ['Express doubt with ⟦未必⟧', 'Bày tỏ nghi ngờ bằng ⟦未必⟧']],
    sec: [
      { h: ['不妨 — “you might as well”', '不妨 — “cứ thử… cũng không sao”'], p: [`⟦不妨 + verb⟧ suggests something harmless and possibly useful. The tone is friendly, softer than ⟦应该⟧. Usually used to the listener or in a general suggestion.`, `⟦不妨 + động từ⟧ gợi ý việc vô hại và có thể hữu ích. Giọng thân thiện, nhẹ hơn ⟦应该⟧. Thường nói với người nghe hoặc gợi ý chung.`],
        ex: [['你不妨先试用一个月，看看合不合适。', 'Nǐ bùfáng xiān shìyòng yí gè yuè, kànkan hé bu héshì.', 'You might try it for a month first to see whether it suits you.', 'Bạn cứ thử việc một tháng xem có hợp không.'], ['有问题不妨直接跟经理谈谈。', 'Yǒu wèntí bùfáng zhíjiē gēn jīnglǐ tántan.', 'If there is a problem, you may as well talk to the manager directly.', 'Có vấn đề thì cứ nói thẳng với quản lý.']] },
      { h: ['何必 — “why bother?”', '何必 — “cần gì phải”'], p: [`⟦何必 + verb⟧ is a rhetorical question: there is no need to do it. The sentence usually ends with ⟦呢⟧ or ⟦呀⟧. It is used to console or to criticise gently.`, `⟦何必 + động từ⟧ là câu hỏi tu từ: không cần phải làm. Câu thường kết thúc bằng ⟦呢⟧ hoặc ⟦呀⟧. Dùng để an ủi hoặc chê nhẹ.`],
        ex: [['这点小事，何必生气呢？', 'Zhè diǎn xiǎoshì, hébì shēngqì ne?', 'Why get angry over such a small thing?', 'Chuyện nhỏ vậy, cần gì phải giận.'], ['时间还早，何必那么着急？', 'Shíjiān hái zǎo, hébì nàme zháojí?', 'It’s still early — no need to rush so much.', 'Còn sớm mà, cần gì vội thế.']] },
      { h: ['未必 — “not necessarily”', '未必 — “chưa chắc”'], p: [`⟦未必⟧ partially denies a common assumption. It is weaker than ⟦不⟧: the speaker is unsure rather than certain it is false. Compare ⟦不一定⟧ (spoken).`, `⟦未必⟧ phủ định một phần giả định phổ biến. Nhẹ hơn ⟦不⟧: người nói không chắc chứ chưa khẳng định là sai. Khẩu ngữ tương đương ⟦不一定⟧.`],
        ex: [['工资高的工作未必适合你。', 'Gōngzī gāo de gōngzuò wèibì shìhé nǐ.', 'A well-paid job is not necessarily right for you.', 'Công việc lương cao chưa chắc hợp với bạn.'], ['名牌大学毕业的人未必能力强。', 'Míngpái dàxué bìyè de rén wèibì nénglì qiáng.', 'Graduates of famous universities are not necessarily capable.', 'Người tốt nghiệp trường danh tiếng chưa chắc giỏi.']] }],
    vocab: [['不妨', 'bùfáng', 'might as well', 'cứ… cũng được'], ['何必', 'hébì', 'why bother', 'cần gì phải'], ['未必', 'wèibì', 'not necessarily', 'chưa chắc'], ['试用', 'shìyòng', 'probation; to try out', 'thử việc'], ['经理', 'jīnglǐ', 'manager', 'quản lý'], ['薪水', 'xīnshui', 'salary', 'tiền lương'], ['福利', 'fúlì', 'benefits', 'phúc lợi'], ['职位', 'zhíwèi', 'position', 'vị trí công việc'], ['升职', 'shēng zhí', 'to be promoted', 'thăng chức'], ['跳槽', 'tiào cáo', 'to switch jobs', 'nhảy việc']],
    dia: [['A', '我想跳槽，现在的薪水太低了。', 'Wǒ xiǎng tiàocáo, xiànzài de xīnshui tài dī le.', 'I want to change jobs; my pay is too low.', 'Tôi muốn nhảy việc, lương hiện tại thấp quá.'], ['B', '薪水高未必就好，你不妨先了解一下福利。', 'Xīnshui gāo wèibì jiù hǎo, nǐ bùfáng xiān liǎojiě yíxià fúlì.', 'High pay isn’t necessarily better; look into the benefits first.', 'Lương cao chưa chắc đã tốt, bạn cứ tìm hiểu phúc lợi trước.'], ['A', '可是我不想再等了。', 'Kěshì wǒ bù xiǎng zài děng le.', 'But I don’t want to wait any more.', 'Nhưng tôi không muốn chờ nữa.'], ['B', '何必这么急？先和经理谈谈吧。', 'Hébì zhème jí? Xiān hé jīnglǐ tántan ba.', 'Why the rush? Talk to your manager first.', 'Cần gì gấp thế? Nói chuyện với quản lý trước đã.']],
    pit: [`Using ⟦何必⟧ without the rhetorical tone, or with a negative (⟦何必不去⟧ is wrong: ⟦何必⟧ already means “no need”). Also ⟦未必⟧ is not a full negation: ⟦他未必来⟧ = “he may not come”, not “he won’t come”.`, `Dùng ⟦何必⟧ không có giọng tu từ, hoặc thêm phủ định (⟦何必不去⟧ sai: ⟦何必⟧ đã có nghĩa “không cần”). Và ⟦未必⟧ không phải phủ định hoàn toàn: ⟦他未必来⟧ = “anh ấy chưa chắc đến”, không phải “sẽ không đến”.`],
    sum: [['⟦不妨⟧ gentle suggestion.', '⟦不妨⟧ gợi ý nhẹ.'], ['⟦何必…呢⟧ rhetorical “no need”.', '⟦何必…呢⟧ tu từ “không cần”.'], ['⟦未必⟧ = not necessarily.', '⟦未必⟧ = chưa chắc.']],
    links: [[GW + 'ASGDFQP7', 'Chinese Grammar Wiki — “how about” with 要不', 'Chinese Grammar Wiki — “hay là” với 要不'], [GW + 'ASGZ8MJM', 'Chinese Grammar Wiki — “just do it” with 干脆', 'Chinese Grammar Wiki — “thôi thì” với 干脆'], [GW + 'HSK_5_grammar_points', 'Chinese Grammar Wiki — HSK 5 grammar points', 'Chinese Grammar Wiki — ngữ pháp HSK 5']],
    prac: [['Say: “No need to be nervous.”', 'Nói: “Cần gì phải căng thẳng.”', '⟦何必紧张呢？⟧ Hébì jǐnzhāng ne?', '⟦何必紧张呢？⟧ Hébì jǐnzhāng ne?'], ['Say: “Expensive things are not necessarily good.”', 'Nói: “Đồ đắt chưa chắc đã tốt.”', '⟦贵的东西未必好。⟧ Guì de dōngxi wèibì hǎo.', '⟦贵的东西未必好。⟧ Guì de dōngxi wèibì hǎo.']] }),
  L('3.2', ['Rules and reasons: 凡是, 之所以, 非…不可', 'Quy định và lý do: 凡是, 之所以, 非…不可'], 'Ba mẫu hay dùng trong văn bản công việc: mọi trường hợp (凡是…都), đảo lý do (之所以…是因为), bắt buộc (非…不可).', {
    goals: [['Cover a whole class with ⟦凡是…都…⟧', 'Bao quát cả một nhóm với ⟦凡是…都…⟧'], ['Put the result first with ⟦之所以…是因为…⟧', 'Đưa kết quả lên trước với ⟦之所以…是因为…⟧'], ['Express a firm requirement with ⟦非…不可⟧', 'Diễn đạt yêu cầu chắc chắn với ⟦非…不可⟧']],
    sec: [
      { h: ['凡是…都… — every, without exception', '凡是…都… — mọi, không trừ ai'], p: [`⟦凡是⟧ + a noun phrase marks the whole group; the main clause must contain ⟦都⟧. It is common in rules and notices.`, `⟦凡是⟧ + cụm danh từ chỉ cả nhóm; vế chính phải có ⟦都⟧. Rất hay gặp trong quy định, thông báo.`], f: '凡是 + 范围，都 + 结果',
        ex: [['凡是公司的员工，都要遵守这个规定。', 'Fánshì gōngsī de yuángōng, dōu yào zūnshǒu zhège guīdìng.', 'All employees of the company must follow this rule.', 'Mọi nhân viên công ty đều phải tuân thủ quy định này.'], ['凡是我能做的，我都愿意帮你。', 'Fánshì wǒ néng zuò de, wǒ dōu yuànyì bāng nǐ.', 'Whatever I can do, I’m willing to help you with.', 'Việc gì tôi làm được tôi đều sẵn lòng giúp bạn.']] },
      { h: ['之所以…是因为… — the reason why', '之所以…是因为… — sở dĩ… là vì…'], p: [`The <em>result</em> is stated first in ⟦之所以…⟧ and the <em>cause</em> follows with ⟦是因为…⟧ (or ⟦是由于…⟧). Do not also use ⟦所以⟧ in the same sentence.`, `<em>Kết quả</em> nêu trước với ⟦之所以…⟧, <em>nguyên nhân</em> theo sau với ⟦是因为…⟧ (hoặc ⟦是由于…⟧). Không dùng thêm ⟦所以⟧ trong cùng câu.`], f: '之所以 + 结果，是因为 + 原因',
        ex: [['他之所以能升职，是因为工作认真。', 'Tā zhīsuǒyǐ néng shēngzhí, shì yīnwèi gōngzuò rènzhēn.', 'The reason he was promoted is that he works conscientiously.', 'Sở dĩ anh ấy được thăng chức là vì làm việc nghiêm túc.'], ['公司之所以招人，是因为业务增加了。', 'Gōngsī zhīsuǒyǐ zhāo rén, shì yīnwèi yèwù zēngjiā le.', 'The company is hiring because business has grown.', 'Sở dĩ công ty tuyển người là vì công việc tăng lên.']] },
      { h: ['非…不可 — must', '非…不可 — nhất định phải'], p: [`⟦非 + verb + 不可⟧ says it is absolutely necessary or someone insists on it (the original double negative: “not doing it is not acceptable”). Often with ⟦不行⟧ or ⟦不成⟧ in speech.`, `⟦非 + động từ + 不可⟧ nói điều tuyệt đối cần thiết hoặc ai đó nhất quyết làm (phủ định kép: “không làm thì không được”). Khẩu ngữ hay thay bằng ⟦不行⟧, ⟦不成⟧.`], f: '非 + 动词 + 不可',
        ex: [['这个项目非你来负责不可。', 'Zhège xiàngmù fēi nǐ lái fùzé bùkě.', 'You absolutely must take charge of this project.', 'Dự án này nhất định phải do bạn phụ trách.'], ['我今天非把报告写完不可。', 'Wǒ jīntiān fēi bǎ bàogào xiě wán bùkě.', 'I must finish the report today.', 'Hôm nay tôi nhất định phải viết xong báo cáo.']] }],
    vocab: [['凡是', 'fánshì', 'every; all', 'mọi, hễ là'], ['之所以', 'zhīsuǒyǐ', 'the reason why', 'sở dĩ'], ['非…不可', 'fēi…bùkě', 'must', 'nhất định phải'], ['遵守', 'zūnshǒu', 'to abide by', 'tuân thủ'], ['规定', 'guīdìng', 'regulation', 'quy định'], ['员工', 'yuángōng', 'employee', 'nhân viên'], ['项目', 'xiàngmù', 'project', 'dự án'], ['负责', 'fùzé', 'to be responsible for', 'phụ trách'], ['合同', 'hétong', 'contract', 'hợp đồng'], ['加班', 'jiā bān', 'to work overtime', 'tăng ca']],
    dia: [['A', '今晚的会议非你参加不可吗？', 'Jīnwǎn de huìyì fēi nǐ cānjiā bùkě ma?', 'Do you absolutely have to attend tonight’s meeting?', 'Cuộc họp tối nay nhất định phải có bạn à?'], ['B', '对，凡是这个项目的负责人都要到。', 'Duì, fánshì zhège xiàngmù de fùzérén dōu yào dào.', 'Yes, everyone in charge of this project has to be there.', 'Đúng, hễ là người phụ trách dự án này đều phải có mặt.'], ['A', '公司之所以加班开会，是因为客户明天就来。', 'Gōngsī zhīsuǒyǐ jiābān kāi huì, shì yīnwèi kèhù míngtiān jiù lái.', 'The company is meeting overtime because the client comes tomorrow.', 'Sở dĩ công ty họp tăng ca là vì mai khách hàng đến.'], ['B', '明白了，我一定准时到。', 'Míngbai le, wǒ yídìng zhǔnshí dào.', 'Understood, I’ll be there on time.', 'Hiểu rồi, tôi sẽ đến đúng giờ.']],
    pit: [`Omitting ⟦都⟧ after ⟦凡是⟧, adding ⟦所以⟧ in a ⟦之所以⟧ sentence (⟦之所以…所以…⟧ is wrong), and leaving out ⟦不可⟧ from ⟦非…不可⟧.`, `Quên ⟦都⟧ sau ⟦凡是⟧, thêm ⟦所以⟧ vào câu ⟦之所以⟧ (⟦之所以…所以…⟧ sai) và bỏ mất ⟦不可⟧ trong ⟦非…不可⟧.`],
    sum: [['⟦凡是…都…⟧: all members of a group.', '⟦凡是…都…⟧: mọi thành viên của nhóm.'], ['⟦之所以…是因为…⟧: result first, cause second.', '⟦之所以…是因为…⟧: kết quả trước, nguyên nhân sau.'], ['⟦非…不可⟧: must.', '⟦非…不可⟧: nhất định phải.']],
    links: [[GW + 'ASGTPGXK', 'Chinese Grammar Wiki — stating the effect before the cause', 'Chinese Grammar Wiki — nêu kết quả trước nguyên nhân'], [GW + 'ASGQFW44', 'Chinese Grammar Wiki — advanced uses of 都', 'Chinese Grammar Wiki — cách dùng nâng cao của 都'], [GW + 'HSK_5_grammar_points', 'Chinese Grammar Wiki — HSK 5 grammar points', 'Chinese Grammar Wiki — ngữ pháp HSK 5']],
    prac: [['Say: “All who pass the interview will receive an email.”', 'Nói: “Mọi người qua phỏng vấn đều sẽ nhận được email.”', '⟦凡是通过面试的人，都会收到邮件。⟧ Fánshì tōngguò miànshì de rén, dōu huì shōudào yóujiàn.', '⟦凡是通过面试的人，都会收到邮件。⟧ Fánshì tōngguò miànshì de rén, dōu huì shōudào yóujiàn.'], ['Rewrite with 之所以: 他迟到了，因为堵车。', 'Viết lại với 之所以: 他迟到了，因为堵车。', '⟦他之所以迟到，是因为堵车。⟧ Tā zhīsuǒyǐ chídào, shì yīnwèi dǔ chē.', '⟦他之所以迟到，是因为堵车。⟧ Tā zhīsuǒyǐ chídào, shì yīnwèi dǔ chē.']] }),
  L('3.3', ['Giving a viewpoint: 对…而言, 就…而言, 在…看来, 至于', 'Nêu góc nhìn: 对…而言, 就…而言, 在…看来, 至于'], 'Bốn khung mở đầu dùng nhiều khi thảo luận, viết luận, họp: “đối với”, “xét về”, “theo quan điểm”, “còn về”.', {
    goals: [['Frame an opinion with ⟦对…而言⟧ and ⟦就…而言⟧', 'Đóng khung ý kiến với ⟦对…而言⟧ và ⟦就…而言⟧'], ['Use ⟦在…看来⟧ for personal views', 'Dùng ⟦在…看来⟧ cho quan điểm cá nhân'], ['Change topic with ⟦至于⟧', 'Chuyển chủ đề bằng ⟦至于⟧']],
    sec: [
      { h: ['对…而言 / 就…而言 — as far as … is concerned', '对…而言 / 就…而言 — xét về…'], p: [`⟦对 X 而言⟧ = “for X” (evaluation from the standpoint of a person or group). ⟦就 X 而言⟧ = “in terms of X” (an aspect). Both go at the start of the clause. CIC301 taught ⟦对于⟧ and ⟦关于⟧ as prepositions; these two are more written and more precise.`, `⟦对 X 而言⟧ = “đối với X” (đánh giá từ lập trường một người/nhóm). ⟦就 X 而言⟧ = “xét về mặt X” (một khía cạnh). Cả hai đặt đầu vế. CIC301 đã học ⟦对于⟧ và ⟦关于⟧ làm giới từ; hai mẫu này văn viết hơn và chính xác hơn.`], f: '对 + 人 / 组织 + 而言，… ; 就 + 方面 + 而言，…',
        ex: [['对公司而言，人才比资金更重要。', 'Duì gōngsī ér yán, réncái bǐ zījīn gèng zhòngyào.', 'For the company, talent matters more than capital.', 'Đối với công ty, nhân tài quan trọng hơn vốn.'], ['就工作经验而言，他比我丰富得多。', 'Jiù gōngzuò jīngyàn ér yán, tā bǐ wǒ fēngfù de duō.', 'In terms of work experience, he has far more than I.', 'Xét về kinh nghiệm làm việc, anh ấy phong phú hơn tôi nhiều.']] },
      { h: ['在…看来 — in the view of', '在…看来 — theo quan điểm của'], p: [`⟦在 + person + 看来⟧ presents someone’s opinion, often one that differs from others’. With ⟦我⟧ it is softer than a flat statement.`, `⟦在 + người + 看来⟧ nêu ý kiến của ai đó, thường khác với số đông. Với ⟦我⟧ nghe mềm hơn câu khẳng định thẳng.`],
        ex: [['在我看来，这份合同有问题。', 'Zài wǒ kànlái, zhè fèn hétong yǒu wèntí.', 'In my view, this contract has problems.', 'Theo tôi, bản hợp đồng này có vấn đề.'], ['在老板看来，加班是应该的。', 'Zài lǎobǎn kànlái, jiābān shì yīnggāi de.', 'In the boss’s view, working overtime is only natural.', 'Theo ông chủ, tăng ca là chuyện đương nhiên.']] },
      { h: ['至于 — as for', '至于 — còn về'], p: [`⟦至于⟧ introduces a <em>new but related</em> topic, often a detail still to settle. It cannot start a conversation by itself.`, `⟦至于⟧ dẫn ra một chủ đề <em>mới nhưng liên quan</em>, thường là chi tiết còn chưa giải quyết. Không dùng để mở đầu cuộc nói chuyện.`],
        ex: [['我可以接受这个职位。至于工资，我们面谈吧。', 'Wǒ kěyǐ jiēshòu zhège zhíwèi. Zhìyú gōngzī, wǒmen miàntán ba.', 'I can accept the post. As for salary, let’s discuss it in person.', 'Tôi nhận vị trí này. Còn lương thì chúng ta gặp nói chuyện.']] }],
    vocab: [['而言', 'ér yán', 'speaking of', 'nói về, xét'], ['看来', 'kànlái', 'it seems; in the view of', 'xem ra'], ['至于', 'zhìyú', 'as for', 'còn về'], ['人才', 'réncái', 'talent', 'nhân tài'], ['资金', 'zījīn', 'capital; funds', 'vốn, tiền vốn'], ['丰富', 'fēngfù', 'rich; abundant', 'phong phú'], ['面谈', 'miàntán', 'to talk in person', 'gặp trực tiếp bàn'], ['观点', 'guāndiǎn', 'viewpoint', 'quan điểm'], ['谈判', 'tánpàn', 'negotiation', 'đàm phán'], ['竞争', 'jìngzhēng', 'competition', 'cạnh tranh']],
    dia: [['A', '你怎么看这家公司？', 'Nǐ zěnme kàn zhè jiā gōngsī?', 'What do you think of this company?', 'Bạn thấy công ty này thế nào?'], ['B', '就发展机会而言，它很不错。', 'Jiù fāzhǎn jīhuì ér yán, tā hěn búcuò.', 'In terms of opportunities, it’s quite good.', 'Xét về cơ hội phát triển thì khá tốt.'], ['A', '对新人而言，竞争是不是太大了？', 'Duì xīnrén ér yán, jìngzhēng shì bu shì tài dà le?', 'For newcomers, isn’t competition too strong?', 'Với người mới, cạnh tranh có quá lớn không?'], ['B', '在我看来，有压力才有进步。至于薪水，以后再谈。', 'Zài wǒ kànlái, yǒu yālì cái yǒu jìnbù. Zhìyú xīnshui, yǐhòu zài tán.', 'In my view, pressure brings progress. As for pay, we’ll talk later.', 'Theo tôi có áp lực mới tiến bộ. Còn lương thì bàn sau.']],
    pit: [`Writing ⟦对…而言⟧ without ⟦而⟧ or ⟦言⟧ (⟦对我言⟧ is wrong), and using ⟦至于⟧ to answer a question that has not yet introduced the topic.`, `Viết ⟦对…而言⟧ thiếu ⟦而⟧ hoặc ⟦言⟧ (⟦对我言⟧ sai), và dùng ⟦至于⟧ để trả lời khi chủ đề chưa được nêu.`],
    sum: [['⟦对…而言⟧ for whom; ⟦就…而言⟧ which aspect.', '⟦对…而言⟧ đối với ai; ⟦就…而言⟧ về khía cạnh nào.'], ['⟦在…看来⟧ someone’s view.', '⟦在…看来⟧ quan điểm của ai.'], ['⟦至于⟧ switches to a related topic.', '⟦至于⟧ chuyển sang chủ đề liên quan.']],
    links: [[GW + 'ASGD2A08', 'Chinese Grammar Wiki — “for…” with 而言', 'Chinese Grammar Wiki — “đối với…” với 而言'], [GW + 'ASGZRKTG', 'Chinese Grammar Wiki — “with regards to” with 至于', 'Chinese Grammar Wiki — “còn về” với 至于'], [GW + 'ASGC01S0', 'Chinese Grammar Wiki — comparing 对于 and 至于', 'Chinese Grammar Wiki — so sánh 对于 và 至于']],
    prac: [['Say: “For students, time is the most precious thing.”', 'Nói: “Đối với sinh viên, thời gian là thứ quý nhất.”', '⟦对学生而言，时间最宝贵。⟧ Duì xuésheng ér yán, shíjiān zuì bǎoguì.', '⟦对学生而言，时间最宝贵。⟧ Duì xuésheng ér yán, shíjiān zuì bǎoguì.'], ['Say: “In my opinion, we should refuse the contract.”', 'Nói: “Theo tôi, chúng ta nên từ chối hợp đồng.”', '⟦在我看来，我们应该拒绝这份合同。⟧ Zài wǒ kànlái, wǒmen yīnggāi jùjué zhè fèn hétong.', '⟦在我看来，我们应该拒绝这份合同。⟧ Zài wǒ kànlái, wǒmen yīnggāi jùjué zhè fèn hétong.']] }),
  QZ(3, 'Kiểm tra nhanh chương 3: 不妨, 何必, 未必, 凡是, 之所以, 非…不可, 对…而言, 在…看来, 至于.', [
    Q('q1', ['这点小事，____ 生气呢？', 'Điền: 这点小事，____ 生气呢？'], ['何必', '不妨', '未必', '凡是'], 0, ['Rhetorical “no need”.', 'Tu từ “không cần”.']),
    Q('q2', ['你 ____ 先试一试，不会有损失。', 'Điền: 你 ____ 先试一试，不会有损失。'], ['不妨', '何必', '之所以', '至于'], 0, ['Gentle suggestion.', 'Gợi ý nhẹ.']),
    Q('q3', ['“贵的东西未必好” means …', '“贵的东西未必好” nghĩa là …'], [['Expensive things are not necessarily good', 'Đồ đắt chưa chắc đã tốt'], ['Expensive things are never good', 'Đồ đắt không bao giờ tốt'], ['Expensive things are always good', 'Đồ đắt luôn tốt'], ['I do not buy expensive things', 'Tôi không mua đồ đắt']], 0, ['⟦未必⟧ = not necessarily.', '⟦未必⟧ = chưa chắc.']),
    Q('q4', ['凡是员工 ____ 要遵守规定。', 'Điền: 凡是员工 ____ 要遵守规定。'], ['都', '才', '再', '就是'], 0, ['⟦凡是…都…⟧.', '⟦凡是…都…⟧.']),
    Q('q5', ['他 ____ 成功，是因为一直努力。', 'Điền: 他 ____ 成功，是因为一直努力。'], ['之所以', '一旦', '不妨', '何况'], 0, ['⟦之所以…是因为…⟧.', '⟦之所以…是因为…⟧.']),
    Q('q6', ['这件事非你去 ____ 。', 'Điền: 这件事非你去 ____ 。'], ['不可', '不但', '不如', '不管'], 0, ['⟦非…不可⟧.', '⟦非…不可⟧.']),
    Q('q7', ['____ 公司而言，客户最重要。', 'Điền: ____ 公司而言，客户最重要。'], ['对', '给', '被', '把'], 0, ['⟦对…而言⟧.', '⟦对…而言⟧.']),
    Q('q8', ['我同意这个计划。____ 时间，我们再商量。', 'Điền: 我同意这个计划。____ 时间，我们再商量。'], ['至于', '之所以', '凡是', '万一'], 0, ['⟦至于⟧ introduces a related detail.', '⟦至于⟧ dẫn chi tiết liên quan.']),
  ]) ]);

const c4 = CH(4, 'Tradition and modernity', 'Truyền thống và hiện đại',
  'Từ vựng lễ hội, phong tục; trùng hợp và trái ý (偏偏, 恰好, 恰恰), nhượng bộ và đánh giá (固然, 虽说, 与其说…不如说), định nghĩa và liệt kê (所谓, 以及, 无…可…).', [
  L('4.1', ['Coincidence and contrary will: 偏偏, 恰好, 恰恰', 'Trùng hợp và trái ý: 偏偏, 恰好, 恰恰'], 'Ba phó từ chỉ sự việc diễn ra “đúng lúc”, “trớ trêu”, “chính là”: 偏偏, 恰好, 恰恰.', {
    goals: [['Complain about unlucky timing with ⟦偏偏⟧', 'Than phiền sự trớ trêu bằng ⟦偏偏⟧'], ['Describe lucky coincidence with ⟦恰好⟧', 'Nói sự trùng hợp may mắn bằng ⟦恰好⟧'], ['Stress “exactly” with ⟦恰恰⟧', 'Nhấn “chính là” bằng ⟦恰恰⟧']],
    sec: [
      { h: ['偏偏 — unluckily, stubbornly', '偏偏 — trớ trêu, cứ khăng khăng'], p: [`⟦偏偏⟧ has two uses: (1) things happen contrary to what one wants (“of all times…”); (2) a person does the opposite of advice. Both carry dissatisfaction.`, `⟦偏偏⟧ có hai cách dùng: (1) sự việc xảy ra trái mong muốn (“đúng lúc…”); (2) người ta làm ngược lời khuyên. Cả hai đều hàm ý bất mãn.`],
        ex: [['我想早点睡，偏偏邻居在开派对。', 'Wǒ xiǎng zǎodiǎn shuì, piānpiān línjū zài kāi pàiduì.', 'I wanted an early night, but of course the neighbour is having a party.', 'Tôi muốn đi ngủ sớm, đúng lúc hàng xóm lại mở tiệc.'], ['大家都劝他别去，他偏偏要去。', 'Dàjiā dōu quàn tā bié qù, tā piānpiān yào qù.', 'Everyone told him not to go, yet he insists on going.', 'Mọi người khuyên đừng đi mà anh ấy cứ khăng khăng đi.']] },
      { h: ['恰好 — just right, by coincidence', '恰好 — vừa khéo, đúng lúc'], p: [`⟦恰好⟧ shows that time, amount or situation matched exactly, usually favourably. Close to ⟦正好⟧ (more spoken).`, `⟦恰好⟧ cho thấy thời gian, số lượng hay tình huống khớp đúng, thường thuận lợi. Gần với ⟦正好⟧ (khẩu ngữ hơn).`],
        ex: [['我到火车站的时候，恰好火车进站。', 'Wǒ dào huǒchēzhàn de shíhou, qiàhǎo huǒchē jìn zhàn.', 'When I reached the station, the train happened to be pulling in.', 'Khi tôi đến ga thì tàu vừa khéo vào ga.'], ['这件衣服的尺寸恰好合适。', 'Zhè jiàn yīfu de chǐcùn qiàhǎo héshì.', 'This garment fits just right.', 'Cỡ của bộ đồ này vừa khít.']] },
      { h: ['恰恰 — precisely', '恰恰 — chính là, đúng là'], p: [`⟦恰恰⟧ points out that something is exactly the case, often to correct a wrong belief: ⟦恰恰相反⟧ “quite the opposite”, ⟦恰恰是…⟧ “is precisely…”.`, `⟦恰恰⟧ khẳng định điều gì đó chính xác là như thế, hay dùng để đính chính niềm tin sai: ⟦恰恰相反⟧ “hoàn toàn ngược lại”, ⟦恰恰是…⟧ “chính là…”.`],
        ex: [['传统不是落后，恰恰相反，它是智慧的积累。', 'Chuántǒng bú shì luòhòu, qiàqià xiāngfǎn, tā shì zhìhuì de jīlěi.', 'Tradition is not backwardness; quite the opposite, it is accumulated wisdom.', 'Truyền thống không phải lạc hậu, hoàn toàn ngược lại, đó là sự tích luỹ trí tuệ.'], ['让他生气的，恰恰是这件小事。', 'Ràng tā shēngqì de, qiàqià shì zhè jiàn xiǎoshì.', 'What made him angry was precisely this small matter.', 'Điều khiến anh ấy giận chính là chuyện nhỏ này.']] }],
    vocab: [['偏偏', 'piānpiān', 'unfortunately; stubbornly', 'trớ trêu; cứ khăng khăng'], ['恰好', 'qiàhǎo', 'just right', 'vừa khéo'], ['恰恰', 'qiàqià', 'exactly', 'chính là'], ['传统', 'chuántǒng', 'tradition', 'truyền thống'], ['现代', 'xiàndài', 'modern', 'hiện đại'], ['习俗', 'xísú', 'custom', 'tập tục'], ['庆祝', 'qìngzhù', 'to celebrate', 'chúc mừng, kỷ niệm'], ['落后', 'luòhòu', 'backward', 'lạc hậu'], ['智慧', 'zhìhuì', 'wisdom', 'trí tuệ'], ['积累', 'jīlěi', 'to accumulate', 'tích luỹ']],
    dia: [['A', '春节我想回老家，偏偏车票都卖完了。', 'Chūnjié wǒ xiǎng huí lǎojiā, piānpiān chēpiào dōu mài wán le.', 'I want to go home for Spring Festival, but tickets are sold out.', 'Tết tôi muốn về quê, trớ trêu vé bán hết rồi.'], ['B', '别急，我朋友恰好有两张退票。', 'Bié jí, wǒ péngyou qiàhǎo yǒu liǎng zhāng tuì piào.', 'Don’t worry, my friend happens to have two returned tickets.', 'Đừng lo, bạn tôi vừa khéo có hai vé trả lại.'], ['A', '真的吗？现代人以为回家很简单。', 'Zhēn de ma? Xiàndài rén yǐwéi huí jiā hěn jiǎndān.', 'Really? Modern people think going home is easy.', 'Thật à? Người hiện đại tưởng về nhà đơn giản.'], ['B', '恰恰相反，春运时最难的就是回家。', 'Qiàqià xiāngfǎn, chūnyùn shí zuì nán de jiù shì huí jiā.', 'Quite the opposite — during the travel rush going home is the hardest.', 'Hoàn toàn ngược lại, mùa xuân vận thì về nhà là khó nhất.']],
    pit: [`Using ⟦偏偏⟧ in a happy sentence (⟦偏偏中奖了⟧ sounds ironic, not pleased), and writing ⟦恰恰⟧ for a time coincidence where ⟦恰好⟧ is right.`, `Dùng ⟦偏偏⟧ trong câu vui (⟦偏偏中奖了⟧ nghe mỉa mai, không vui), và dùng ⟦恰恰⟧ cho sự trùng hợp thời gian trong khi phải là ⟦恰好⟧.`],
    sum: [['⟦偏偏⟧: against one’s wish.', '⟦偏偏⟧: trái ý muốn.'], ['⟦恰好⟧: matched by chance.', '⟦恰好⟧: khớp một cách tình cờ.'], ['⟦恰恰⟧: exactly; ⟦恰恰相反⟧ quite the opposite.', '⟦恰恰⟧: chính là; ⟦恰恰相反⟧ hoàn toàn ngược lại.']],
    links: [[GW + 'ASGX5QTV', 'Chinese Grammar Wiki — “on the contrary” with 反而', 'Chinese Grammar Wiki — “ngược lại” với 反而'], [GW + 'ASG87D22', 'Chinese Grammar Wiki — “especially” with 格外', 'Chinese Grammar Wiki — “đặc biệt” với 格外'], ['https://en.wikipedia.org/wiki/Chinese_New_Year', 'Wikipedia — Chinese New Year', 'Wikipedia — Tết Nguyên đán Trung Quốc']],
    prac: [['Say: “I wanted to go out, but of course it rained.”', 'Nói: “Tôi muốn ra ngoài, đúng lúc trời lại mưa.”', '⟦我想出去玩，偏偏下雨了。⟧ Wǒ xiǎng chūqù wán, piānpiān xià yǔ le.', '⟦我想出去玩，偏偏下雨了。⟧ Wǒ xiǎng chūqù wán, piānpiān xià yǔ le.'], ['Complete: 他不是不想学，____ 相反，他太想学了。', 'Điền: 他不是不想学，____ 相反，他太想学了。', '⟦恰恰⟧ — qiàqià.', '⟦恰恰⟧ — qiàqià.']] }),
  L('4.2', ['Concession and judgement: 固然, 虽说, 与其说…不如说…', 'Nhượng bộ và đánh giá: 固然, 虽说, 与其说…不如说…'], 'Ba mẫu dùng khi tranh luận về truyền thống: thừa nhận một nửa (固然, 虽说) và chỉnh lại cách gọi (与其说…不如说…).', {
    goals: [['Concede a point with ⟦固然…但是…⟧ and ⟦虽说…但…⟧', 'Thừa nhận một ý với ⟦固然…但是…⟧ và ⟦虽说…但…⟧'], ['Re-describe something with ⟦与其说…不如说…⟧', 'Gọi tên lại sự việc bằng ⟦与其说…不如说…⟧']],
    sec: [
      { h: ['固然 / 虽说 — it is true that… but…', '固然 / 虽说 — đúng là… nhưng…'], p: [`⟦固然⟧ admits that the first point is true but moves to the point the speaker thinks is more important (⟦但是 / 可是 / 也⟧). ⟦虽说⟧ is the spoken counterpart of ⟦虽然⟧, usually followed by ⟦但⟧. Compare CIC301 ⟦尽管…然而⟧.`, `⟦固然⟧ thừa nhận ý đầu là đúng nhưng chuyển sang ý người nói cho là quan trọng hơn (⟦但是 / 可是 / 也⟧). ⟦虽说⟧ là dạng khẩu ngữ của ⟦虽然⟧, thường theo sau là ⟦但⟧. So với ⟦尽管…然而⟧ ở CIC301.`], f: 'A 固然 …，但是 / 也 + B',
        ex: [['传统文化固然重要，但也需要创新。', 'Chuántǒng wénhuà gùrán zhòngyào, dàn yě xūyào chuàngxīn.', 'Traditional culture is indeed important, but it also needs innovation.', 'Văn hoá truyền thống đúng là quan trọng nhưng cũng cần đổi mới.'], ['虽说现在年轻人不太过节，但家人团聚还是很重要。', 'Suīshuō xiànzài niánqīngrén bú tài guò jié, dàn jiārén tuánjù háishi hěn zhòngyào.', 'Although young people hardly celebrate festivals nowadays, family reunions still matter.', 'Dù giới trẻ ngày nay ít ăn lễ nhưng sum họp gia đình vẫn rất quan trọng.']] },
      { h: ['与其说 A，不如说 B — it is better described as B', '与其说 A，不如说 B — gọi là B thì đúng hơn'], p: [`This pattern does not compare actions (as ⟦与其…不如…⟧ in Chapter 1) but <em>labels</em>: A is a common description, B is the more accurate one.`, `Mẫu này không so sánh hành động (khác ⟦与其…不如…⟧ ở Chương 1) mà <em>gọi tên</em>: A là cách nói thường gặp, B là cách nói chính xác hơn.`], f: '与其说 + A，不如说 + B',
        ex: [['与其说这是一种习俗，不如说这是一种感情。', 'Yǔqí shuō zhè shì yì zhǒng xísú, bùrú shuō zhè shì yì zhǒng gǎnqíng.', 'Rather than a custom, it is more a kind of feeling.', 'Gọi đó là tập tục chi bằng gọi là một thứ tình cảm.'], ['与其说他聪明，不如说他勤奋。', 'Yǔqí shuō tā cōngmíng, bùrú shuō tā qínfèn.', 'It is less that he is clever than that he is hard-working.', 'Nói anh ấy thông minh chi bằng nói anh ấy chăm chỉ.']] }],
    vocab: [['固然', 'gùrán', 'admittedly', 'đúng là'], ['虽说', 'suīshuō', 'although', 'tuy nói'], ['与其说', 'yǔqí shuō', 'rather than say', 'thay vì nói'], ['创新', 'chuàngxīn', 'to innovate', 'đổi mới, sáng tạo'], ['团聚', 'tuánjù', 'reunion', 'sum họp'], ['感情', 'gǎnqíng', 'feeling; affection', 'tình cảm'], ['遗产', 'yíchǎn', 'heritage', 'di sản'], ['保护', 'bǎohù', 'to protect', 'bảo vệ'], ['继承', 'jìchéng', 'to inherit', 'kế thừa'], ['勤奋', 'qínfèn', 'diligent', 'siêng năng']],
    dia: [['A', '有人说过节太麻烦，不如取消。', 'Yǒu rén shuō guò jié tài máfan, bùrú qǔxiāo.', 'Some say festivals are too much trouble and should be dropped.', 'Có người nói ăn lễ phiền, bỏ đi còn hơn.'], ['B', '过节固然麻烦，但是家人能团聚。', 'Guò jié gùrán máfan, dànshì jiārén néng tuánjù.', 'Festivals are indeed troublesome, but the family can get together.', 'Ăn lễ đúng là phiền nhưng gia đình được sum họp.'], ['A', '与其说是节日，不如说是见面的理由。', 'Yǔqí shuō shì jiérì, bùrú shuō shì jiànmiàn de lǐyóu.', 'Less a holiday than a reason to meet.', 'Gọi là ngày lễ chi bằng gọi là cái cớ để gặp nhau.'], ['B', '说得对，传统要继承，也要创新。', 'Shuō de duì, chuántǒng yào jìchéng, yě yào chuàngxīn.', 'Right — tradition should be inherited and renewed.', 'Đúng, truyền thống phải kế thừa và cũng phải đổi mới.']],
    pit: [`Following ⟦固然⟧ with a result that continues the same idea (it needs a turning point: ⟦但是 / 也⟧), and mixing ⟦与其说⟧ with the choice pattern ⟦与其…不如…⟧ of Chapter 1.`, `Theo sau ⟦固然⟧ bằng ý cùng chiều (phải có chuyển ý: ⟦但是 / 也⟧), và lẫn ⟦与其说⟧ với mẫu chọn lựa ⟦与其…不如…⟧ ở Chương 1.`],
    sum: [['⟦固然 A，但是 B⟧: A true, B matters more.', '⟦固然 A，但是 B⟧: A đúng, B quan trọng hơn.'], ['⟦虽说…但…⟧: spoken “although”.', '⟦虽说…但…⟧: “tuy” khẩu ngữ.'], ['⟦与其说 A，不如说 B⟧: relabelling.', '⟦与其说 A，不如说 B⟧: gọi tên lại.']],
    links: [[GW + 'ASGE4B94', 'Chinese Grammar Wiki — comparisons with 比起', 'Chinese Grammar Wiki — so sánh với 比起'], [GW + 'ASGX5QTV', 'Chinese Grammar Wiki — “on the contrary” with 反而', 'Chinese Grammar Wiki — “ngược lại” với 反而'], [GW + 'HSK_5_grammar_points', 'Chinese Grammar Wiki — HSK 5 grammar points', 'Chinese Grammar Wiki — ngữ pháp HSK 5']],
    prac: [['Say: “Money is indeed important, but it is not everything.”', 'Nói: “Tiền đúng là quan trọng nhưng không phải tất cả.”', '⟦钱固然重要，但不是一切。⟧ Qián gùrán zhòngyào, dàn bú shì yíqiè.', '⟦钱固然重要，但不是一切。⟧ Qián gùrán zhòngyào, dàn bú shì yíqiè.'], ['Say: “It is less a problem of time than of method.”', 'Nói: “Gọi là vấn đề thời gian chi bằng gọi là vấn đề phương pháp.”', '⟦与其说是时间问题，不如说是方法问题。⟧ Yǔqí shuō shì shíjiān wèntí, bùrú shuō shì fāngfǎ wèntí.', '⟦与其说是时间问题，不如说是方法问题。⟧ Yǔqí shuō shì shíjiān wèntí, bùrú shuō shì fāngfǎ wèntí.']] }),
  L('4.3', ['Defining and listing: 所谓, 以及, 无…可…', 'Định nghĩa và liệt kê: 所谓, 以及, 无…可…'], 'Ba công cụ cho bài viết giới thiệu phong tục: giải thích khái niệm (所谓), liệt kê trang trọng (以及), diễn đạt “không có gì để…” (无…可…).', {
    goals: [['Define a term with ⟦所谓…，就是…⟧', 'Định nghĩa thuật ngữ bằng ⟦所谓…，就是…⟧'], ['List items formally with ⟦以及⟧', 'Liệt kê trang trọng với ⟦以及⟧'], ['Say “nothing to…” with ⟦无…可…⟧', 'Nói “chẳng có gì để…” bằng ⟦无…可…⟧']],
    sec: [
      { h: ['所谓…，就是… — “the so-called… means…”', '所谓…，就是… — “cái gọi là… tức là…”'], p: [`⟦所谓⟧ quotes a term and then explains it. It may also have a slightly doubtful tone (“so-called”), depending on context.`, `⟦所谓⟧ nêu một thuật ngữ rồi giải thích. Tuỳ ngữ cảnh có thể mang chút hoài nghi (“cái gọi là”).`], f: '所谓 + 词语，就是 / 是指 + 解释',
        ex: [['所谓“年味”，就是节日里的热闹和团圆的气氛。', 'Suǒwèi “niánwèi”, jiùshì jiérì lǐ de rènao hé tuányuán de qìfēn.', 'The so-called “flavour of the New Year” is the bustle and reunion atmosphere of the festival.', 'Cái gọi là “không khí Tết” chính là sự náo nhiệt và bầu không khí sum vầy.'], ['所谓传统，是指一代一代传下来的东西。', 'Suǒwèi chuántǒng, shì zhǐ yí dài yí dài chuán xiàlái de dōngxi.', 'Tradition refers to what is handed down generation after generation.', 'Truyền thống là những thứ truyền lại qua từng thế hệ.']] },
      { h: ['以及 — as well as', '以及 — cùng với, và'], p: [`⟦以及⟧ joins nouns (rarely verbs) at the <em>last</em> position of a list, and is more formal than ⟦和⟧. It often joins larger groups after items already joined by commas.`, `⟦以及⟧ nối danh từ (hiếm khi động từ) ở vị trí <em>cuối</em> danh sách, trang trọng hơn ⟦和⟧. Thường nối nhóm lớn hơn sau các mục đã ngăn bằng dấu phẩy.`],
        ex: [['春节期间，人们贴春联、挂灯笼以及吃团圆饭。', 'Chūnjié qījiān, rénmen tiē chūnlián, guà dēnglong yǐjí chī tuányuánfàn.', 'During Spring Festival people put up couplets, hang lanterns and have the reunion dinner.', 'Dịp Tết, người ta dán câu đối, treo đèn lồng và ăn bữa cơm đoàn viên.'], ['会议讨论了经费、人员以及时间安排。', 'Huìyì tǎolùnle jīngfèi, rényuán yǐjí shíjiān ānpái.', 'The meeting discussed funds, staff and scheduling.', 'Cuộc họp bàn về kinh phí, nhân sự và sắp xếp thời gian.']] },
      { h: ['无…可… — nothing to…', '无…可… — chẳng có gì để…'], p: [`Four-character patterns with ⟦无 + noun + 可 + verb⟧ mean “there is no X to Y”. Common set phrases: ⟦无话可说⟧, ⟦无事可做⟧, ⟦无路可走⟧, ⟦无可奈何⟧.`, `Mẫu bốn chữ ⟦无 + danh từ + 可 + động từ⟧ nghĩa “không có X để Y”. Cụm cố định: ⟦无话可说⟧, ⟦无事可做⟧, ⟦无路可走⟧, ⟦无可奈何⟧.`], f: '无 + 名词 + 可 + 动词',
        ex: [['假期里他无事可做，觉得很无聊。', 'Jiàqī lǐ tā wú shì kě zuò, juéde hěn wúliáo.', 'During the holiday he had nothing to do and felt bored.', 'Kỳ nghỉ anh ấy chẳng có việc gì làm, thấy rất chán.'], ['对这个结果，我无话可说。', 'Duì zhège jiéguǒ, wǒ wú huà kě shuō.', 'I have nothing to say about this result.', 'Với kết quả này tôi không còn gì để nói.']] }],
    vocab: [['所谓', 'suǒwèi', 'so-called', 'cái gọi là'], ['以及', 'yǐjí', 'as well as', 'cùng với'], ['春联', 'chūnlián', 'Spring Festival couplets', 'câu đối Tết'], ['灯笼', 'dēnglong', 'lantern', 'đèn lồng'], ['团圆饭', 'tuányuánfàn', 'reunion dinner', 'bữa cơm đoàn viên'], ['气氛', 'qìfēn', 'atmosphere', 'bầu không khí'], ['热闹', 'rènao', 'lively', 'náo nhiệt'], ['期间', 'qījiān', 'during', 'trong thời gian'], ['无聊', 'wúliáo', 'bored; boring', 'chán, tẻ nhạt'], ['无可奈何', 'wú kě nài hé', 'helpless', 'bất lực, đành chịu']],
    dia: [['A', '你说的“年味”到底是什么？', 'Nǐ shuō de “niánwèi” dàodǐ shì shénme?', 'What exactly is this “New Year flavour” you mention?', 'Cái “không khí Tết” bạn nói rốt cuộc là gì?'], ['B', '所谓年味，就是红灯笼、鞭炮声以及家人的笑声。', 'Suǒwèi niánwèi, jiùshì hóng dēnglong, biānpào shēng yǐjí jiārén de xiàoshēng.', 'It is red lanterns, firecrackers and the family’s laughter.', 'Là đèn lồng đỏ, tiếng pháo và tiếng cười của gia đình.'], ['A', '城市里的年味越来越淡了。', 'Chéngshì lǐ de niánwèi yuè lái yuè dàn le.', 'City New Year flavour is fading.', 'Không khí Tết ở thành phố ngày càng nhạt.'], ['B', '是啊，很多人觉得无事可做，只能看手机。', 'Shì a, hěn duō rén juéde wú shì kě zuò, zhǐ néng kàn shǒujī.', 'Yes, many feel there is nothing to do but look at their phones.', 'Ừ, nhiều người thấy chẳng có gì làm, chỉ biết nhìn điện thoại.']],
    pit: [`Using ⟦以及⟧ between two clauses (it joins nouns, not sentences) and putting it before the first item. Also confusing ⟦所谓⟧ (“so-called”) with ⟦所以⟧ (“therefore”).`, `Dùng ⟦以及⟧ nối hai mệnh đề (nó nối danh từ, không nối câu) và đặt trước mục đầu. Cũng hay nhầm ⟦所谓⟧ (“cái gọi là”) với ⟦所以⟧ (“cho nên”).`],
    sum: [['⟦所谓…就是…⟧: define a term.', '⟦所谓…就是…⟧: định nghĩa thuật ngữ.'], ['⟦A、B 以及 C⟧: formal list.', '⟦A、B 以及 C⟧: liệt kê trang trọng.'], ['⟦无 N 可 V⟧: nothing to V.', '⟦无 N 可 V⟧: không có N để V.']],
    links: [[GW + 'ASGC4C1F', 'Chinese Grammar Wiki — “so-called” with 所谓', 'Chinese Grammar Wiki — “cái gọi là” với 所谓'], [GW + 'ASGBA782', 'Chinese Grammar Wiki — 无…可… pattern', 'Chinese Grammar Wiki — mẫu 无…可…'], [GW + 'ASG50341', 'Chinese Grammar Wiki — “including” with 在内', 'Chinese Grammar Wiki — “bao gồm” với 在内']],
    prac: [['Say: “The so-called ‘green food’ means pollution-free food.”', 'Nói: “Cái gọi là ‘thực phẩm xanh’ là thực phẩm không ô nhiễm.”', '⟦所谓“绿色食品”，就是无污染的食品。⟧ Suǒwèi “lǜsè shípǐn”, jiùshì wú wūrǎn de shípǐn.', '⟦所谓“绿色食品”，就是无污染的食品。⟧ Suǒwèi “lǜsè shípǐn”, jiùshì wú wūrǎn de shípǐn.'], ['Fill in: 我们买了苹果、香蕉 ____ 西瓜。', 'Điền: 我们买了苹果、香蕉 ____ 西瓜。', '⟦以及⟧ — yǐjí.', '⟦以及⟧ — yǐjí.']] }),
  QZ(4, 'Kiểm tra nhanh chương 4: 偏偏, 恰好, 恰恰, 固然, 虽说, 与其说…不如说, 所谓, 以及, 无…可….', [
    Q('q1', ['我想休息，____ 老板又打来电话。', 'Điền: 我想休息，____ 老板又打来电话。'], ['偏偏', '恰恰', '以及', '固然'], 0, ['Unlucky timing: ⟦偏偏⟧.', 'Trớ trêu: ⟦偏偏⟧.']),
    Q('q2', ['我到站时，车 ____ 来了。', 'Điền: 我到站时，车 ____ 来了。'], ['恰好', '固然', '所谓', '无可'], 0, ['Lucky coincidence: ⟦恰好⟧.', 'Trùng hợp may mắn: ⟦恰好⟧.']),
    Q('q3', ['“恰恰相反” means …', '“恰恰相反” nghĩa là …'], [['quite the opposite', 'hoàn toàn ngược lại'], ['exactly the same', 'giống hệt'], ['not at all sure', 'hoàn toàn không chắc'], ['by chance', 'tình cờ']], 0, ['Fixed phrase.', 'Cụm cố định.']),
    Q('q4', ['传统 ____ 重要，但也要创新。', 'Điền: 传统 ____ 重要，但也要创新。'], ['固然', '偏偏', '恰好', '以及'], 0, ['Concession: ⟦固然⟧.', 'Nhượng bộ: ⟦固然⟧.']),
    Q('q5', ['与其说他懒，____ 说他没有方法。', 'Điền: 与其说他懒，____ 说他没有方法。'], ['不如', '何必', '未必', '以便'], 0, ['⟦与其说 A，不如说 B⟧.', '⟦与其说 A，不如说 B⟧.']),
    Q('q6', ['____ “缘分”，就是命运让两个人相遇。', 'Điền: ____ “缘分”，就是命运让两个人相遇。'], ['所谓', '所以', '以及', '万一'], 0, ['⟦所谓…就是…⟧ defines a term.', '⟦所谓…就是…⟧ định nghĩa thuật ngữ.']),
    Q('q7', ['我们去了北京、上海 ____ 广州。', 'Điền: 我们去了北京、上海 ____ 广州。'], ['以及', '固然', '偏偏', '虽说'], 0, ['⟦以及⟧ introduces the last item.', '⟦以及⟧ nối mục cuối.']),
    Q('q8', ['Which means “nothing to do”?', 'Cụm nào nghĩa “không có việc gì làm”?'], ['无事可做', '无话可说', '无路可走', '无可奈何'], 0, ['⟦无事可做⟧.', '⟦无事可做⟧.']),
  ]) ]);

const c5 = CH(5, 'Environment and sustainability', 'Môi trường và phát triển bền vững',
  'Từ vựng môi trường; điều khó tránh (难免, 不免, 免不了), may nhờ và hoá ra (多亏, 幸亏, 要不是, 难怪), nắm thời cơ và mức độ (趁, 尽量, 尽快, 随手).', [
  L('5.1', ['What is hard to avoid: 难免, 不免, 免不了', 'Điều khó tránh: 难免, 不免, 免不了'], 'Ba cách nói “khó tránh khỏi” với sắc thái khác nhau, kèm từ vựng về ô nhiễm và tài nguyên.', {
    goals: [['Say “it is hard to avoid” with ⟦难免⟧, ⟦免不了⟧ and ⟦不免⟧', 'Nói “khó tránh khỏi” với ⟦难免⟧, ⟦免不了⟧, ⟦不免⟧'], ['Choose the right one by structure', 'Chọn đúng từ theo cấu trúc'], ['Learn 10 environment words', 'Học 10 từ về môi trường']],
    sec: [
      { h: ['难免 / 免不了 — it is hard to avoid', '难免 / 免不了 — khó tránh khỏi'], p: [`Both state that a (usually unwelcome) result will naturally occur in a situation. ⟦难免⟧ is an adjective-like word placed before the verb, often with ⟦会⟧; ⟦免不了⟧ is spoken, and may be followed directly by a noun object. A specific cause is given first.`, `Cả hai nói rằng một kết quả (thường không mong muốn) sẽ tự nhiên xảy ra trong tình huống ấy. ⟦难免⟧ giống tính từ, đặt trước động từ, hay đi với ⟦会⟧; ⟦免不了⟧ khẩu ngữ, có thể theo ngay sau là tân ngữ danh từ. Thường nêu nguyên nhân trước.`], f: '情况，难免 (会) / 免不了 + 结果',
        ex: [['刚来到新环境，难免会紧张。', 'Gāng láidào xīn huánjìng, nánmiǎn huì jǐnzhāng.', 'When you first arrive in a new environment, it is hard not to feel nervous.', 'Mới đến môi trường mới thì khó tránh khỏi lo lắng.'], ['城市发展得快，免不了出现污染问题。', 'Chéngshì fāzhǎn de kuài, miǎnbuliǎo chūxiàn wūrǎn wèntí.', 'With fast urban growth, pollution problems are bound to appear.', 'Thành phố phát triển nhanh, khó tránh có vấn đề ô nhiễm.']] },
      { h: ['不免 — inevitably (a feeling)', '不免 — khó tránh (cảm xúc)'], p: [`⟦不免⟧ is a written adverb, usually followed by a feeling or reaction (⟦担心 / 失望 / 有些…⟧). It describes a natural human reaction to what has just been said.`, `⟦不免⟧ là phó từ văn viết, thường theo sau là cảm xúc hoặc phản ứng (⟦担心 / 失望 / 有些…⟧). Diễn tả phản ứng tự nhiên của con người trước sự việc vừa nêu.`],
        ex: [['看到河水变脏，他不免有些担心。', 'Kàndào héshuǐ biàn zāng, tā bùmiǎn yǒuxiē dānxīn.', 'Seeing the river turn dirty, he could not help feeling worried.', 'Thấy nước sông bẩn đi, anh ấy không khỏi lo lắng.']] }],
    vocab: [['难免', 'nánmiǎn', 'hard to avoid', 'khó tránh'], ['免不了', 'miǎnbuliǎo', 'bound to', 'không tránh được'], ['不免', 'bùmiǎn', 'inevitably', 'không khỏi'], ['污染', 'wūrǎn', 'pollution', 'ô nhiễm'], ['垃圾', 'lājī', 'rubbish', 'rác'], ['分类', 'fēnlèi', 'to sort', 'phân loại'], ['排放', 'páifàng', 'to discharge, emit', 'thải ra'], ['资源', 'zīyuán', 'resources', 'tài nguyên'], ['能源', 'néngyuán', 'energy source', 'năng lượng'], ['气候', 'qìhòu', 'climate', 'khí hậu']],
    dia: [['A', '工厂越来越多，空气难免会变差。', 'Gōngchǎng yuè lái yuè duō, kōngqì nánmiǎn huì biàn chà.', 'With more and more factories, the air will inevitably get worse.', 'Nhà máy ngày càng nhiều, không khí khó tránh xấu đi.'], ['B', '是啊，免不了要排放废气。', 'Shì a, miǎnbuliǎo yào páifàng fèiqì.', 'Yes, emitting waste gas is unavoidable.', 'Đúng vậy, khó tránh việc thải khí thải.'], ['A', '所以垃圾分类很重要。', 'Suǒyǐ lājī fēnlèi hěn zhòngyào.', 'That’s why sorting rubbish matters.', 'Vì vậy phân loại rác rất quan trọng.'], ['B', '看到这么多垃圾，我不免有些难过。', 'Kàndào zhème duō lājī, wǒ bùmiǎn yǒuxiē nánguò.', 'Seeing so much rubbish, I can’t help feeling sad.', 'Nhìn nhiều rác thế này tôi không khỏi buồn.']],
    pit: [`Using ⟦难免⟧ for a desirable outcome (⟦学习难免会进步⟧ is odd), and putting ⟦不免⟧ before a bare noun. Do not confuse ⟦难免⟧ with ⟦难以⟧ (“difficult to”).`, `Dùng ⟦难免⟧ cho kết quả đáng mong (⟦学习难免会进步⟧ lạ), và đặt ⟦不免⟧ trước danh từ trơn. Đừng nhầm ⟦难免⟧ với ⟦难以⟧ (“khó mà”).`],
    sum: [['⟦难免 (会)⟧: naturally occurs.', '⟦难免 (会)⟧: tự nhiên sẽ xảy ra.'], ['⟦免不了⟧: spoken, may take a noun.', '⟦免不了⟧: khẩu ngữ, có thể theo danh từ.'], ['⟦不免⟧: written, a feeling follows.', '⟦不免⟧: văn viết, theo sau là cảm xúc.']],
    links: [[GW + 'ASGYDKT3', 'Chinese Grammar Wiki — “hard to avoid” with 难免', 'Chinese Grammar Wiki — “khó tránh” với 难免'], [GW + 'ASGYKH5G', 'Chinese Grammar Wiki — 难怪 as a verb', 'Chinese Grammar Wiki — 难怪 làm động từ'], ['https://www.hsk.academy/en/hsk-5-vocabulary-list', 'HSK Academy — HSK 5 vocabulary list', 'HSK Academy — từ vựng HSK 5']],
    prac: [['Say: “Learning a language, mistakes are inevitable.”', 'Nói: “Học ngoại ngữ khó tránh mắc lỗi.”', '⟦学外语难免会犯错。⟧ Xué wàiyǔ nánmiǎn huì fàn cuò.', '⟦学外语难免会犯错。⟧ Xué wàiyǔ nánmiǎn huì fàn cuò.'], ['Which word fits a feeling: 难免 or 不免? Complete: 听到这个消息，她 ____ 有些失望。', 'Từ nào hợp cảm xúc: 难免 hay 不免? Điền: 听到这个消息，她 ____ 有些失望。', '⟦不免⟧ — bùmiǎn.', '⟦不免⟧ — bùmiǎn.']] }),
  L('5.2', ['Thanks to and no wonder: 多亏, 幸亏, 要不是, 难怪', 'May nhờ và hèn gì: 多亏, 幸亏, 要不是, 难怪'], 'Bốn từ phản ứng với sự việc đã xảy ra: biết ơn (多亏), may mắn (幸亏), giả định ngược (要不是), hiểu ra (难怪).', {
    goals: [['Thank a cause with ⟦多亏⟧', 'Cảm ơn nguyên nhân bằng ⟦多亏⟧'], ['Show lucky escape with ⟦幸亏⟧', 'Diễn tả may mắn thoát nạn với ⟦幸亏⟧'], ['Argue counterfactually with ⟦要不是⟧', 'Lập luận phản thực với ⟦要不是⟧'], ['React with ⟦难怪⟧', 'Phản ứng bằng ⟦难怪⟧']],
    sec: [
      { h: ['多亏 / 幸亏 — thanks to / luckily', '多亏 / 幸亏 — nhờ / may mà'], p: [`⟦多亏 + person or fact⟧ credits someone for a good outcome. ⟦幸亏⟧ stresses luck; the second clause often starts with ⟦不然 / 否则⟧ to state the bad result that was avoided.`, `⟦多亏 + người hoặc sự việc⟧ ghi công ai đó cho kết quả tốt. ⟦幸亏⟧ nhấn may mắn; vế sau hay bắt đầu bằng ⟦不然 / 否则⟧ nêu kết quả xấu đã tránh được.`],
        ex: [['多亏大家帮忙，我们才按时完成了环保活动。', 'Duōkuī dàjiā bāngmáng, wǒmen cái ànshí wánchéngle huánbǎo huódòng.', 'Thanks to everyone’s help, we finished the green event on time.', 'Nhờ mọi người giúp, chúng tôi mới hoàn thành hoạt động môi trường đúng hạn.'], ['幸亏带了雨伞，不然就淋湿了。', 'Xìngkuī dàile yǔsǎn, bùrán jiù línshī le.', 'Luckily I brought an umbrella, otherwise I’d be soaked.', 'May mà mang ô, không thì ướt hết rồi.']] },
      { h: ['要不是 — if it were not for', '要不是 — nếu không phải vì'], p: [`⟦要不是 + cause，(就 / 早就) + result⟧ talks about the real world through an opposite hypothesis: the cause really existed, so the good thing happened.`, `⟦要不是 + nguyên nhân，(就 / 早就) + kết quả⟧ nói về thực tế bằng giả thiết ngược: nguyên nhân có thật nên điều tốt đã xảy ra.`], f: '要不是 + 原因，(早) 就 + 结果',
        ex: [['要不是政府采取措施，空气质量不会这么快好转。', 'Yàobushì zhèngfǔ cǎiqǔ cuòshī, kōngqì zhìliàng bú huì zhème kuài hǎozhuǎn.', 'If the government hadn’t taken measures, air quality wouldn’t have improved so fast.', 'Nếu chính phủ không áp dụng biện pháp thì chất lượng không khí đã không tốt lên nhanh vậy.']] },
      { h: ['难怪 — no wonder', '难怪 — hèn gì'], p: [`State the explanation first or after: ⟦难怪 + surprising result⟧ shows the speaker has just understood why. Often paired with ⟦原来⟧.`, `Nêu lời giải thích trước hoặc sau: ⟦难怪 + kết quả lạ⟧ cho thấy người nói vừa hiểu nguyên do. Hay đi với ⟦原来⟧.`],
        ex: [['今天气温三十八度，难怪这么热。', 'Jīntiān qìwēn sānshíbā dù, nánguài zhème rè.', 'It’s 38 degrees today — no wonder it’s so hot.', 'Hôm nay 38 độ, hèn gì nóng thế.']] }],
    vocab: [['多亏', 'duōkuī', 'thanks to', 'may nhờ'], ['幸亏', 'xìngkuī', 'luckily', 'may mà'], ['要不是', 'yàobushì', 'if it were not for', 'nếu không phải'], ['难怪', 'nánguài', 'no wonder', 'hèn gì'], ['政府', 'zhèngfǔ', 'government', 'chính phủ'], ['措施', 'cuòshī', 'measure', 'biện pháp'], ['好转', 'hǎozhuǎn', 'to improve', 'khá lên'], ['气温', 'qìwēn', 'temperature', 'nhiệt độ không khí'], ['环保', 'huánbǎo', 'environmental protection', 'bảo vệ môi trường'], ['淋湿', 'línshī', 'to get soaked', 'ướt mưa']],
    dia: [['A', '这条河怎么变干净了？', 'Zhè tiáo hé zěnme biàn gānjìng le?', 'How did this river become clean?', 'Sao con sông này sạch rồi?'], ['B', '多亏居民们天天清理垃圾。', 'Duōkuī jūmínmen tiān tiān qīnglǐ lājī.', 'Thanks to residents cleaning up daily.', 'Nhờ dân cư dọn rác hằng ngày.'], ['A', '要不是大家坚持，河水早就发臭了。', 'Yàobushì dàjiā jiānchí, héshuǐ zǎo jiù fāchòu le.', 'Without everyone’s persistence the water would have stunk long ago.', 'Nếu không nhờ mọi người kiên trì, nước sông đã hôi từ lâu.'], ['B', '难怪这里的鸟越来越多了。', 'Nánguài zhèlǐ de niǎo yuè lái yuè duō le.', 'No wonder there are more and more birds here.', 'Hèn gì chim ở đây ngày càng nhiều.']],
    pit: [`Using ⟦多亏⟧ for a bad result, and giving ⟦幸亏⟧ no follow-up (the avoided bad outcome is usually expressed with ⟦不然 / 否则⟧). In ⟦要不是⟧ sentences, do not add a second negative to the result clause.`, `Dùng ⟦多亏⟧ cho kết quả xấu, và để ⟦幸亏⟧ không có vế sau (kết quả xấu đã tránh thường nêu bằng ⟦不然 / 否则⟧). Ở câu ⟦要不是⟧ đừng thêm phủ định thừa ở vế kết quả.`],
    sum: [['⟦多亏⟧ = thanks to (credit).', '⟦多亏⟧ = nhờ (ghi công).'], ['⟦幸亏…不然…⟧ = luckily, otherwise…', '⟦幸亏…不然…⟧ = may mà, không thì…'], ['⟦要不是⟧ = if not for; ⟦难怪⟧ = no wonder.', '⟦要不是⟧ = nếu không phải; ⟦难怪⟧ = hèn gì.']],
    links: [[GW + 'ASG44TBS', 'Chinese Grammar Wiki — “thanks to” with 多亏', 'Chinese Grammar Wiki — “nhờ” với 多亏'], [GW + 'ASG8F7D4', 'Chinese Grammar Wiki — “if it were not for” with 要不是', 'Chinese Grammar Wiki — “nếu không phải” với 要不是'], [GW + 'ASGFPV2C', 'Chinese Grammar Wiki — “no wonder”', 'Chinese Grammar Wiki — “hèn gì”']],
    prac: [['Say: “Thanks to the teacher’s help, I passed.”', 'Nói: “Nhờ thầy giúp, tôi đã đậu.”', '⟦多亏老师的帮助，我才通过了。⟧ Duōkuī lǎoshī de bāngzhù, wǒ cái tōngguò le.', '⟦多亏老师的帮助，我才通过了。⟧ Duōkuī lǎoshī de bāngzhù, wǒ cái tōngguò le.'], ['Say: “No wonder he is tired — he worked all night.”', 'Nói: “Hèn gì anh ấy mệt — làm cả đêm.”', '⟦难怪他这么累，他工作了一整夜。⟧ Nánguài tā zhème lèi, tā gōngzuòle yì zhěng yè.', '⟦难怪他这么累，他工作了一整夜。⟧ Nánguài tā zhème lèi, tā gōngzuòle yì zhěng yè.']] }),
  L('5.3', ['Seizing the moment: 趁, 尽量, 尽快, 随手', 'Nắm thời cơ: 趁, 尽量, 尽快, 随手'], 'Bốn từ cho lời kêu gọi hành động: tận dụng lúc (趁), hết mức có thể (尽量), càng nhanh càng tốt (尽快), tiện tay (随手).', {
    goals: [['Use ⟦趁(着)⟧ and ⟦趁早⟧', 'Dùng ⟦趁(着)⟧ và ⟦趁早⟧'], ['Use ⟦尽量⟧ and ⟦尽快⟧', 'Dùng ⟦尽量⟧ và ⟦尽快⟧'], ['Use ⟦随手⟧ and ⟦随时⟧ in advice', 'Dùng ⟦随手⟧ và ⟦随时⟧ trong lời khuyên']],
    sec: [
      { h: ['趁(着) / 趁早 — while you can', '趁(着) / 趁早 — nhân lúc / sớm đi'], p: [`⟦趁 + favourable condition + verb⟧ means doing something while an opportunity lasts. ⟦趁早⟧ means “before it is too late” and is used alone before a verb.`, `⟦趁 + điều kiện thuận lợi + động từ⟧ nghĩa làm việc gì nhân lúc thời cơ còn. ⟦趁早⟧ nghĩa “nên sớm kẻo muộn”, đứng ngay trước động từ.`],
        ex: [['趁天气好，我们去公园种树吧。', 'Chèn tiānqì hǎo, wǒmen qù gōngyuán zhòng shù ba.', 'Let’s plant trees in the park while the weather is nice.', 'Nhân lúc trời đẹp, mình đi công viên trồng cây nhé.'], ['垃圾分类要趁早养成习惯。', 'Lājī fēnlèi yào chènzǎo yǎngchéng xíguàn.', 'Form the habit of sorting rubbish early.', 'Phân loại rác nên tạo thói quen sớm.']] },
      { h: ['尽量 / 尽快 — as much / as soon as possible', '尽量 / 尽快 — hết mức / càng sớm càng tốt'], p: [`Both stand before the verb: ⟦尽量⟧ is about degree or amount, ⟦尽快⟧ about speed. They are common in requests and notices.`, `Đều đứng trước động từ: ⟦尽量⟧ về mức độ/số lượng, ⟦尽快⟧ về tốc độ. Rất hay gặp trong yêu cầu, thông báo.`],
        ex: [['请尽量少用一次性塑料袋。', 'Qǐng jǐnliàng shǎo yòng yícìxìng sùliàodài.', 'Please use as few disposable plastic bags as possible.', 'Hãy dùng ít túi ni lông dùng một lần hết mức có thể.'], ['请尽快处理这些垃圾。', 'Qǐng jǐnkuài chǔlǐ zhèxiē lājī.', 'Please deal with this rubbish as soon as possible.', 'Xin xử lý số rác này càng sớm càng tốt.']] },
      { h: ['随手 / 随时 — on the spot / any time', '随手 / 随时 — tiện tay / bất cứ lúc nào'], p: [`⟦随手 + verb⟧ means doing a small action in passing (⟦随手关灯⟧ “switch off the light as you go”). ⟦随时⟧ means “at any time”.`, `⟦随手 + động từ⟧ nghĩa làm việc nhỏ tiện tay (⟦随手关灯⟧ “tiện tay tắt đèn”). ⟦随时⟧ nghĩa “bất cứ lúc nào”.`],
        ex: [['离开房间时，请随手关灯。', 'Líkāi fángjiān shí, qǐng suíshǒu guān dēng.', 'When leaving the room, switch off the light.', 'Khi rời phòng xin tiện tay tắt đèn.'], ['有困难随时告诉我。', 'Yǒu kùnnan suíshí gàosu wǒ.', 'Tell me any time you have difficulty.', 'Có khó khăn cứ nói với tôi bất cứ lúc nào.']] }],
    vocab: [['趁', 'chèn', 'while; taking advantage of', 'nhân lúc'], ['趁早', 'chènzǎo', 'as early as possible', 'sớm đi'], ['尽量', 'jǐnliàng', 'as much as possible', 'hết mức'], ['尽快', 'jǐnkuài', 'as soon as possible', 'càng sớm càng tốt'], ['随手', 'suíshǒu', 'conveniently, in passing', 'tiện tay'], ['随时', 'suíshí', 'at any time', 'bất cứ lúc nào'], ['一次性', 'yícìxìng', 'disposable', 'dùng một lần'], ['塑料袋', 'sùliàodài', 'plastic bag', 'túi ni lông'], ['节约', 'jiéyuē', 'to save', 'tiết kiệm'], ['回收', 'huíshōu', 'to recycle, recover', 'thu hồi, tái chế']],
    dia: [['A', '周末我们去捡垃圾吧，趁天气还不冷。', 'Zhōumò wǒmen qù jiǎn lājī ba, chèn tiānqì hái bù lěng.', 'Let’s pick up rubbish this weekend while it’s not cold yet.', 'Cuối tuần mình đi nhặt rác, nhân lúc trời chưa lạnh.'], ['B', '好，大家尽量早点到。', 'Hǎo, dàjiā jǐnliàng zǎodiǎn dào.', 'OK, everyone try to come early.', 'Được, mọi người cố đến sớm.'], ['A', '请随手把可回收的瓶子放进蓝色的桶。', 'Qǐng suíshǒu bǎ kě huíshōu de píngzi fàngjìn lánsè de tǒng.', 'Please drop recyclable bottles into the blue bin as you go.', 'Xin tiện tay bỏ chai tái chế vào thùng xanh.'], ['B', '没问题，我会尽快通知大家。', 'Méi wèntí, wǒ huì jǐnkuài tōngzhī dàjiā.', 'No problem, I’ll notify everyone ASAP.', 'Không vấn đề, tôi sẽ báo mọi người sớm nhất.']],
    pit: [`Using ⟦趁⟧ with an unfavourable condition (⟦趁他生气⟧ sounds like exploiting; fine only if that is meant), and putting ⟦尽量⟧ after the verb. Note: ⟦尽⟧ here is pronounced jǐn (not jìn).`, `Dùng ⟦趁⟧ với điều kiện bất lợi (⟦趁他生气⟧ nghe như lợi dụng), và đặt ⟦尽量⟧ sau động từ. Lưu ý: ⟦尽⟧ ở đây đọc jǐn (không phải jìn).`],
    sum: [['⟦趁⟧ + chance, then act.', '⟦趁⟧ + thời cơ, rồi hành động.'], ['⟦尽量⟧ degree, ⟦尽快⟧ speed.', '⟦尽量⟧ mức độ, ⟦尽快⟧ tốc độ.'], ['⟦随手⟧ small action in passing.', '⟦随手⟧ việc nhỏ làm tiện tay.']],
    links: [[GW + 'ASGI9PNV', 'Chinese Grammar Wiki — opportune timing with 趁', 'Chinese Grammar Wiki — nắm thời cơ với 趁'], [GW + 'ASGINBWJ', 'Chinese Grammar Wiki — “as much as possible” with 尽量', 'Chinese Grammar Wiki — “hết mức” với 尽量'], [GW + 'HSK_5_grammar_points', 'Chinese Grammar Wiki — HSK 5 grammar points', 'Chinese Grammar Wiki — ngữ pháp HSK 5']],
    prac: [['Say: “Eat while it’s hot.”', 'Nói: “Ăn nhân lúc còn nóng.”', '⟦趁热吃吧。⟧ Chèn rè chī ba.', '⟦趁热吃吧。⟧ Chèn rè chī ba.'], ['Say: “Please bring your own cup as much as possible.”', 'Nói: “Xin hết mức mang theo cốc của mình.”', '⟦请尽量自带杯子。⟧ Qǐng jǐnliàng zìdài bēizi.', '⟦请尽量自带杯子。⟧ Qǐng jǐnliàng zìdài bēizi.']] }),
  QZ(5, 'Kiểm tra nhanh chương 5: 难免, 不免, 免不了, 多亏, 幸亏, 要不是, 难怪, 趁, 尽量, 尽快, 随手.', [
    Q('q1', ['第一次上台，____ 会紧张。', 'Điền: 第一次上台，____ 会紧张。'], ['难免', '多亏', '随手', '趁早'], 0, ['Natural outcome: ⟦难免⟧.', 'Kết quả tự nhiên: ⟦难免⟧.']),
    Q('q2', ['____ 你提醒我，我差点忘了带护照。', 'Điền: ____ 你提醒我，我差点忘了带护照。'], ['多亏', '难免', '尽量', '何必'], 0, ['Credit someone: ⟦多亏⟧.', 'Ghi công ai: ⟦多亏⟧.']),
    Q('q3', ['____ 带了伞，不然就淋湿了。', 'Điền: ____ 带了伞，不然就淋湿了。'], ['幸亏', '难免', '趁', '以便'], 0, ['⟦幸亏…不然…⟧.', '⟦幸亏…不然…⟧.']),
    Q('q4', ['What does 难怪 express?', 'Từ 难怪 diễn tả điều gì?'], [['realisation (“no wonder”)', 'hiểu ra (“hèn gì”)'], ['regret', 'hối tiếc'], ['request', 'yêu cầu'], ['purpose', 'mục đích']], 0, ['⟦难怪⟧ = no wonder.', '⟦难怪⟧ = hèn gì.']),
    Q('q5', ['____ 天气好，我们去爬山吧。', 'Điền: ____ 天气好，我们去爬山吧。'], ['趁', '被', '把', '比'], 0, ['⟦趁⟧ + favourable condition.', '⟦趁⟧ + điều kiện thuận lợi.']),
    Q('q6', ['请 ____ 少用塑料袋。(as much as possible)', 'Điền: 请 ____ 少用塑料袋。(hết mức có thể)'], ['尽量', '尽快', '随时', '难怪'], 0, ['Degree: ⟦尽量⟧.', 'Mức độ: ⟦尽量⟧.']),
    Q('q7', ['请 ____ 回复我。(as soon as possible)', 'Điền: 请 ____ 回复我。(sớm nhất có thể)'], ['尽快', '尽量', '随手', '不免'], 0, ['Speed: ⟦尽快⟧.', 'Tốc độ: ⟦尽快⟧.']),
    Q('q8', ['______ 政府采取措施，空气不会变好。', 'Điền: ______ 政府采取措施，空气不会变好。'], ['要不是', '多亏', '难免', '趁早'], 0, ['Counterfactual: ⟦要不是⟧ (if not for).', 'Phản thực: ⟦要不是⟧.']),
  ]) ]);

const c6 = CH(6, 'Arts, literature and film', 'Nghệ thuật, văn học và điện ảnh',
  'Từ vựng điện ảnh, văn học; suy đoán và ấn tượng (看来, 显得, 似乎, 仿佛), động từ trang trọng (受到, 遭到, 加以, 予以, 将), so sánh và đánh giá (与…相比, 比起, 相比之下, 在…方面).', [
  L('6.1', ['Impressions and inferences: 看来, 显得, 似乎, 仿佛', 'Ấn tượng và suy đoán: 看来, 显得, 似乎, 仿佛'], 'Bốn từ diễn tả điều “có vẻ như”: suy ra từ bằng chứng (看来), tạo ấn tượng (显得), phỏng đoán (似乎), ví von (仿佛).', {
    goals: [['Infer from evidence with ⟦看来⟧', 'Suy luận từ bằng chứng bằng ⟦看来⟧'], ['Describe an impression with ⟦显得⟧', 'Miêu tả ấn tượng bằng ⟦显得⟧'], ['Hedge with ⟦似乎⟧ and compare with ⟦仿佛⟧', 'Giảm nhẹ khẳng định bằng ⟦似乎⟧ và ví von bằng ⟦仿佛⟧']],
    sec: [
      { h: ['看来 / 似乎 — it seems', '看来 / 似乎 — xem ra / dường như'], p: [`⟦看来⟧ draws a conclusion from visible evidence stated before it. ⟦似乎⟧ is a more cautious guess and can be used without evidence. Both go at the start of the clause or before the verb. Do not confuse ⟦看来⟧ with ⟦在…看来⟧ of Chapter 3.`, `⟦看来⟧ rút kết luận từ bằng chứng thấy được nêu trước đó. ⟦似乎⟧ là phỏng đoán thận trọng hơn, có thể không cần bằng chứng. Cả hai đặt đầu vế hoặc trước động từ. Đừng nhầm ⟦看来⟧ với ⟦在…看来⟧ ở Chương 3.`],
        ex: [['观众都在笑，看来这部喜剧很成功。', 'Guānzhòng dōu zài xiào, kànlái zhè bù xǐjù hěn chénggōng.', 'The audience is laughing — it seems this comedy is a success.', 'Khán giả đều đang cười, xem ra bộ hài kịch này thành công.'], ['他似乎对这个结局不太满意。', 'Tā sìhū duì zhège jiéjú bú tài mǎnyì.', 'He doesn’t seem very happy with the ending.', 'Anh ấy dường như không hài lòng lắm với cái kết.']] },
      { h: ['显得 — to appear, to look (in a certain state)', '显得 — trông có vẻ, tỏ ra'], p: [`⟦显得 + adjective⟧ states how someone or something looks because of a cause: the cause is the subject (clothes, light, mood), the impression follows.`, `⟦显得 + tính từ⟧ nói người/vật trông thế nào do một nguyên nhân: nguyên nhân là chủ ngữ (quần áo, ánh sáng, tâm trạng), ấn tượng theo sau.`],
        ex: [['舞台上的灯光让演员显得更高大。', 'Wǔtái shàng de dēngguāng ràng yǎnyuán xiǎnde gèng gāodà.', 'The stage lighting makes the actor look taller.', 'Ánh đèn sân khấu khiến diễn viên trông cao lớn hơn.'], ['这首歌太安静了，显得有点儿悲伤。', 'Zhè shǒu gē tài ānjìng le, xiǎnde yǒudiǎnr bēishāng.', 'The song is so quiet that it seems a bit sad.', 'Bài hát quá yên tĩnh nên có vẻ hơi buồn.']] },
      { h: ['仿佛 — as if', '仿佛 — như thể'], p: [`⟦仿佛 … 一样 / 似的⟧ makes a vivid comparison with something that is not literally true. It is typical of literary descriptions.`, `⟦仿佛 … 一样 / 似的⟧ tạo so sánh sinh động với điều không đúng nghĩa đen. Điển hình trong miêu tả văn chương.`],
        ex: [['读这首诗，仿佛看到了一幅山水画。', 'Dú zhè shǒu shī, fǎngfú kàndàole yì fú shānshuǐ huà.', 'Reading this poem, it is as if you see a landscape painting.', 'Đọc bài thơ này như thể thấy một bức tranh sơn thuỷ.']] }],
    vocab: [['看来', 'kànlái', 'it seems (from evidence)', 'xem ra'], ['显得', 'xiǎnde', 'to look, appear', 'trông có vẻ'], ['似乎', 'sìhū', 'seemingly', 'dường như'], ['仿佛', 'fǎngfú', 'as if', 'như thể'], ['观众', 'guānzhòng', 'audience', 'khán giả'], ['喜剧', 'xǐjù', 'comedy', 'hài kịch'], ['结局', 'jiéjú', 'ending', 'kết cục'], ['舞台', 'wǔtái', 'stage', 'sân khấu'], ['演员', 'yǎnyuán', 'actor', 'diễn viên'], ['悲伤', 'bēishāng', 'sad', 'buồn thương']],
    dia: [['A', '这部电影你看完了吗？', 'Zhè bù diànyǐng nǐ kànwán le ma?', 'Did you finish this film?', 'Bạn xem xong bộ phim này chưa?'], ['B', '看完了，结局似乎有点儿悲伤。', 'Kànwán le, jiéjú sìhū yǒudiǎnr bēishāng.', 'Yes, the ending seems a bit sad.', 'Xem xong rồi, cái kết dường như hơi buồn.'], ['A', '看来你很喜欢它。', 'Kànlái nǐ hěn xǐhuan tā.', 'It seems you like it a lot.', 'Xem ra bạn rất thích nó.'], ['B', '是的，演员的表演仿佛真的一样。', 'Shì de, yǎnyuán de biǎoyǎn fǎngfú zhēn de yíyàng.', 'Yes, the acting feels real.', 'Ừ, diễn xuất như thật vậy.']],
    pit: [`Using ⟦显得⟧ with a bare noun or a verb (it needs an adjective-type predicate), and using ⟦看来⟧ when there is no visible evidence (use ⟦似乎⟧ or ⟦可能⟧).`, `Dùng ⟦显得⟧ với danh từ hoặc động từ trơn (cần vị ngữ dạng tính từ), và dùng ⟦看来⟧ khi không có bằng chứng (dùng ⟦似乎⟧ hoặc ⟦可能⟧).`],
    sum: [['⟦看来⟧: inference from evidence.', '⟦看来⟧: suy từ bằng chứng.'], ['⟦显得 + adj⟧: appears so.', '⟦显得 + tính từ⟧: trông như vậy.'], ['⟦仿佛⟧: as if; ⟦似乎⟧: seemingly.', '⟦仿佛⟧: như thể; ⟦似乎⟧: dường như.']],
    links: [[GW + 'ASG54932', 'Chinese Grammar Wiki — comparing 看起来 and 看来', 'Chinese Grammar Wiki — so sánh 看起来 và 看来'], [GW + 'ASGKQEG9', 'Chinese Grammar Wiki — comparing 显得 and 看起来', 'Chinese Grammar Wiki — so sánh 显得 và 看起来'], [GW + 'HSK_5_grammar_points', 'Chinese Grammar Wiki — HSK 5 grammar points', 'Chinese Grammar Wiki — ngữ pháp HSK 5']],
    prac: [['Say: “It seems the film is very popular.”', 'Nói: “Xem ra bộ phim rất được ưa chuộng.”', '⟦看来这部电影很受欢迎。⟧ Kànlái zhè bù diànyǐng hěn shòu huānyíng.', '⟦看来这部电影很受欢迎。⟧ Kànlái zhè bù diànyǐng hěn shòu huānyíng.'], ['Say: “The red dress makes her look beautiful.”', 'Nói: “Chiếc váy đỏ khiến cô ấy trông xinh đẹp.”', '⟦红裙子让她显得很漂亮。⟧ Hóng qúnzi ràng tā xiǎnde hěn piàoliang.', '⟦红裙子让她显得很漂亮。⟧ Hóng qúnzi ràng tā xiǎnde hěn piàoliang.']] }),
  L('6.2', ['Formal verbs: 受到, 遭到, 得到, 加以, 予以, 将', 'Động từ trang trọng: 受到, 遭到, 得到, 加以, 予以, 将'], 'Các động từ “nhận lấy/bị” + danh từ hoá (受到欢迎, 遭到批评) và động từ hình thức (加以, 予以) thường gặp trong bài báo, bình luận văn học.', {
    goals: [['Use ⟦受到 / 遭到 / 得到⟧ + abstract noun', 'Dùng ⟦受到 / 遭到 / 得到⟧ + danh từ trừu tượng'], ['Use ⟦加以 / 予以⟧ + two-syllable verb', 'Dùng ⟦加以 / 予以⟧ + động từ hai âm tiết'], ['Recognise ⟦将⟧ as a formal ⟦把⟧', 'Nhận ra ⟦将⟧ như ⟦把⟧ trang trọng']],
    sec: [
      { h: ['受到 / 遭到 / 得到 + noun', '受到 / 遭到 / 得到 + danh từ'], p: [`These three verbs take an abstract noun (usually already a verb turned noun) as object: ⟦受到⟧ is neutral/positive, ⟦遭到⟧ is for bad things (criticism, rejection), ⟦得到⟧ is for gain (recognition, support). They are the formal passive of CIC301 without ⟦被⟧.`, `Ba động từ này mang tân ngữ danh từ trừu tượng (thường là động từ danh hoá): ⟦受到⟧ trung tính/tích cực, ⟦遭到⟧ cho việc xấu (phê bình, từ chối), ⟦得到⟧ cho cái đạt được (công nhận, ủng hộ). Là dạng bị động trang trọng ở CIC301 nhưng không cần ⟦被⟧.`],
        ex: [['这部小说受到了读者的欢迎。', 'Zhè bù xiǎoshuō shòudàole dúzhě de huānyíng.', 'This novel was welcomed by readers.', 'Cuốn tiểu thuyết này được độc giả đón nhận.'], ['这部电影遭到了很多批评。', 'Zhè bù diànyǐng zāodàole hěn duō pīpíng.', 'The film met with a lot of criticism.', 'Bộ phim này bị nhiều chỉ trích.'], ['他的才华得到了大家的认可。', 'Tā de cáihuá dédàole dàjiā de rènkě.', 'His talent earned everyone’s recognition.', 'Tài năng của anh ấy được mọi người công nhận.']] },
      { h: ['加以 / 予以 — to give (treatment)', '加以 / 予以 — tiến hành, dành cho'], p: [`⟦加以 + verb⟧ means “apply the action to it” and cannot take a one-syllable verb; the object usually appears earlier as topic. ⟦予以 + noun/verb⟧ means “give” (reward, support, criticism) and is stiffer.`, `⟦加以 + động từ⟧ nghĩa “thực hiện hành động đó lên nó”, không dùng với động từ một âm tiết; tân ngữ thường đã nêu trước làm chủ đề. ⟦予以 + danh từ/động từ⟧ nghĩa “dành cho” (khen thưởng, ủng hộ, phê bình), cứng hơn.`],
        ex: [['作者对故事加以修改后才出版。', 'Zuòzhě duì gùshi jiāyǐ xiūgǎi hòu cái chūbǎn.', 'The author revised the story before publishing it.', 'Tác giả chỉnh sửa câu chuyện rồi mới xuất bản.'], ['对优秀作品要予以奖励。', 'Duì yōuxiù zuòpǐn yào yǔyǐ jiǎnglì.', 'Outstanding works should be rewarded.', 'Tác phẩm xuất sắc cần được khen thưởng.']] },
      { h: ['将 — formal 把 / future', '将 — 把 trang trọng / tương lai'], p: [`In written Chinese ⟦将⟧ replaces ⟦把⟧ (⟦将 + object + verb⟧) and also marks a near future (⟦将要⟧). The meaning is the same as 把, only the register is higher.`, `Trong văn viết ⟦将⟧ thay ⟦把⟧ (⟦将 + tân ngữ + động từ⟧) và cũng chỉ tương lai gần (⟦将要⟧). Nghĩa giống 把, chỉ khác văn phong.`],
        ex: [['导演将剧本交给了演员。', 'Dǎoyǎn jiāng jùběn jiāo gěile yǎnyuán.', 'The director handed the script to the actors.', 'Đạo diễn giao kịch bản cho diễn viên.']] }],
    vocab: [['受到', 'shòudào', 'to receive; to be subjected to', 'nhận được, bị'], ['遭到', 'zāodào', 'to suffer, meet with', 'gặp phải, bị'], ['得到', 'dédào', 'to obtain', 'đạt được'], ['加以', 'jiāyǐ', 'to apply (to)', 'tiến hành'], ['予以', 'yǔyǐ', 'to give', 'dành cho'], ['批评', 'pīpíng', 'criticism', 'phê bình'], ['认可', 'rènkě', 'to approve', 'công nhận'], ['才华', 'cáihuá', 'talent', 'tài hoa'], ['剧本', 'jùběn', 'script', 'kịch bản'], ['导演', 'dǎoyǎn', 'director', 'đạo diễn']],
    dia: [['A', '你看过那部新电影吗？', 'Nǐ kànguo nà bù xīn diànyǐng ma?', 'Have you seen that new film?', 'Bạn xem bộ phim mới đó chưa?'], ['B', '看过，它在网上遭到了不少批评。', 'Kànguo, tā zài wǎngshàng zāodàole bù shǎo pīpíng.', 'Yes, it drew a lot of online criticism.', 'Xem rồi, trên mạng nó bị chỉ trích khá nhiều.'], ['A', '可是演员的表演得到了认可。', 'Kěshì yǎnyuán de biǎoyǎn dédàole rènkě.', 'But the acting was recognised.', 'Nhưng diễn xuất lại được công nhận.'], ['B', '对，导演将这个故事拍得很感人。', 'Duì, dǎoyǎn jiāng zhège gùshi pāi de hěn gǎnrén.', 'Right, the director filmed it very movingly.', 'Đúng, đạo diễn quay câu chuyện này rất cảm động.']],
    pit: [`Using ⟦加以⟧ with one-syllable verbs (⟦加以看⟧ is wrong, ⟦加以研究⟧ is right), and using ⟦遭到⟧ for pleasant things. Remember that ⟦受到⟧/⟦遭到⟧ need an abstract noun, not a person.`, `Dùng ⟦加以⟧ với động từ một âm tiết (⟦加以看⟧ sai, ⟦加以研究⟧ đúng), và dùng ⟦遭到⟧ cho việc dễ chịu. Nhớ ⟦受到⟧/⟦遭到⟧ cần danh từ trừu tượng, không phải người.`],
    sum: [['⟦受到⟧ neutral+, ⟦遭到⟧ bad, ⟦得到⟧ gain.', '⟦受到⟧ trung tính+, ⟦遭到⟧ xấu, ⟦得到⟧ đạt được.'], ['⟦加以 / 予以⟧ + 2-syllable verb or noun.', '⟦加以 / 予以⟧ + động từ 2 âm tiết hoặc danh từ.'], ['⟦将⟧ = formal ⟦把⟧.', '⟦将⟧ = ⟦把⟧ trang trọng.']],
    links: [[GW + 'ASG1DXUD', 'Chinese Grammar Wiki — passive verbs with 受', 'Chinese Grammar Wiki — động từ bị động với 受'], [GW + 'ASG68DA5', 'Chinese Grammar Wiki — 将 as a formal 把', 'Chinese Grammar Wiki — 将 như 把 trang trọng'], [GW + 'ASGEZ2HN', 'Chinese Grammar Wiki — passive with 给', 'Chinese Grammar Wiki — bị động với 给']],
    prac: [['Say: “The plan was supported by the teachers.”', 'Nói: “Kế hoạch được các thầy cô ủng hộ.”', '⟦这个计划得到了老师们的支持。⟧ Zhège jìhuà dédàole lǎoshīmen de zhīchí.', '⟦这个计划得到了老师们的支持。⟧ Zhège jìhuà dédàole lǎoshīmen de zhīchí.'], ['Correct: 我们要加以看这些问题。', 'Sửa lỗi: 我们要加以看这些问题。', '⟦我们要对这些问题加以研究。⟧ (use a two-syllable verb)', '⟦我们要对这些问题加以研究。⟧ (dùng động từ hai âm tiết)']] }),
  L('6.3', ['Comparing and evaluating: 与…相比, 比起, 相比之下, 在…方面', 'So sánh và đánh giá: 与…相比, 比起, 相比之下, 在…方面'], 'Các mẫu so sánh văn viết khi phân tích phim, sách: 与…相比, 比起…来, 相比之下, 在…方面.', {
    goals: [['Compare with ⟦与…相比⟧ and ⟦比起…来⟧', 'So sánh bằng ⟦与…相比⟧ và ⟦比起…来⟧'], ['Contrast with ⟦相比之下⟧', 'Đối chiếu với ⟦相比之下⟧'], ['Specify an aspect with ⟦在…方面⟧', 'Chỉ khía cạnh bằng ⟦在…方面⟧']],
    sec: [
      { h: ['与…相比 / 比起…来 — compared with…', '与…相比 / 比起…来 — so với…'], p: [`⟦与 A 相比，B …⟧ and ⟦比起 A 来，B …⟧ state a comparison where B is judged (usually with ⟦更 / 比较⟧). Unlike ⟦比⟧ (CIC102), the comparison word is not in the middle of the sentence, so the adjective needs no extra degree word.`, `⟦与 A 相比，B …⟧ và ⟦比起 A 来，B …⟧ nêu phép so sánh trong đó B được đánh giá (thường có ⟦更 / 比较⟧). Khác ⟦比⟧ (CIC102), từ so sánh không nằm giữa câu nên tính từ không cần thêm từ chỉ mức.`], f: '与 A 相比，B + 更 / 比较 + 形容词 ;  比起 A (来)，B …',
        ex: [['与小说相比，电影更直观。', 'Yǔ xiǎoshuō xiāngbǐ, diànyǐng gèng zhíguān.', 'Compared with novels, films are more direct.', 'So với tiểu thuyết, phim trực quan hơn.'], ['比起看电视剧，我更喜欢读书。', 'Bǐqǐ kàn diànshìjù, wǒ gèng xǐhuan dúshū.', 'Compared with watching TV dramas, I prefer reading.', 'So với xem phim truyền hình, tôi thích đọc sách hơn.']] },
      { h: ['相比之下 — by comparison', '相比之下 — so ra'], p: [`⟦相比之下⟧ starts a new clause that contrasts with a situation just mentioned; the compared object is not repeated.`, `⟦相比之下⟧ mở đầu vế mới đối chiếu với tình huống vừa nêu; không lặp lại đối tượng so sánh.`],
        ex: [['上一部电影很无聊，相比之下，这部的剧情更吸引人。', 'Shàng yí bù diànyǐng hěn wúliáo, xiāngbǐ zhī xià, zhè bù de jùqíng gèng xīyǐn rén.', 'The last film was boring; by comparison, this plot is more engaging.', 'Phim trước rất chán, so ra cốt truyện phim này cuốn hút hơn.']] },
      { h: ['在…方面 — in the aspect of', '在…方面 — về mặt…'], p: [`⟦在 + noun + 方面⟧ names the area being evaluated. Often followed by ⟦很 / 比较 / 非常⟧ + adjective, or by ⟦有…的表现⟧.`, `⟦在 + danh từ + 方面⟧ nêu lĩnh vực được đánh giá. Thường theo sau là ⟦很 / 比较 / 非常⟧ + tính từ.`],
        ex: [['在表演方面，他非常出色。', 'Zài biǎoyǎn fāngmiàn, tā fēicháng chūsè.', 'In acting, he is outstanding.', 'Về diễn xuất, anh ấy rất xuất sắc.']] }],
    vocab: [['与…相比', 'yǔ…xiāngbǐ', 'compared with…', 'so với…'], ['比起', 'bǐqǐ', 'compared to', 'so với'], ['相比之下', 'xiāngbǐ zhī xià', 'by comparison', 'so ra'], ['在…方面', 'zài…fāngmiàn', 'in terms of', 'về mặt'], ['直观', 'zhíguān', 'intuitive, direct', 'trực quan'], ['电视剧', 'diànshìjù', 'TV drama', 'phim truyền hình'], ['剧情', 'jùqíng', 'plot', 'cốt truyện'], ['吸引', 'xīyǐn', 'to attract', 'thu hút'], ['表演', 'biǎoyǎn', 'performance', 'biểu diễn, diễn xuất'], ['出色', 'chūsè', 'outstanding', 'xuất sắc']],
    dia: [['A', '你更喜欢小说还是电影？', 'Nǐ gèng xǐhuan xiǎoshuō háishi diànyǐng?', 'Do you prefer novels or films?', 'Bạn thích tiểu thuyết hay phim hơn?'], ['B', '与电影相比，我觉得小说更有想象空间。', 'Yǔ diànyǐng xiāngbǐ, wǒ juéde xiǎoshuō gèng yǒu xiǎngxiàng kōngjiān.', 'Compared with film, novels leave more room for imagination.', 'So với phim, tôi thấy tiểu thuyết có nhiều không gian tưởng tượng hơn.'], ['A', '可是在视觉方面，电影更有优势。', 'Kěshì zài shìjué fāngmiàn, diànyǐng gèng yǒu yōushì.', 'But visually, film has the advantage.', 'Nhưng về thị giác thì phim có lợi thế hơn.'], ['B', '相比之下，两者各有特点。', 'Xiāngbǐ zhī xià, liǎng zhě gè yǒu tèdiǎn.', 'By comparison, each has its own character.', 'So ra, mỗi bên có nét riêng.']],
    pit: [`Mixing ⟦与…相比⟧ with ⟦比⟧ in one clause (⟦与他相比，我比高⟧ is wrong). Also, do not repeat the compared noun after ⟦相比之下⟧.`, `Trộn ⟦与…相比⟧ với ⟦比⟧ trong một vế (⟦与他相比，我比高⟧ sai). Và đừng lặp lại danh từ so sánh sau ⟦相比之下⟧.`],
    sum: [['⟦与 A 相比，B …⟧ / ⟦比起 A 来，B …⟧.', '⟦与 A 相比，B …⟧ / ⟦比起 A 来，B …⟧.'], ['⟦相比之下⟧: contrast with the previous.', '⟦相比之下⟧: đối chiếu với điều vừa nêu.'], ['⟦在…方面⟧: name the aspect.', '⟦在…方面⟧: nêu khía cạnh.']],
    links: [[GW + 'ASGE4B94', 'Chinese Grammar Wiki — comparisons with 比起', 'Chinese Grammar Wiki — so sánh với 比起'], [GW + 'ASGWH1D5', 'Chinese Grammar Wiki — comparisons with 不如', 'Chinese Grammar Wiki — so sánh với 不如'], [GW + 'ASG1MD4N', 'Chinese Grammar Wiki — comparing specifically with 像', 'Chinese Grammar Wiki — so sánh cụ thể với 像']],
    prac: [['Say: “Compared with last year, I read more this year.”', 'Nói: “So với năm ngoái, năm nay tôi đọc nhiều hơn.”', '⟦与去年相比，今年我读得更多。⟧ Yǔ qùnián xiāngbǐ, jīnnián wǒ dú de gèng duō.', '⟦与去年相比，今年我读得更多。⟧ Yǔ qùnián xiāngbǐ, jīnnián wǒ dú de gèng duō.'], ['Say: “In music, this film is excellent.”', 'Nói: “Về âm nhạc, bộ phim này rất tuyệt.”', '⟦在音乐方面，这部电影非常出色。⟧ Zài yīnyuè fāngmiàn, zhè bù diànyǐng fēicháng chūsè.', '⟦在音乐方面，这部电影非常出色。⟧ Zài yīnyuè fāngmiàn, zhè bù diànyǐng fēicháng chūsè.']] }),
  QZ(6, 'Kiểm tra nhanh chương 6: 看来, 显得, 似乎, 仿佛, 受到, 遭到, 加以, 将, 与…相比, 相比之下, 在…方面.', [
    Q('q1', ['路上全是积水，____ 昨晚下了大雨。', 'Điền: 路上全是积水，____ 昨晚下了大雨。'], ['看来', '仿佛', '加以', '遭到'], 0, ['Inference from evidence.', 'Suy luận từ bằng chứng.']),
    Q('q2', ['这件衣服让他 ____ 很年轻。', 'Điền: 这件衣服让他 ____ 很年轻。'], ['显得', '得到', '将', '予以'], 0, ['⟦显得 + adj⟧.', '⟦显得 + adj⟧.']),
    Q('q3', ['这部小说 ____ 了很多读者的喜爱。', 'Điền: 这部小说 ____ 了很多读者的喜爱。'], ['受到', '加以', '相比', '似乎'], 0, ['⟦受到…喜爱⟧.', '⟦受到…喜爱⟧.']),
    Q('q4', ['Which verb is for something negative?', 'Động từ nào dùng cho việc tiêu cực?'], ['遭到', '得到', '予以', '显得'], 0, ['⟦遭到⟧ = suffer.', '⟦遭到⟧ = gặp phải.']),
    Q('q5', ['Which is correct?', 'Câu nào đúng?'], ['我们要对问题加以研究。', '我们要对问题加以看。', '我们要对问题予以看。', '我们要问题加以研究。'], 0, ['⟦加以⟧ needs a two-syllable verb.', '⟦加以⟧ cần động từ hai âm tiết.']),
    Q('q6', ['The formal equivalent of 把 is …', 'Từ trang trọng tương đương 把 là …'], ['将', '被', '让', '给'], 0, ['⟦将⟧ replaces 把 in writing.', '⟦将⟧ thay 把 trong văn viết.']),
    Q('q7', ['____ 手机，我更喜欢纸质书。', 'Điền: ____ 手机，我更喜欢纸质书。'], ['比起', '何必', '固然', '以便'], 0, ['⟦比起 A，B 更…⟧.', '⟦比起 A，B 更…⟧.']),
    Q('q8', ['____ 语言方面，他很有天赋。', 'Điền: ____ 语言方面，他很有天赋。'], ['在', '把', '被', '对于'], 0, ['⟦在…方面⟧.', '⟦在…方面⟧.']),
  ]) ]);

const c7 = CH(7, 'Chengyu, proverbs and set phrases', 'Thành ngữ, tục ngữ và cách nói cố định',
  'Cấu tạo và cách dùng thành ngữ bốn chữ (成语), 24 thành ngữ thông dụng theo truyện và chủ đề, tục ngữ và hậu ngữ (歇后语).', [
  L('7.1', ['Chengyu with a story: 画蛇添足, 守株待兔 and more', 'Thành ngữ có điển tích: 画蛇添足, 守株待兔 và các câu khác'], 'Thành ngữ bốn chữ là gì, chúng đóng vai trò gì trong câu, và 8 thành ngữ có điển tích dễ nhớ.', {
    goals: [['Explain what a ⟦成语⟧ is and how it works in a sentence', 'Giải thích ⟦成语⟧ là gì và nó hoạt động thế nào trong câu'], ['Learn 8 story-based idioms', 'Học 8 thành ngữ có điển tích'], ['Use an idiom as predicate, modifier or adverbial', 'Dùng thành ngữ làm vị ngữ, định ngữ, trạng ngữ']],
    sec: [
      { h: ['What is a chengyu?', 'Thành ngữ là gì?'], p: [`A ⟦成语⟧ is a fixed phrase, usually of <strong>four characters</strong>, whose meaning is more than the sum of its characters; most come from classical stories or texts. You must keep the characters unchanged. In a sentence an idiom works like an adjective or verb phrase: as predicate (⟦他做事半途而废⟧), as modifier with ⟦的⟧ (⟦一举两得的办法⟧) or as adverbial with ⟦地⟧.`, `⟦成语⟧ là cụm cố định, thường <strong>bốn chữ</strong>, nghĩa không bằng tổng nghĩa từng chữ; đa số xuất xứ từ truyện hoặc văn cổ. Không được đổi chữ. Trong câu, thành ngữ đóng vai trò như tính từ hoặc cụm động từ: làm vị ngữ (⟦他做事半途而废⟧), định ngữ với ⟦的⟧ (⟦一举两得的办法⟧) hoặc trạng ngữ với ⟦地⟧.`] },
      { h: ['Four classic stories', 'Bốn điển tích kinh điển'], ex: [
        ['画蛇添足', 'huà shé tiān zú', '“Draw a snake and add feet” — to ruin something by an unnecessary addition. Story: a man who finished first drawing a snake added feet and lost the prize.', '“Vẽ rắn thêm chân” — làm thừa khiến hỏng việc. Điển tích: người vẽ rắn xong trước, thêm chân nên mất giải.'],
        ['守株待兔', 'shǒu zhū dài tù', '“Wait by a stump for a hare” — to rely on luck instead of effort. A farmer waited for another hare to hit the stump.', '“Ôm cây đợi thỏ” — trông chờ may rủi thay vì cố gắng. Người nông dân đợi thêm con thỏ đâm vào gốc cây.'],
        ['亡羊补牢', 'wáng yáng bǔ láo', '“Mend the pen after losing a sheep” — better late than never.', '“Mất cừu mới sửa chuồng” — muộn còn hơn không.'],
        ['井底之蛙', 'jǐng dǐ zhī wā', '“Frog at the bottom of a well” — someone with a narrow view.', '“Ếch ngồi đáy giếng” — người tầm nhìn hạn hẹp.']] },
      { h: ['Four more everyday idioms', 'Bốn thành ngữ đời thường khác'], ex: [
        ['一举两得', 'yì jǔ liǎng dé', '“One move, two gains” — to kill two birds with one stone.', '“Một việc được hai” — một công đôi việc.'],
        ['半途而废', 'bàn tú ér fèi', 'To give up halfway.', 'Bỏ dở giữa chừng.'],
        ['自相矛盾', 'zì xiāng máodùn', 'Self-contradictory (a man boasted his spear pierced any shield, and his shield stopped any spear).', 'Tự mâu thuẫn (người khoe giáo đâm thủng mọi khiên, khiên chống mọi giáo).'],
        ['对牛弹琴', 'duì niú tán qín', '“Play the lute to a cow” — to speak to someone who cannot understand.', '“Gảy đàn cho trâu nghe” — nói với người không hiểu.']] },
      { h: ['In sentences', 'Trong câu'], ex: [
        ['做事要认真，不要画蛇添足。', 'Zuò shì yào rènzhēn, bú yào huà shé tiān zú.', 'Work carefully and don’t add needless extras.', 'Làm việc phải nghiêm túc, đừng làm thừa.'],
        ['想成功就得努力，不能守株待兔。', 'Xiǎng chénggōng jiù děi nǔlì, bù néng shǒu zhū dài tù.', 'To succeed you must work hard, not wait for luck.', 'Muốn thành công phải nỗ lực, không thể ôm cây đợi thỏ.'],
        ['在去超市的路上取快递，真是一举两得。', 'Zài qù chāoshì de lùshang qǔ kuàidì, zhēn shì yì jǔ liǎng dé.', 'Collecting a parcel on the way to the supermarket is two birds with one stone.', 'Lấy bưu kiện trên đường đi siêu thị đúng là một công đôi việc.'],
        ['学汉语不能半途而废。', 'Xué Hànyǔ bù néng bàn tú ér fèi.', 'You can’t give up halfway when learning Chinese.', 'Học tiếng Trung không thể bỏ dở giữa chừng.']] }],
    vocab: [['成语', 'chéngyǔ', 'idiom (four-character)', 'thành ngữ'], ['画蛇添足', 'huà shé tiān zú', 'ruin by adding the superfluous', 'vẽ rắn thêm chân'], ['守株待兔', 'shǒu zhū dài tù', 'wait for luck', 'ôm cây đợi thỏ'], ['亡羊补牢', 'wáng yáng bǔ láo', 'better late than never', 'mất bò mới lo làm chuồng'], ['井底之蛙', 'jǐng dǐ zhī wā', 'narrow-minded person', 'ếch đáy giếng'], ['一举两得', 'yì jǔ liǎng dé', 'kill two birds', 'một công đôi việc'], ['半途而废', 'bàn tú ér fèi', 'give up halfway', 'bỏ dở giữa chừng'], ['自相矛盾', 'zì xiāng máodùn', 'self-contradictory', 'tự mâu thuẫn'], ['对牛弹琴', 'duì niú tán qín', 'cast pearls before swine', 'đàn gảy tai trâu']],
    dia: [['A', '我昨天只复习了一小时就放弃了。', 'Wǒ zuótiān zhǐ fùxíle yì xiǎoshí jiù fàngqì le.', 'I gave up after only an hour of revision yesterday.', 'Hôm qua tôi mới ôn một giờ đã bỏ.'], ['B', '学习不能半途而废啊。', 'Xuéxí bù néng bàn tú ér fèi a.', 'Studying can’t be abandoned halfway.', 'Học tập không thể bỏ dở giữa chừng.'], ['A', '我知道了。现在开始还来得及，也算亡羊补牢吧。', 'Wǒ zhīdào le. Xiànzài kāishǐ hái lái de jí, yě suàn wáng yáng bǔ láo ba.', 'I know. Starting now isn’t too late — better late than never.', 'Tôi biết rồi. Bắt đầu bây giờ vẫn kịp, coi như mất bò mới lo làm chuồng.'], ['B', '对，别再守株待兔，等着好运了。', 'Duì, bié zài shǒu zhū dài tù, děngzhe hǎoyùn le.', 'Right, stop waiting around for luck.', 'Đúng, đừng ôm cây đợi thỏ chờ may nữa.']],
    pit: [`Changing a character (⟦画蛇加足⟧ is wrong) and forcing an idiom into the wrong role — ⟦井底之蛙⟧ is a noun phrase (a person), not a verb. Always check the example in a dictionary.`, `Đổi chữ (⟦画蛇加足⟧ sai) và ép thành ngữ vào sai vai — ⟦井底之蛙⟧ là cụm danh từ (chỉ người), không phải động từ. Hãy kiểm tra ví dụ trong từ điển.`],
    sum: [['A ⟦成语⟧ = 4-character fixed phrase, meaning from a story.', '⟦成语⟧ = cụm cố định 4 chữ, nghĩa từ điển tích.'], ['Keep the characters unchanged.', 'Giữ nguyên các chữ.'], ['Learn each with its story and one example.', 'Học mỗi câu kèm điển tích và một ví dụ.']],
    links: [['https://en.wikipedia.org/wiki/Chengyu', 'Wikipedia — Chengyu', 'Wikipedia — Chengyu'], ['https://zh.wikipedia.org/wiki/%E6%88%90%E8%AF%AD', 'Chinese Wikipedia — 成语', 'Wikipedia tiếng Trung — 成语'], ['https://en.wikipedia.org/wiki/Four-character_idiom', 'Wikipedia — Four-character idiom', 'Wikipedia — Thành ngữ bốn chữ']],
    prac: [['What does 画蛇添足 mean, and when do you say it?', '画蛇添足 nghĩa là gì và khi nào dùng?', 'Adding something unnecessary that spoils the work.', 'Làm thêm điều thừa khiến hỏng việc.'], ['Complete: 他想一边运动一边听英语，真是 ____ 。', 'Điền: 他想一边运动一边听英语，真是 ____ 。', '⟦一举两得⟧ — yì jǔ liǎng dé.', '⟦一举两得⟧ — yì jǔ liǎng dé.']] }),
  L('7.2', ['Chengyu for effort and study: 持之以恒, 全力以赴…', 'Thành ngữ về nỗ lực và học tập: 持之以恒, 全力以赴…'], 'Tám thành ngữ về học tập và làm việc, cách đặt vào câu nghị luận và thư xin việc.', {
    goals: [['Learn 8 idioms about effort and learning', 'Học 8 thành ngữ về nỗ lực, học tập'], ['Put idioms into a short opinion paragraph', 'Đặt thành ngữ vào đoạn văn nêu ý kiến']],
    sec: [
      { h: ['Persistence and effort', 'Kiên trì và nỗ lực'], ex: [
        ['持之以恒', 'chí zhī yǐ héng', 'To persevere.', 'Kiên trì bền bỉ.'],
        ['全力以赴', 'quán lì yǐ fù', 'To go all out.', 'Dốc toàn lực.'],
        ['一心一意', 'yì xīn yí yì', 'Wholeheartedly.', 'Một lòng một dạ.'],
        ['精益求精', 'jīng yì qiú jīng', 'To strive for perfection.', 'Càng làm càng tốt hơn.']] },
      { h: ['Method and result', 'Phương pháp và kết quả'], ex: [
        ['事半功倍', 'shì bàn gōng bèi', 'Half the effort, double the result.', 'Công ít hiệu quả nhiều.'],
        ['取长补短', 'qǔ cháng bǔ duǎn', 'To learn from others’ strengths to offset one’s weaknesses.', 'Lấy cái dài bù cái ngắn.'],
        ['熟能生巧', 'shú néng shēng qiǎo', 'Practice makes perfect.', 'Quen tay hay việc.'],
        ['迫不及待', 'pò bù jí dài', 'Unable to wait.', 'Nóng lòng không chờ nổi.']] },
      { h: ['Using them in an opinion paragraph', 'Dùng trong đoạn nêu ý kiến'], p: [`A short model for the HSK 5 writing task: state a view, give two reasons with idioms, finish with advice.`, `Một đoạn mẫu cho bài viết HSK 5: nêu quan điểm, hai lý do có thành ngữ, kết bằng lời khuyên.`], ex: [
        ['学汉语需要持之以恒。只要每天坚持，就会熟能生巧。', 'Xué Hànyǔ xūyào chí zhī yǐ héng. Zhǐyào měi tiān jiānchí, jiù huì shú néng shēng qiǎo.', 'Learning Chinese requires perseverance. As long as you persist daily, practice makes perfect.', 'Học tiếng Trung cần kiên trì. Chỉ cần mỗi ngày bền bỉ thì quen tay hay việc.'],
        ['如果方法正确，学习就能事半功倍。', 'Rúguǒ fāngfǎ zhèngquè, xuéxí jiù néng shì bàn gōng bèi.', 'With the right method, study yields twice the result for half the effort.', 'Nếu phương pháp đúng, học tập sẽ công ít hiệu quả nhiều.'],
        ['我们应该取长补短，全力以赴完成目标。', 'Wǒmen yīnggāi qǔ cháng bǔ duǎn, quán lì yǐ fù wánchéng mùbiāo.', 'We should learn from each other and go all out to reach the goal.', 'Chúng ta nên lấy dài bù ngắn và dốc toàn lực hoàn thành mục tiêu.']] }],
    vocab: [['持之以恒', 'chí zhī yǐ héng', 'persevere', 'kiên trì'], ['全力以赴', 'quán lì yǐ fù', 'go all out', 'dốc toàn lực'], ['一心一意', 'yì xīn yí yì', 'wholeheartedly', 'một lòng một dạ'], ['精益求精', 'jīng yì qiú jīng', 'strive for perfection', 'càng tốt hơn nữa'], ['事半功倍', 'shì bàn gōng bèi', 'double result, half effort', 'công ít hiệu quả nhiều'], ['取长补短', 'qǔ cháng bǔ duǎn', 'learn from strengths', 'lấy dài bù ngắn'], ['熟能生巧', 'shú néng shēng qiǎo', 'practice makes perfect', 'quen tay hay việc'], ['迫不及待', 'pò bù jí dài', 'too eager to wait', 'nóng lòng'], ['目标', 'mùbiāo', 'goal', 'mục tiêu']],
    dia: [['A', '你的汉语进步真快，有什么秘诀吗？', 'Nǐ de Hànyǔ jìnbù zhēn kuài, yǒu shénme mìjué ma?', 'Your Chinese has improved so fast — any secret?', 'Tiếng Trung của bạn tiến bộ nhanh quá, có bí quyết gì không?'], ['B', '没有秘诀，就是持之以恒，每天练习。', 'Méiyǒu mìjué, jiùshì chí zhī yǐ héng, měi tiān liànxí.', 'No secret, just perseverance and daily practice.', 'Không có bí quyết, chỉ là kiên trì luyện mỗi ngày.'], ['A', '还有，我找了一位好老师，学起来事半功倍。', 'Háiyǒu, wǒ zhǎole yí wèi hǎo lǎoshī, xué qǐlái shì bàn gōng bèi.', 'Also I found a good teacher, so it’s very efficient.', 'Ngoài ra tôi tìm được cô giáo giỏi, học công ít hiệu quả nhiều.'], ['B', '太好了，我也迫不及待想试试。', 'Tài hǎo le, wǒ yě pò bù jí dài xiǎng shìshi.', 'Great, I can’t wait to try as well.', 'Tuyệt, tôi cũng nóng lòng muốn thử.']],
    pit: [`Using an idiom without being sure of its register: ⟦迫不及待⟧ expresses personal eagerness, not a rule. Also do not stack more than two idioms in one short sentence; it reads as showing off.`, `Dùng thành ngữ mà không chắc sắc thái: ⟦迫不及待⟧ diễn tả sự nóng lòng cá nhân, không phải quy tắc. Đừng chất quá hai thành ngữ trong một câu ngắn, đọc như khoe chữ.`],
    sum: [['Pair each idiom with a topic: effort, method, result.', 'Gắn mỗi thành ngữ với chủ đề: nỗ lực, phương pháp, kết quả.'], ['One or two idioms per paragraph is enough.', 'Mỗi đoạn một hai thành ngữ là đủ.']],
    links: [['https://en.wikipedia.org/wiki/Chengyu', 'Wikipedia — Chengyu', 'Wikipedia — Chengyu'], ['https://www.hsk.academy/en/hsk-5-vocabulary-list', 'HSK Academy — HSK 5 vocabulary list', 'HSK Academy — từ vựng HSK 5'], ['https://www.mdbg.net/chinese/dictionary', 'MDBG dictionary (look up idioms)', 'Từ điển MDBG (tra thành ngữ)']],
    prac: [['Choose: 想在考试中取得好成绩，必须 ____ 。(持之以恒 / 守株待兔)', 'Chọn: 想在考试中取得好成绩，必须 ____ 。(持之以恒 / 守株待兔)', '⟦持之以恒⟧.', '⟦持之以恒⟧.'], ['Which means “practice makes perfect”?', 'Câu nào nghĩa “quen tay hay việc”?', '⟦熟能生巧⟧ shú néng shēng qiǎo.', '⟦熟能生巧⟧ shú néng shēng qiǎo.']] }),
  L('7.3', ['Proverbs and xiehouyu: 谚语 and 歇后语', 'Tục ngữ và hậu ngữ: 谚语 và 歇后语'], 'Tục ngữ phổ biến và 歇后语 (câu đố hai vế), cách dùng trong hội thoại và ngôn ngữ báo chí.', {
    goals: [['Learn 4 proverbs and 4 xiehouyu', 'Học 4 tục ngữ và 4 歇后语'], ['Understand the two-part structure of xiehouyu', 'Hiểu cấu trúc hai vế của 歇后语']],
    sec: [
      { h: ['Proverbs (谚语)', 'Tục ngữ (谚语)'], p: [`Proverbs are full sentences giving advice or a general truth. They are spoken style and can be quoted in a composition to support a point.`, `Tục ngữ là câu trọn vẹn nêu lời khuyên hoặc chân lý chung. Mang tính khẩu ngữ, có thể trích trong bài viết để củng cố ý.`], ex: [
        ['一寸光阴一寸金。', 'Yí cùn guāngyīn yí cùn jīn.', 'An inch of time is an inch of gold — time is precious.', 'Một tấc thời gian một tấc vàng.'],
        ['千里之行，始于足下。', 'Qiān lǐ zhī xíng, shǐ yú zú xià.', 'A journey of a thousand miles begins with one step.', 'Đi ngàn dặm bắt đầu từ một bước chân.'],
        ['失败是成功之母。', 'Shībài shì chénggōng zhī mǔ.', 'Failure is the mother of success.', 'Thất bại là mẹ thành công.'],
        ['三个臭皮匠，顶个诸葛亮。', 'Sān gè chòu píjiang, dǐng gè Zhūgě Liàng.', 'Three cobblers equal one Zhuge Liang — many heads are better than one.', 'Ba ông thợ giày bằng một Gia Cát Lượng.']] },
      { h: ['Xiehouyu (歇后语) — a two-part riddle', '歇后语 — câu đố hai vế'], p: [`A ⟦歇后语⟧ has a picture part and an explanation part separated by ⟦——⟧. In speech the second part is often <em>left unsaid</em> (“歇后”) because the listener can guess it.`, `⟦歇后语⟧ gồm vế hình ảnh và vế giải thích, ngăn bằng ⟦——⟧. Khi nói thường <em>bỏ vế sau</em> (“歇后”) vì người nghe tự đoán được.`], ex: [
        ['哑巴吃黄连——有苦说不出', 'Yǎba chī huánglián — yǒu kǔ shuō bù chū', 'A mute eating bitter herb — can’t express the suffering.', 'Người câm ăn hoàng liên — khổ mà không nói ra được.'],
        ['小葱拌豆腐——一清二白', 'Xiǎo cōng bàn dòufu — yì qīng èr bái', 'Scallion with tofu — perfectly clear (also “innocent”).', 'Hành trộn đậu phụ — rõ ràng trong sạch.'],
        ['竹篮打水——一场空', 'Zhúlán dǎ shuǐ — yì chǎng kōng', 'Drawing water with a bamboo basket — all for nothing.', 'Múc nước bằng rổ tre — công cốc.'],
        ['八仙过海——各显神通', 'Bā xiān guò hǎi — gè xiǎn shéntōng', 'Eight Immortals crossing the sea — each shows their own skill.', 'Bát tiên qua biển — mỗi người một tài.']] }],
    vocab: [['谚语', 'yànyǔ', 'proverb', 'tục ngữ'], ['歇后语', 'xiēhòuyǔ', 'two-part allegorical saying', 'hậu ngữ (câu đố hai vế)'], ['光阴', 'guāngyīn', 'time', 'thời gian, quang âm'], ['足下', 'zúxià', 'under the foot', 'dưới chân'], ['黄连', 'huánglián', 'goldthread (bitter herb)', 'hoàng liên'], ['豆腐', 'dòufu', 'tofu', 'đậu phụ'], ['竹篮', 'zhúlán', 'bamboo basket', 'rổ tre'], ['神通', 'shéntōng', 'magical skill', 'bản lĩnh, thần thông'], ['清白', 'qīngbái', 'pure; innocent', 'trong sạch']],
    dia: [['A', '我没有说过那句话，我是小葱拌豆腐——', 'Wǒ méiyǒu shuōguo nà jù huà, wǒ shì xiǎo cōng bàn dòufu——', 'I never said that — I’m scallion with tofu —', 'Tôi chưa nói câu đó, tôi là hành trộn đậu phụ —'], ['B', '一清二白，我相信你。', 'Yì qīng èr bái, wǒ xiāngxìn nǐ.', 'Clear as day. I believe you.', 'Trong sạch rõ ràng, tôi tin bạn.'], ['A', '这次考试我准备了很久，别再说我偷懒了。', 'Zhè cì kǎoshì wǒ zhǔnbèile hěn jiǔ, bié zài shuō wǒ tōu lǎn le.', 'I prepared long for this exam — stop saying I’m lazy.', 'Kỳ thi này tôi chuẩn bị lâu rồi, đừng nói tôi lười nữa.'], ['B', '好，千里之行，始于足下，继续加油。', 'Hǎo, qiān lǐ zhī xíng, shǐ yú zú xià, jìxù jiāyóu.', 'OK, a journey starts with one step — keep going.', 'Được, đi ngàn dặm bắt đầu từ một bước, cố lên.']],
    pit: [`Quoting only the second half of a xiehouyu to someone who has not heard the first, or using a xiehouyu in formal writing, where proverbs and idioms are preferred.`, `Chỉ nói vế sau của 歇后语 với người chưa nghe vế đầu, hoặc dùng 歇后语 trong văn trang trọng, nơi nên dùng thành ngữ/tục ngữ.`],
    sum: [['⟦谚语⟧ = full sentence of advice; spoken.', '⟦谚语⟧ = câu trọn vẹn nêu lời khuyên; khẩu ngữ.'], ['⟦歇后语⟧ = picture part + meaning part.', '⟦歇后语⟧ = vế hình ảnh + vế nghĩa.']],
    links: [['https://en.wikipedia.org/wiki/Xiehouyu', 'Wikipedia — Xiehouyu', 'Wikipedia — Xiehouyu'], ['https://en.wikipedia.org/wiki/Chengyu', 'Wikipedia — Chengyu', 'Wikipedia — Chengyu'], ['https://zh.wikipedia.org/wiki/%E6%88%90%E8%AF%AD', 'Chinese Wikipedia — 成语', 'Wikipedia tiếng Trung — 成语']],
    prac: [['What is the second half of 竹篮打水——?', 'Vế sau của 竹篮打水—— là gì?', '⟦一场空⟧ — all for nothing.', '⟦一场空⟧ — công cốc.'], ['Which proverb says “time is precious”?', 'Tục ngữ nào nói “thời gian quý báu”?', '⟦一寸光阴一寸金⟧.', '⟦一寸光阴一寸金⟧.']] }),
  QZ(7, 'Kiểm tra nhanh chương 7: thành ngữ, tục ngữ, 歇后语.', [
    Q('q1', ['“画蛇添足” means …', '“画蛇添足” nghĩa là …'], [['to ruin by adding the unnecessary', 'làm thừa khiến hỏng'], ['to draw well', 'vẽ đẹp'], ['to be afraid of snakes', 'sợ rắn'], ['to walk slowly', 'đi chậm']], 0, ['Superfluous addition.', 'Thêm điều thừa.']),
    Q('q2', ['Which idiom means “wait for luck”?', 'Thành ngữ nào nghĩa “chờ may”?'], ['守株待兔', '亡羊补牢', '一举两得', '持之以恒'], 0, ['⟦守株待兔⟧.', '⟦守株待兔⟧.']),
    Q('q3', ['出了问题再补救，也算 ____ 。', 'Điền: 出了问题再补救，也算 ____ 。'], ['亡羊补牢', '对牛弹琴', '自相矛盾', '半途而废'], 0, ['Better late than never.', 'Muộn còn hơn không.']),
    Q('q4', ['Which idiom means “give up halfway”?', 'Thành ngữ nào nghĩa “bỏ dở giữa chừng”?'], ['半途而废', '事半功倍', '全力以赴', '一心一意'], 0, ['⟦半途而废⟧.', '⟦半途而废⟧.']),
    Q('q5', ['找到好方法，学习就能 ____ 。', 'Điền: 找到好方法，学习就能 ____ 。'], ['事半功倍', '对牛弹琴', '画蛇添足', '井底之蛙'], 0, ['Half effort, double result.', 'Công ít hiệu quả nhiều.']),
    Q('q6', ['“井底之蛙” describes …', '“井底之蛙” chỉ …'], [['a narrow-minded person', 'người tầm nhìn hẹp'], ['a hard worker', 'người chăm chỉ'], ['a good swimmer', 'người bơi giỏi'], ['a clever child', 'đứa trẻ thông minh']], 0, ['Frog in the well.', 'Ếch đáy giếng.']),
    Q('q7', ['竹篮打水——____', 'Điền vế sau: 竹篮打水——____'], ['一场空', '一清二白', '有苦说不出', '各显神通'], 0, ['Xiehouyu second part.', 'Vế sau của 歇后语.']),
    Q('q8', ['Which proverb is about the first step?', 'Tục ngữ nào nói về bước đầu tiên?'], ['千里之行，始于足下', '一寸光阴一寸金', '失败是成功之母', '隔墙有耳'], 0, ['A thousand-mile journey.', 'Đi ngàn dặm.']),
  ]) ]);

const c8 = CH(8, 'Media, society and formal style', 'Truyền thông, xã hội và văn phong trang trọng',
  'Ngôn ngữ bản tin (据…报道, 近年来, 其中, 此外, 由此可见), nhượng bộ mạnh (哪怕, 即便, 纵然, 再…也, 就连), cặp từ khẩu ngữ – văn viết.', [
  L('8.1', ['Reading the news: 据…, 近年来, 其中, 此外, 由此可见', 'Đọc tin tức: 据…, 近年来, 其中, 此外, 由此可见'], 'Những khung câu xuất hiện trong gần như mọi bài báo: nguồn tin, mốc thời gian, tách một phần, bổ sung và kết luận.', {
    goals: [['Cite a source with ⟦据…报道 / 据统计 / 据调查⟧', 'Dẫn nguồn với ⟦据…报道 / 据统计 / 据调查⟧'], ['Place events in time with ⟦近年来⟧', 'Đặt sự việc vào dòng thời gian với ⟦近年来⟧'], ['Add and conclude with ⟦其中⟧, ⟦此外⟧, ⟦由此可见⟧', 'Bổ sung và kết luận với ⟦其中⟧, ⟦此外⟧, ⟦由此可见⟧']],
    sec: [
      { h: ['Source and time', 'Nguồn tin và thời gian'], p: [`⟦据 + source + 报道 / 统计 / 调查⟧ opens a news sentence (CIC301 taught ⟦据说⟧ and ⟦根据⟧; ⟦据⟧ is the written form). ⟦近年来⟧ means “in recent years” and introduces a trend, usually with ⟦越来越多⟧.`, `⟦据 + nguồn + 报道 / 统计 / 调查⟧ mở đầu câu tin (CIC301 đã học ⟦据说⟧ và ⟦根据⟧; ⟦据⟧ là dạng văn viết). ⟦近年来⟧ nghĩa “mấy năm gần đây”, mở ra một xu hướng, thường đi với ⟦越来越多⟧.`], ex: [
        ['据调查，大部分学生每天上网三个小时以上。', 'Jù diàochá, dà bùfen xuésheng měi tiān shàngwǎng sān gè xiǎoshí yǐshàng.', 'According to a survey, most students go online more than three hours a day.', 'Theo khảo sát, phần lớn sinh viên lên mạng hơn ba giờ mỗi ngày.'],
        ['近年来，越来越多的年轻人选择在网上学习。', 'Jìnnián lái, yuè lái yuè duō de niánqīngrén xuǎnzé zài wǎngshàng xuéxí.', 'In recent years, more and more young people choose to study online.', 'Những năm gần đây, ngày càng nhiều bạn trẻ chọn học trực tuyến.']] },
      { h: ['Part, addition and conclusion', 'Một phần, bổ sung và kết luận'], p: [`⟦其中⟧ picks a subset from a group just mentioned. ⟦此外⟧ adds another point (“besides”). ⟦由此可见⟧ draws a conclusion from the facts above.`, `⟦其中⟧ tách một bộ phận trong nhóm vừa nêu. ⟦此外⟧ thêm một ý khác (“ngoài ra”). ⟦由此可见⟧ rút kết luận từ các dữ kiện trên.`], ex: [
        ['参加活动的有两百人，其中一半是学生。', 'Cānjiā huódòng de yǒu liǎng bǎi rén, qízhōng yíbàn shì xuésheng.', 'Two hundred people took part, half of them students.', 'Có hai trăm người tham gia, trong đó một nửa là sinh viên.'],
        ['学校提供免费课程。此外，还有各种比赛。', 'Xuéxiào tígōng miǎnfèi kèchéng. Cǐwài, hái yǒu gè zhǒng bǐsài.', 'The school offers free courses. Besides, there are various contests.', 'Trường cung cấp khoá học miễn phí. Ngoài ra còn có nhiều cuộc thi.'],
        ['每天读书的学生成绩更好，由此可见，阅读习惯很重要。', 'Měi tiān dúshū de xuésheng chéngjì gèng hǎo, yóu cǐ kějiàn, yuèdú xíguàn hěn zhòngyào.', 'Students who read daily do better — evidently, reading habits matter.', 'Sinh viên đọc sách hằng ngày điểm cao hơn, qua đó thấy thói quen đọc rất quan trọng.']] }],
    vocab: [['据', 'jù', 'according to', 'theo'], ['报道', 'bàodào', 'report; to report', 'đưa tin'], ['统计', 'tǒngjì', 'statistics', 'thống kê'], ['调查', 'diàochá', 'survey; investigate', 'khảo sát'], ['近年来', 'jìnnián lái', 'in recent years', 'những năm gần đây'], ['其中', 'qízhōng', 'among them', 'trong đó'], ['此外', 'cǐwài', 'besides', 'ngoài ra'], ['由此可见', 'yóu cǐ kějiàn', 'from this we can see', 'qua đó thấy'], ['网民', 'wǎngmín', 'netizen', 'người dùng mạng'], ['趋势', 'qūshì', 'trend', 'xu hướng']],
    dia: [['A', '你看今天的新闻了吗？', 'Nǐ kàn jīntiān de xīnwén le ma?', 'Did you read today’s news?', 'Hôm nay bạn đọc tin chưa?'], ['B', '看了，据报道，近年来网上购物增长很快。', 'Kàn le, jù bàodào, jìnnián lái wǎngshàng gòuwù zēngzhǎng hěn kuài.', 'Yes — reportedly online shopping has grown fast in recent years.', 'Đọc rồi, theo tin, mấy năm nay mua sắm trực tuyến tăng rất nhanh.'], ['A', '其中哪一类商品最多？', 'Qízhōng nǎ yí lèi shāngpǐn zuì duō?', 'Which type of goods is most among them?', 'Trong đó loại hàng nào nhiều nhất?'], ['B', '衣服和食品。由此可见，网购已经是一种趋势。', 'Yīfu hé shípǐn. Yóu cǐ kějiàn, wǎnggòu yǐjīng shì yì zhǒng qūshì.', 'Clothes and food. Clearly online shopping is a trend.', 'Quần áo và thực phẩm. Qua đó thấy mua sắm trực tuyến đã là xu thế.']],
    pit: [`Putting ⟦据⟧ before a person you are quoting directly (use ⟦他说⟧); using ⟦其中⟧ without a group stated just before; and starting a sentence with ⟦由此可见⟧ when the facts are not in the previous sentence.`, `Đặt ⟦据⟧ trước người trích dẫn trực tiếp (dùng ⟦他说⟧); dùng ⟦其中⟧ mà trước đó không nêu nhóm; và mở câu bằng ⟦由此可见⟧ khi dữ kiện không có ở câu trước.`],
    sum: [['⟦据…⟧: source; ⟦近年来⟧: trend in time.', '⟦据…⟧: nguồn; ⟦近年来⟧: xu hướng theo thời gian.'], ['⟦其中⟧ subset, ⟦此外⟧ addition.', '⟦其中⟧ một phần, ⟦此外⟧ bổ sung.'], ['⟦由此可见⟧: conclusion.', '⟦由此可见⟧: kết luận.']],
    links: [[GW + 'ASGGB3IV', 'Chinese Grammar Wiki — “on the basis of” with 凭', 'Chinese Grammar Wiki — “dựa vào” với 凭'], [GW + 'ASG50341', 'Chinese Grammar Wiki — “including” with 在内', 'Chinese Grammar Wiki — “bao gồm” với 在内'], ['https://www.duchinese.net/', 'Du Chinese — graded news reading', 'Du Chinese — đọc tin theo cấp độ']],
    prac: [['Say: “According to the report, prices will rise next month.”', 'Nói: “Theo báo cáo, giá sẽ tăng vào tháng sau.”', '⟦据报告，下个月价格会上涨。⟧ Jù bàogào, xià gè yuè jiàgé huì shàngzhǎng.', '⟦据报告，下个月价格会上涨。⟧ Jù bàogào, xià gè yuè jiàgé huì shàngzhǎng.'], ['Fill: 班里有三十个人，____ 十个是女生。', 'Điền: 班里有三十个人，____ 十个是女生。', '⟦其中⟧ — qízhōng.', '⟦其中⟧ — qízhōng.']] }),
  L('8.2', ['Strong concession: 哪怕, 即便, 纵然, 再…也…, 就连', 'Nhượng bộ mạnh: 哪怕, 即便, 纵然, 再…也…, 就连'], 'Mở rộng nhóm “dù… cũng…” của CIC301 (即使, 就算): 哪怕 (khẩu ngữ, cực đoan), 即便/纵然 (văn viết), 再…也 (mức độ cao nhất), 就连 (ngay cả).', {
    goals: [['Use ⟦哪怕⟧ for extreme cases', 'Dùng ⟦哪怕⟧ cho trường hợp cực đoan'], ['Use ⟦即便 / 纵然⟧ in writing', 'Dùng ⟦即便 / 纵然⟧ trong văn viết'], ['Use ⟦再…也…⟧ and ⟦就连⟧', 'Dùng ⟦再…也…⟧ và ⟦就连⟧']],
    sec: [
      { h: ['哪怕 / 即便 / 纵然 — even if', '哪怕 / 即便 / 纵然 — dù cho'], p: [`CIC301 gave ⟦即使…也…⟧ and ⟦就算…也…⟧. ⟦哪怕⟧ is spoken and picks the most extreme example, ⟦即便⟧ is written and neutral, ⟦纵然⟧ is literary. The second clause always keeps ⟦也 / 都 / 还⟧.`, `CIC301 đã học ⟦即使…也…⟧ và ⟦就算…也…⟧. ⟦哪怕⟧ khẩu ngữ, chọn ví dụ cực đoan nhất; ⟦即便⟧ văn viết trung tính; ⟦纵然⟧ mang màu văn chương. Vế sau luôn giữ ⟦也 / 都 / 还⟧.`], f: '哪怕 / 即便 / 纵然 + 假设，(也 / 都) + 结果',
        ex: [['哪怕下大雨，比赛也不会取消。', 'Nǎpà xià dàyǔ, bǐsài yě bú huì qǔxiāo.', 'Even if it pours, the match won’t be cancelled.', 'Dù mưa to, trận đấu cũng không bị huỷ.'], ['即便失败了，我们也学到了经验。', 'Jíbiàn shībài le, wǒmen yě xuédàole jīngyàn.', 'Even if we fail, we will have gained experience.', 'Dù thất bại, chúng ta cũng học được kinh nghiệm.'], ['纵然困难重重，他也没有放弃。', 'Zòngrán kùnnan chóngchóng, tā yě méiyǒu fàngqì.', 'Though difficulties were many, he did not give up.', 'Dù khó khăn trùng trùng, anh ấy cũng không bỏ cuộc.']] },
      { h: ['再…也… and 就连', '再…也… và 就连'], p: [`⟦再 + adjective，也…⟧ means “however + adjective, still…” (the degree is at the maximum). ⟦就连 X 也 / 都…⟧ stresses X as an extreme example, like ⟦连…都⟧ from CIC301 but stronger.`, `⟦再 + tính từ，也…⟧ nghĩa “dù… đến đâu cũng…” (mức độ tối đa). ⟦就连 X 也 / 都…⟧ nhấn X là ví dụ cực đoan, như ⟦连…都⟧ ở CIC301 nhưng mạnh hơn.`],
        ex: [['再忙，也要吃早饭。', 'Zài máng, yě yào chī zǎofàn.', 'However busy, you must eat breakfast.', 'Bận đến đâu cũng phải ăn sáng.'], ['这个问题太难了，就连专家也不敢肯定。', 'Zhège wèntí tài nán le, jiùlián zhuānjiā yě bù gǎn kěndìng.', 'The problem is so hard that even experts are not sure.', 'Vấn đề khó đến mức ngay cả chuyên gia cũng không dám chắc.']] }],
    vocab: [['哪怕', 'nǎpà', 'even if', 'dù cho'], ['即便', 'jíbiàn', 'even if (written)', 'dù (văn viết)'], ['纵然', 'zòngrán', 'even though (literary)', 'dù (văn chương)'], ['就连', 'jiùlián', 'even', 'ngay cả'], ['取消', 'qǔxiāo', 'to cancel', 'huỷ bỏ'], ['经验', 'jīngyàn', 'experience', 'kinh nghiệm'], ['重重', 'chóngchóng', 'layer upon layer', 'trùng trùng'], ['专家', 'zhuānjiā', 'expert', 'chuyên gia'], ['肯定', 'kěndìng', 'to affirm; sure', 'khẳng định'], ['艰难', 'jiānnán', 'difficult', 'gian nan']],
    dia: [['A', '明天要考试，今晚哪怕熬夜我也要复习完。', 'Míngtiān yào kǎoshì, jīnwǎn nǎpà áoyè wǒ yě yào fùxí wán.', 'Exam tomorrow — even if I stay up all night I’ll finish revising.', 'Mai thi, tối nay dù thức khuya tôi cũng ôn cho xong.'], ['B', '再累也要睡几个小时。', 'Zài lèi yě yào shuì jǐ gè xiǎoshí.', 'However tired, sleep a few hours.', 'Mệt đến đâu cũng phải ngủ vài tiếng.'], ['A', '这次的题很难，就连老师也说不简单。', 'Zhè cì de tí hěn nán, jiùlián lǎoshī yě shuō bù jiǎndān.', 'This paper is hard; even the teacher says it isn’t simple.', 'Đề lần này khó, ngay cả thầy cũng nói không đơn giản.'], ['B', '即便如此，我们也要尽力。', 'Jíbiàn rúcǐ, wǒmen yě yào jìnlì.', 'Even so, we should do our best.', 'Dù vậy, chúng ta cũng phải cố hết sức.']],
    pit: [`Dropping ⟦也 / 都⟧ in the result clause, and using ⟦纵然⟧ in casual talk (it sounds bookish). Do not use these with facts that have already happened if you mean a hypothesis: use ⟦虽然⟧ for real facts.`, `Bỏ ⟦也 / 都⟧ ở vế sau, và dùng ⟦纵然⟧ khi nói chuyện thường ngày (nghe sách vở). Với sự việc đã xảy ra thật thì dùng ⟦虽然⟧, đừng dùng các từ giả định này.`],
    sum: [['⟦哪怕⟧ spoken extreme; ⟦即便 / 纵然⟧ written.', '⟦哪怕⟧ khẩu ngữ cực đoan; ⟦即便 / 纵然⟧ văn viết.'], ['⟦再…也…⟧ however…, still…', '⟦再…也…⟧ dù… đến đâu cũng…'], ['⟦就连 X 也…⟧ even X.', '⟦就连 X 也…⟧ ngay cả X.']],
    links: [[GW + 'ASGXX3NY', 'Chinese Grammar Wiki — “even if” with 哪怕', 'Chinese Grammar Wiki — “dù” với 哪怕'], [GW + 'ASGF1TQ2', 'Chinese Grammar Wiki — “even if” with 即使', 'Chinese Grammar Wiki — “dù” với 即使'], [GW + 'ASGLI513', 'Chinese Grammar Wiki — “even if” with 就算', 'Chinese Grammar Wiki — “dù” với 就算']],
    prac: [['Say: “Even if it is expensive, I will buy it.”', 'Nói: “Dù đắt tôi cũng mua.”', '⟦哪怕很贵，我也要买。⟧ Nǎpà hěn guì, wǒ yě yào mǎi.', '⟦哪怕很贵，我也要买。⟧ Nǎpà hěn guì, wǒ yě yào mǎi.'], ['Say: “However far, I will go.”', 'Nói: “Xa đến đâu tôi cũng đi.”', '⟦再远我也要去。⟧ Zài yuǎn wǒ yě yào qù.', '⟦再远我也要去。⟧ Zài yuǎn wǒ yě yào qù.']] }),
  L('8.3', ['Spoken vs written Chinese: 口语 and 书面语 pairs', 'Khẩu ngữ và văn viết: các cặp 口语 – 书面语'], 'Bảng các cặp từ khẩu ngữ và văn viết thường gặp, cách chuyển một câu nói thành câu viết trang trọng.', {
    goals: [['Know 10 spoken–written word pairs', 'Biết 10 cặp từ khẩu ngữ – văn viết'], ['Rewrite a spoken sentence in a formal register', 'Viết lại câu khẩu ngữ ở văn phong trang trọng']],
    sec: [
      { h: ['Why register matters', 'Vì sao văn phong quan trọng'], p: [`HSK 5 reading is full of ⟦书面语⟧ (written style), while conversation uses ⟦口语⟧. A written word is usually shorter and often one syllable shorter than its spoken partner. You do not need to use written style when speaking, but you must <em>recognise</em> it when reading.`, `Bài đọc HSK 5 đầy ⟦书面语⟧ (văn viết) còn hội thoại dùng ⟦口语⟧. Từ văn viết thường ngắn hơn từ khẩu ngữ tương ứng. Khi nói bạn không bắt buộc dùng văn viết, nhưng khi đọc phải <em>nhận ra</em> nó.`] },
      { h: ['Common pairs', 'Các cặp thường gặp'], ex: [
        ['所以 → 因此 · 可是 → 然而', 'suǒyǐ → yīncǐ · kěshì → rán’ér', 'therefore · however', 'cho nên · tuy nhiên'],
        ['都 → 均 · 把 → 将', 'dōu → jūn · bǎ → jiāng', 'all · (disposal marker)', 'đều · (chữ 把)'],
        ['很多 → 众多 · 一起 → 共同', 'hěn duō → zhòngduō · yìqǐ → gòngtóng', 'many · together', 'nhiều · cùng nhau'],
        ['马上 → 立即 · 帮助 → 协助', 'mǎshàng → lìjí · bāngzhù → xiézhù', 'immediately · to assist', 'ngay · hỗ trợ'],
        ['觉得 → 认为 · 问题 → 难题 / 课题', 'juéde → rènwéi · wèntí → nántí / kètí', 'to think · issue', 'cho rằng · vấn đề / đề tài']] },
      { h: ['Rewriting', 'Viết lại'], ex: [
        ['口语：因为下雨，所以比赛取消了。', 'Kǒuyǔ: Yīnwèi xià yǔ, suǒyǐ bǐsài qǔxiāo le.', 'Spoken: Because of rain, the match was cancelled.', 'Khẩu ngữ: Vì mưa nên trận đấu bị huỷ.'],
        ['书面：由于降雨，比赛已被取消。', 'Shūmiàn: Yóuyú jiàng yǔ, bǐsài yǐ bèi qǔxiāo.', 'Written: Owing to rainfall, the match has been cancelled.', 'Văn viết: Do mưa, trận đấu đã bị huỷ.'],
        ['口语：他马上就到，我们一起去吧。', 'Kǒuyǔ: Tā mǎshàng jiù dào, wǒmen yìqǐ qù ba.', 'Spoken: He’ll be here soon, let’s go together.', 'Khẩu ngữ: Anh ấy sắp đến rồi, chúng ta cùng đi.'],
        ['书面：他即将抵达，请大家共同前往。', 'Shūmiàn: Tā jíjiāng dǐdá, qǐng dàjiā gòngtóng qiánwǎng.', 'Written: He is about to arrive; everyone please go together.', 'Văn viết: Anh ấy sắp tới nơi, mời mọi người cùng đi.']] }],
    vocab: [['因此', 'yīncǐ', 'therefore', 'vì vậy'], ['然而', 'rán’ér', 'however', 'tuy nhiên'], ['均', 'jūn', 'all, equally', 'đều'], ['将', 'jiāng', 'will; (formal 把)', 'sẽ; (把 trang trọng)'], ['众多', 'zhòngduō', 'numerous', 'đông đảo'], ['共同', 'gòngtóng', 'jointly', 'cùng chung'], ['立即', 'lìjí', 'immediately', 'lập tức'], ['协助', 'xiézhù', 'to assist', 'hỗ trợ'], ['即将', 'jíjiāng', 'about to', 'sắp'], ['抵达', 'dǐdá', 'to arrive', 'đến nơi']],
    dia: [['A', '这封邮件太口语了，经理会不满意。', 'Zhè fēng yóujiàn tài kǒuyǔ le, jīnglǐ huì bù mǎnyì.', 'This email is too colloquial; the manager won’t like it.', 'Email này quá khẩu ngữ, quản lý sẽ không hài lòng.'], ['B', '那我把“所以”改成“因此”，“马上”改成“立即”。', 'Nà wǒ bǎ “suǒyǐ” gǎi chéng “yīncǐ”, “mǎshàng” gǎi chéng “lìjí”.', 'Then I’ll change “suǒyǐ” to “yīncǐ” and “mǎshàng” to “lìjí”.', 'Vậy tôi đổi “所以” thành “因此”, “马上” thành “立即”.'], ['A', '还可以用“请协助”代替“帮我”。', 'Hái kěyǐ yòng “qǐng xiézhù” dàitì “bāng wǒ”.', 'You can also use “qǐng xiézhù” instead of “bāng wǒ”.', 'Còn có thể dùng “请协助” thay cho “帮我”.'], ['B', '好的，谢谢你的建议。', 'Hǎo de, xièxie nǐ de jiànyì.', 'OK, thanks for the suggestion.', 'Được, cảm ơn gợi ý của bạn.']],
    pit: [`Using written words everywhere, even with friends (⟦吾⟧-style speech sounds odd), or mixing spoken and written particles within one sentence (⟦因此…所以…⟧ is redundant).`, `Dùng từ văn viết ở mọi nơi, cả khi nói với bạn (nghe lạ), hoặc trộn từ khẩu ngữ và văn viết trong một câu (⟦因此…所以…⟧ thừa).`],
    sum: [['Written words are shorter and more formal.', 'Từ văn viết ngắn và trang trọng hơn.'], ['Learn pairs, then rewrite spoken sentences.', 'Học theo cặp rồi viết lại câu nói.'], ['Recognise written style in HSK 5 reading.', 'Nhận ra văn viết trong bài đọc HSK 5.']],
    links: [[GW + 'ASG6TB4J', 'Chinese Grammar Wiki — “that’s all” with 而已', 'Chinese Grammar Wiki — “chỉ vậy thôi” với 而已'], [GW + 'ASG68DA5', 'Chinese Grammar Wiki — 将 as formal 把', 'Chinese Grammar Wiki — 将 như 把 trang trọng'], [GW + 'HSK_5_grammar_points', 'Chinese Grammar Wiki — HSK 5 grammar points', 'Chinese Grammar Wiki — ngữ pháp HSK 5']],
    prac: [['What is the written word for 马上?', 'Từ văn viết của 马上 là gì?', '⟦立即⟧ lìjí.', '⟦立即⟧ lìjí.'], ['Rewrite formally: 我觉得这个办法很好。', 'Viết trang trọng: 我觉得这个办法很好。', '⟦我认为这个办法很好。⟧ Wǒ rènwéi zhège bànfǎ hěn hǎo.', '⟦我认为这个办法很好。⟧ Wǒ rènwéi zhège bànfǎ hěn hǎo.']] }),
  QZ(8, 'Kiểm tra nhanh chương 8: văn phong tin tức, nhượng bộ mạnh, cặp khẩu ngữ – văn viết.', [
    Q('q1', ['____ 调查，大部分学生喜欢网课。', 'Điền: ____ 调查，大部分学生喜欢网课。'], ['据', '把', '被', '让'], 0, ['⟦据调查⟧ = according to the survey.', '⟦据调查⟧ = theo khảo sát.']),
    Q('q2', ['Which means “in recent years”?', 'Từ nào nghĩa “những năm gần đây”?'], ['近年来', '其中', '此外', '总之'], 0, ['⟦近年来⟧.', '⟦近年来⟧.']),
    Q('q3', ['有三百人参加，____ 一百人是外国人。', 'Điền: 有三百人参加，____ 一百人是外国人。'], ['其中', '此外', '哪怕', '纵然'], 0, ['Subset: ⟦其中⟧.', 'Một phần: ⟦其中⟧.']),
    Q('q4', ['____ 下雪，我们也要出发。(spoken, extreme)', 'Điền: ____ 下雪，我们也要出发。(khẩu ngữ, cực đoan)'], ['哪怕', '因此', '然而', '以及'], 0, ['⟦哪怕⟧.', '⟦哪怕⟧.']),
    Q('q5', ['再累 ____ 要坚持。', 'Điền: 再累 ____ 要坚持。'], ['也', '就是', '才', '却'], 0, ['⟦再…也…⟧.', '⟦再…也…⟧.']),
    Q('q6', ['Which is the written equivalent of 所以?', 'Từ văn viết tương đương 所以 là?'], ['因此', '可是', '马上', '一起'], 0, ['⟦因此⟧.', '⟦因此⟧.']),
    Q('q7', ['Which is a literary “even though”?', 'Từ nào là “dù” mang màu văn chương?'], ['纵然', '哪怕', '反正', '何必'], 0, ['⟦纵然⟧.', '⟦纵然⟧.']),
    Q('q8', ['“就连老师也不知道” means …', '“就连老师也不知道” nghĩa là …'], [['even the teacher doesn’t know', 'ngay cả thầy cũng không biết'], ['the teacher knows', 'thầy biết'], ['only the teacher knows', 'chỉ thầy biết'], ['the teacher is away', 'thầy vắng mặt']], 0, ['⟦就连…也…⟧ = even.', '⟦就连…也…⟧ = ngay cả.']),
  ]) ]);

const c9 = CH(9, 'HSK 5 skills: reading, writing and review', 'Kỹ năng HSK 5: đọc, viết và ôn tập',
  'Chiến lược đọc đoạn văn dài kèm bài mẫu, viết đoạn 80 chữ từ từ cho trước và sắp xếp câu, ôn các cặp từ dễ nhầm (以为/认为, 本来/原来, 按时/及时/准时, 终于/总算).', [
  L('9.1', ['Reading a longer passage: strategy and a model text', 'Đọc đoạn văn dài: chiến lược và bài mẫu'], 'Quy trình đọc hiểu HSK 5: đọc câu hỏi trước, bắt từ nối tín hiệu, đoán từ lạ qua bộ thủ và ngữ cảnh; một bài mẫu hoàn chỉnh có phân tích.', {
    goals: [['Use a 4-step reading routine', 'Dùng quy trình đọc 4 bước'], ['Spot signal words that mark the main idea', 'Nhận ra từ nối tín hiệu chỉ ý chính'], ['Read a model passage and answer questions', 'Đọc một bài mẫu và trả lời câu hỏi']],
    sec: [
      { h: ['A 4-step routine', 'Quy trình 4 bước'], ul: [
        [`<strong>1. Questions first.</strong> Read the questions and options before the passage so you know what to look for.`, `<strong>1. Đọc câu hỏi trước.</strong> Đọc câu hỏi và đáp án trước bài để biết cần tìm gì.`],
        [`<strong>2. Skim for signal words.</strong> ⟦然而 / 但是 / 相比之下⟧ mark a turn, ⟦因此 / 由此可见⟧ mark a conclusion, ⟦首先 / 其次⟧ mark a list (all taught in CIC301–302). The main idea often follows the turn or precedes the conclusion.`, `<strong>2. Lướt tìm từ nối tín hiệu.</strong> ⟦然而 / 但是 / 相比之下⟧ báo chuyển ý, ⟦因此 / 由此可见⟧ báo kết luận, ⟦首先 / 其次⟧ báo liệt kê (đã học ở CIC301–302). Ý chính thường theo sau chỗ chuyển hoặc đứng trước kết luận.`],
        [`<strong>3. Guess unknown words.</strong> Use the radical (氵water, 讠speech, 忄heart) and the surrounding words; do not stop for every new word.`, `<strong>3. Đoán từ lạ.</strong> Dựa vào bộ thủ (氵nước, 讠lời nói, 忄tâm) và các từ xung quanh; đừng dừng ở mọi từ mới.`],
        [`<strong>4. Check against the text.</strong> Eliminate options with absolute words (⟦一定 / 所有 / 从不⟧) unless the text says so.`, `<strong>4. Đối chiếu bài.</strong> Loại đáp án có từ tuyệt đối (⟦一定 / 所有 / 从不⟧) trừ khi bài nói vậy.`]] },
      { h: ['Model passage', 'Bài mẫu'], ex: [
        ['现在很多年轻人习惯在手机上阅读，纸质书似乎越来越少了。', 'Xiànzài hěn duō niánqīngrén xíguàn zài shǒujī shàng yuèdú, zhǐzhì shū sìhū yuè lái yuè shǎo le.', 'Nowadays many young people read on their phones, and paper books seem rarer.', 'Ngày nay nhiều người trẻ quen đọc trên điện thoại, sách giấy dường như ngày càng ít.'],
        ['据调查，近年来电子书的读者增加了不少。', 'Jù diàochá, jìnnián lái diànzǐ shū de dúzhě zēngjiāle bù shǎo.', 'Surveys show e-book readers have increased considerably in recent years.', 'Theo khảo sát, mấy năm qua độc giả sách điện tử tăng khá nhiều.'],
        ['然而，有专家指出，手机阅读容易被各种消息打断，读者很难长时间集中注意力。', 'Rán’ér, yǒu zhuānjiā zhǐchū, shǒujī yuèdú róngyì bèi gè zhǒng xiāoxi dǎduàn, dúzhě hěn nán cháng shíjiān jízhōng zhùyìlì.', 'However, some experts point out that phone reading is easily interrupted by messages, so readers can hardly concentrate for long.', 'Tuy nhiên có chuyên gia chỉ ra đọc trên điện thoại dễ bị tin nhắn làm gián đoạn, khó tập trung lâu.'],
        ['相比之下，读纸质书时，人们更专心，也更容易记住内容。', 'Xiāngbǐ zhī xià, dú zhǐzhì shū shí, rénmen gèng zhuānxīn, yě gèng róngyì jìzhù nèiróng.', 'By comparison, with paper books people are more focused and remember more.', 'So ra, khi đọc sách giấy người ta tập trung hơn và dễ nhớ nội dung hơn.'],
        ['因此，专家建议大家每天至少抽出半小时，安静地读一本纸质书。', 'Yīncǐ, zhuānjiā jiànyì dàjiā měi tiān zhìshǎo chōuchū bàn xiǎoshí, ānjìng de dú yì běn zhǐzhì shū.', 'Therefore experts advise everyone to set aside at least half an hour a day to read a paper book quietly.', 'Vì vậy chuyên gia khuyên mỗi ngày dành ít nhất nửa giờ yên tĩnh đọc một cuốn sách giấy.']] },
      { h: ['Analysis', 'Phân tích'], p: [`Signal words: ⟦然而⟧ (turn: the problem of phone reading), ⟦相比之下⟧ (comparison: paper is better), ⟦因此⟧ (conclusion: advice). The main idea is the advice. Question: <em>Why do experts recommend paper books?</em> Answer: because phone reading is easily interrupted and paper reading is more focused.`, `Từ tín hiệu: ⟦然而⟧ (chuyển ý: vấn đề của đọc điện thoại), ⟦相比之下⟧ (so sánh: sách giấy tốt hơn), ⟦因此⟧ (kết luận: lời khuyên). Ý chính là lời khuyên. Câu hỏi: <em>Vì sao chuyên gia khuyên đọc sách giấy?</em> Đáp án: vì đọc điện thoại dễ bị gián đoạn còn sách giấy giúp tập trung hơn.`] }],
    vocab: [['阅读', 'yuèdú', 'to read', 'đọc'], ['纸质', 'zhǐzhì', 'paper (adj.)', 'bằng giấy'], ['电子书', 'diànzǐ shū', 'e-book', 'sách điện tử'], ['指出', 'zhǐchū', 'to point out', 'chỉ ra'], ['打断', 'dǎduàn', 'to interrupt', 'làm gián đoạn'], ['集中', 'jízhōng', 'to concentrate', 'tập trung'], ['注意力', 'zhùyìlì', 'attention', 'sự chú ý'], ['专心', 'zhuānxīn', 'focused', 'chuyên tâm'], ['记住', 'jìzhù', 'to remember', 'ghi nhớ'], ['建议', 'jiànyì', 'to suggest', 'đề nghị']],
    pit: [`Choosing an option because it shares words with the passage (it may only repeat a detail), and reading every sentence at the same speed. Spend time on sentences after ⟦然而⟧ and ⟦因此⟧.`, `Chọn đáp án chỉ vì có từ trùng với bài (có thể chỉ lặp một chi tiết), và đọc mọi câu cùng tốc độ. Hãy dành thời gian cho câu sau ⟦然而⟧ và ⟦因此⟧.`],
    sum: [['Questions first, then skim signal words.', 'Đọc câu hỏi trước, rồi lướt từ tín hiệu.'], ['Main idea: after the turn or before the conclusion.', 'Ý chính: sau chỗ chuyển hoặc trước kết luận.'], ['Guess unknown words from radicals and context.', 'Đoán từ lạ qua bộ thủ và ngữ cảnh.']],
    links: [['https://www.duchinese.net/', 'Du Chinese — graded reading', 'Du Chinese — đọc theo cấp độ'], ['https://www.hsk.academy/en/hsk-5-vocabulary-list', 'HSK Academy — HSK 5 vocabulary list', 'HSK Academy — từ vựng HSK 5'], ['https://en.wikipedia.org/wiki/Hanyu_Shuiping_Kaoshi', 'Wikipedia — HSK test overview', 'Wikipedia — tổng quan kỳ thi HSK']],
    prac: [['Find the three signal words in the model passage.', 'Tìm ba từ tín hiệu trong bài mẫu.', '⟦然而⟧, ⟦相比之下⟧, ⟦因此⟧.', '⟦然而⟧, ⟦相比之下⟧, ⟦因此⟧.'], ['True or false: the passage says nobody reads e-books.', 'Đúng hay sai: bài nói không ai đọc sách điện tử.', 'False — e-book readers have increased.', 'Sai — độc giả sách điện tử đã tăng.']] }),
  L('9.2', ['Writing: ordering sentences and an 80-character paragraph', 'Viết: sắp xếp câu và đoạn văn 80 chữ'], 'Hai dạng viết của HSK 5: sắp xếp câu lộn xộn thành đoạn hợp lý, và viết đoạn khoảng 80 chữ dùng năm từ cho trước.', {
    goals: [['Order jumbled sentences using logic clues', 'Sắp xếp câu lộn xộn dựa vào manh mối logic'], ['Write an 80-character paragraph with 5 given words', 'Viết đoạn 80 chữ với 5 từ cho trước']],
    sec: [
      { h: ['Ordering sentences', 'Sắp xếp câu'], p: [`Clues: (1) time or sequence words (⟦去年 / 然后 / 后来⟧), (2) connectors in pairs (⟦因为…所以⟧, ⟦虽然…但是⟧), (3) pronouns (⟦他 / 这 / 其中⟧ refer back), (4) the sentence with the topic name comes first. <strong>Exercise:</strong> A ⟦他每天坚持跑步⟧ · B ⟦所以身体越来越好⟧ · C ⟦医生建议他多运动⟧ · D ⟦去年他生了一场病⟧. Order: D → C → A → B, because D gives the time and cause, C the advice, A the action, B the result (⟦所以⟧ comes after the reason).`, `Manh mối: (1) từ chỉ thời gian/trình tự (⟦去年 / 然后 / 后来⟧), (2) liên từ đi cặp (⟦因为…所以⟧, ⟦虽然…但是⟧), (3) đại từ (⟦他 / 这 / 其中⟧ chỉ lại điều trước), (4) câu nêu chủ đề đứng đầu. <strong>Bài tập:</strong> A ⟦他每天坚持跑步⟧ · B ⟦所以身体越来越好⟧ · C ⟦医生建议他多运动⟧ · D ⟦去年他生了一场病⟧. Thứ tự: D → C → A → B, vì D nêu thời gian và nguyên nhân, C lời khuyên, A hành động, B kết quả (⟦所以⟧ đi sau lý do).`] },
      { h: ['Writing with five given words', 'Viết với năm từ cho trước'], p: [`Plan three sentences: <strong>view → action → result</strong>. Use each given word once, add one connector and finish with a complete sentence. Words: ⟦保护 · 环境 · 垃圾 · 随手 · 尽量⟧.`, `Lập kế hoạch ba câu: <strong>quan điểm → hành động → kết quả</strong>. Dùng mỗi từ cho trước một lần, thêm một từ nối và kết bằng câu trọn vẹn. Các từ: ⟦保护 · 环境 · 垃圾 · 随手 · 尽量⟧.`], ex: [
        ['保护环境是每个人的责任。近年来，城市的垃圾越来越多，所以我们更应该行动起来。', 'Bǎohù huánjìng shì měi gè rén de zérèn. Jìnnián lái, chéngshì de lājī yuè lái yuè duō, suǒyǐ wǒmen gèng yīnggāi xíngdòng qǐlái.', 'Protecting the environment is everyone’s duty. In recent years cities produce ever more rubbish, so we should act.', 'Bảo vệ môi trường là trách nhiệm của mỗi người. Mấy năm nay rác ở thành phố ngày càng nhiều nên chúng ta càng phải hành động.'],
        ['出门时，我们应该尽量少用塑料袋，随手把垃圾扔进垃圾桶。', 'Chūmén shí, wǒmen yīnggāi jǐnliàng shǎo yòng sùliàodài, suíshǒu bǎ lājī rēng jìn lājītǒng.', 'When going out, use as few plastic bags as possible and drop rubbish into the bin as you go.', 'Khi ra ngoài, nên dùng ít túi ni lông hết mức và tiện tay bỏ rác vào thùng.'],
        ['如果大家都能这样做，环境一定会越来越好。', 'Rúguǒ dàjiā dōu néng zhèyàng zuò, huánjìng yídìng huì yuè lái yuè hǎo.', 'If everyone does so, the environment will certainly get better and better.', 'Nếu ai cũng làm vậy, môi trường nhất định sẽ ngày càng tốt hơn.']] }],
    vocab: [['责任', 'zérèn', 'responsibility', 'trách nhiệm'], ['行动', 'xíngdòng', 'to act; action', 'hành động'], ['垃圾桶', 'lājītǒng', 'rubbish bin', 'thùng rác'], ['扔', 'rēng', 'to throw', 'ném, vứt'], ['顺序', 'shùnxù', 'order', 'thứ tự'], ['通顺', 'tōngshùn', 'fluent, coherent', 'trôi chảy, mạch lạc'], ['连接词', 'liánjiēcí', 'connective', 'từ nối'], ['结构', 'jiégòu', 'structure', 'cấu trúc'], ['段落', 'duànluò', 'paragraph', 'đoạn văn'], ['修改', 'xiūgǎi', 'to revise', 'chỉnh sửa']],
    pit: [`Writing in English-style word order (⟦我们应该保护环境尽量⟧ is wrong) and forgetting punctuation. Use the full-width Chinese comma ⟦，⟧ and full stop ⟦。⟧ and check every character stroke by stroke; a wrong character loses marks.`, `Viết theo trật tự từ kiểu tiếng Anh (⟦我们应该保护环境尽量⟧ sai) và quên dấu câu. Dùng dấu phẩy ⟦，⟧ và chấm ⟦。⟧ toàn chiều rộng, kiểm tra từng nét; viết sai chữ sẽ mất điểm.`],
    sum: [['Ordering: time words, paired connectors, pronouns.', 'Sắp xếp: từ thời gian, liên từ cặp, đại từ.'], ['Writing: view → action → result.', 'Viết: quan điểm → hành động → kết quả.'], ['Use each given word once and proofread.', 'Dùng mỗi từ cho trước một lần và soát lại.']],
    links: [[GW + 'HSK_5_grammar_points', 'Chinese Grammar Wiki — HSK 5 grammar points', 'Chinese Grammar Wiki — ngữ pháp HSK 5'], ['https://www.mdbg.net/chinese/dictionary', 'MDBG dictionary', 'Từ điển MDBG'], ['https://www.hsk.academy/en/hsk-5-vocabulary-list', 'HSK Academy — HSK 5 vocabulary list', 'HSK Academy — từ vựng HSK 5']],
    prac: [['Order: A 所以他很累 · B 他昨晚加班到很晚 · C 今天早上起不来.', 'Sắp xếp: A 所以他很累 · B 他昨晚加班到很晚 · C 今天早上起不来.', 'B → A → C: ⟦他昨晚加班到很晚，所以他很累，今天早上起不来。⟧', 'B → A → C: ⟦他昨晚加班到很晚，所以他很累，今天早上起不来。⟧'], ['Write one sentence with 尽量 and 随手.', 'Viết một câu có 尽量 và 随手.', '⟦我们要尽量节约用水，随手关好水龙头。⟧ Wǒmen yào jǐnliàng jiéyuē yòng shuǐ, suíshǒu guānhǎo shuǐlóngtóu.', '⟦我们要尽量节约用水，随手关好水龙头。⟧ Wǒmen yào jǐnliàng jiéyuē yòng shuǐ, suíshǒu guānhǎo shuǐlóngtóu.']] }),
  L('9.3', ['Review of confusable pairs: 以为/认为, 本来/原来, 按时/及时/准时, 终于/总算', 'Ôn các cặp dễ nhầm: 以为/认为, 本来/原来, 按时/及时/准时, 终于/总算'], 'Bốn nhóm từ nghĩa gần nhau gây lỗi nhiều nhất ở HSK 4–5; mỗi nhóm có quy tắc phân biệt và ví dụ đối chiếu.', {
    goals: [['Tell ⟦以为⟧ from ⟦认为⟧ and ⟦本来⟧ from ⟦原来⟧', 'Phân biệt ⟦以为⟧ với ⟦认为⟧ và ⟦本来⟧ với ⟦原来⟧'], ['Choose among ⟦按时 / 及时 / 准时⟧', 'Chọn trong ⟦按时 / 及时 / 准时⟧'], ['Tell ⟦终于⟧ from ⟦总算⟧', 'Phân biệt ⟦终于⟧ với ⟦总算⟧']],
    sec: [
      { h: ['以为 vs 认为', '以为 vs 认为'], p: [`⟦以为⟧ means “to think (wrongly)”: the belief turns out to be false. ⟦认为⟧ is a neutral or formal “to hold that”.`, `⟦以为⟧ nghĩa “tưởng rằng (sai)”: niềm tin hóa ra không đúng. ⟦认为⟧ là “cho rằng” trung tính hoặc trang trọng.`], ex: [
        ['我以为今天不上课，原来是我记错了。', 'Wǒ yǐwéi jīntiān bú shàngkè, yuánlái shì wǒ jì cuò le.', 'I thought there was no class today — it turns out I misremembered.', 'Tôi tưởng hôm nay không có tiết, hoá ra tôi nhớ nhầm.'],
        ['我认为这个办法可行。', 'Wǒ rènwéi zhège bànfǎ kěxíng.', 'I believe this method is feasible.', 'Tôi cho rằng cách này khả thi.']] },
      { h: ['本来 vs 原来', '本来 vs 原来'], p: [`⟦本来⟧ = “originally / it should have been” (the situation then changed). ⟦原来⟧ = “originally” (an earlier state) or “so it was!” (sudden discovery).`, `⟦本来⟧ = “vốn dĩ / lẽ ra” (sau đó tình huống đổi). ⟦原来⟧ = “ban đầu” (trạng thái trước) hoặc “hoá ra” (phát hiện bất ngờ).`], ex: [
        ['我本来想去，可是下雨了。', 'Wǒ běnlái xiǎng qù, kěshì xià yǔ le.', 'I originally wanted to go, but it rained.', 'Tôi vốn định đi nhưng trời mưa.'],
        ['原来是你！我还以为是别人呢。', 'Yuánlái shì nǐ! Wǒ hái yǐwéi shì biérén ne.', 'So it was you! I thought it was somebody else.', 'Hoá ra là bạn! Tôi còn tưởng ai khác.']] },
      { h: ['按时 / 及时 / 准时', '按时 / 及时 / 准时'], p: [`⟦按时⟧ = according to schedule (doing a routine duty, e.g. hand in, take medicine). ⟦及时⟧ = just in time / promptly (in the nick of time). ⟦准时⟧ = punctually (arriving or starting on the exact time).`, `⟦按时⟧ = theo đúng thời hạn (việc thường nhật: nộp bài, uống thuốc). ⟦及时⟧ = kịp lúc (vừa đủ). ⟦准时⟧ = đúng giờ (đến/bắt đầu đúng thời điểm).`], ex: [
        ['请按时交作业。', 'Qǐng ànshí jiāo zuòyè.', 'Please hand in homework on time.', 'Hãy nộp bài đúng hạn.'],
        ['幸亏医生及时赶到。', 'Xìngkuī yīshēng jíshí gǎndào.', 'Luckily the doctor arrived in time.', 'May mà bác sĩ đến kịp lúc.'],
        ['火车准时出发。', 'Huǒchē zhǔnshí chūfā.', 'The train departs punctually.', 'Tàu khởi hành đúng giờ.']] },
      { h: ['终于 vs 总算', '终于 vs 总算'], p: [`Both mean “at last” after a wait. ⟦终于⟧ is neutral and can describe good or bad outcomes; ⟦总算⟧ always carries relief and is more spoken.`, `Cả hai nghĩa “cuối cùng” sau khi chờ đợi. ⟦终于⟧ trung tính, dùng cho cả kết quả tốt lẫn xấu; ⟦总算⟧ luôn mang sắc thái nhẹ nhõm và khẩu ngữ hơn.`], ex: [
        ['经过三年的努力，他终于考上了大学。', 'Jīngguò sān nián de nǔlì, tā zhōngyú kǎoshàngle dàxué.', 'After three years of effort, he finally got into university.', 'Sau ba năm cố gắng, cuối cùng anh ấy đỗ đại học.'],
        ['作业总算写完了！', 'Zuòyè zǒngsuàn xiě wán le!', 'The homework is finally finished — phew!', 'Bài tập cuối cùng cũng viết xong — hú hồn!']] }],
    vocab: [['以为', 'yǐwéi', 'to think (mistakenly)', 'tưởng rằng'], ['认为', 'rènwéi', 'to consider', 'cho rằng'], ['本来', 'běnlái', 'originally', 'vốn dĩ'], ['原来', 'yuánlái', 'originally; so it turns out', 'ban đầu; hoá ra'], ['按时', 'ànshí', 'on schedule', 'đúng hạn'], ['及时', 'jíshí', 'in time', 'kịp thời'], ['准时', 'zhǔnshí', 'punctual', 'đúng giờ'], ['终于', 'zhōngyú', 'finally', 'cuối cùng'], ['总算', 'zǒngsuàn', 'at long last', 'rốt cuộc cũng'], ['可行', 'kěxíng', 'feasible', 'khả thi']],
    dia: [['A', '你不是说今天开会吗？我以为你会来。', 'Nǐ bú shì shuō jīntiān kāi huì ma? Wǒ yǐwéi nǐ huì lái.', 'Didn’t you say there’s a meeting today? I thought you’d come.', 'Chẳng phải bạn nói hôm nay họp à? Tôi tưởng bạn sẽ đến.'], ['B', '本来是今天，后来改到明天了。', 'Běnlái shì jīntiān, hòulái gǎi dào míngtiān le.', 'It was supposed to be today, then it moved to tomorrow.', 'Vốn là hôm nay, sau đó dời sang ngày mai.'], ['A', '原来如此。明天请准时到。', 'Yuánlái rúcǐ. Míngtiān qǐng zhǔnshí dào.', 'I see. Please arrive punctually tomorrow.', 'Hoá ra vậy. Mai xin đến đúng giờ.'], ['B', '放心，我会按时到的，这次总算不会迟到了。', 'Fàngxīn, wǒ huì ànshí dào de, zhè cì zǒngsuàn bú huì chídào le.', 'Don’t worry, I’ll be on time; for once I won’t be late.', 'Yên tâm, tôi sẽ đến đúng hạn, lần này cuối cùng không trễ nữa.']],
    pit: [`Using ⟦以为⟧ for a belief that is true (⟦我以为这是对的⟧ implies it is wrong), and ⟦及时⟧ for a routine duty (⟦及时交作业⟧ is unusual; say ⟦按时⟧).`, `Dùng ⟦以为⟧ cho niềm tin đúng (⟦我以为这是对的⟧ ngụ ý là sai), và ⟦及时⟧ cho việc thường nhật (⟦及时交作业⟧ lạ; nên nói ⟦按时⟧).`],
    sum: [['⟦以为⟧ wrong belief; ⟦认为⟧ neutral.', '⟦以为⟧ tưởng sai; ⟦认为⟧ trung tính.'], ['⟦本来⟧ changed; ⟦原来⟧ discovery.', '⟦本来⟧ có thay đổi; ⟦原来⟧ phát hiện.'], ['⟦按时⟧ schedule, ⟦及时⟧ in time, ⟦准时⟧ exact time.', '⟦按时⟧ theo lịch, ⟦及时⟧ kịp lúc, ⟦准时⟧ đúng giờ.']],
    links: [[GW + 'ASGT8AUA', 'Chinese Grammar Wiki — comparing 总算 and 终于', 'Chinese Grammar Wiki — so sánh 总算 và 终于'], [GW + 'ASGE8FLP', 'Chinese Grammar Wiki — comparing 常常 and 经常', 'Chinese Grammar Wiki — so sánh 常常 và 经常'], [GW + 'ASG3JELV', 'Chinese Grammar Wiki — comparing 对 and 对于', 'Chinese Grammar Wiki — so sánh 对 và 对于']],
    prac: [['Choose: 我 ____ 他是老师，原来他是学生。(以为 / 认为)', 'Chọn: 我 ____ 他是老师，原来他是学生。(以为 / 认为)', '⟦以为⟧ — the belief was wrong.', '⟦以为⟧ — niềm tin hoá ra sai.'], ['Choose: 请 ____ 吃药，一天三次。(按时 / 及时 / 准时)', 'Chọn: 请 ____ 吃药，一天三次。(按时 / 及时 / 准时)', '⟦按时⟧ — according to schedule.', '⟦按时⟧ — theo đúng lịch.']] }),
  QZ(9, 'Kiểm tra tổng hợp: ôn các mẫu của cả khoá (HSK 4 → 5) và các cặp từ dễ nhầm.', [
    Q('q1', ['我 ____ 他是中国人，其实他是日本人。', 'Điền: 我 ____ 他是中国人，其实他是日本人。'], ['以为', '认为', '何必', '未必'], 0, ['Wrong belief: ⟦以为⟧.', 'Tưởng sai: ⟦以为⟧.']),
    Q('q2', ['请 ____ 到会议室，会议八点开始。', 'Điền: 请 ____ 到会议室，会议八点开始。'], ['准时', '及时', '总算', '偏偏'], 0, ['Exact time: ⟦准时⟧.', 'Đúng giờ: ⟦准时⟧.']),
    Q('q3', ['作业 ____ 写完了，真累！', 'Điền: 作业 ____ 写完了，真累！'], ['总算', '本来', '何况', '以免'], 0, ['Relief: ⟦总算⟧.', 'Nhẹ nhõm: ⟦总算⟧.']),
    Q('q4', ['出门带伞，____ 淋雨。', 'Điền: 出门带伞，____ 淋雨。'], ['以免', '以便', '从而', '即便'], 0, ['Avoid a bad result: ⟦以免⟧.', 'Tránh kết quả xấu: ⟦以免⟧.']),
    Q('q5', ['Which phrase marks a conclusion in a news article?', 'Cụm nào báo kết luận trong bài báo?'], ['由此可见', '近年来', '其中', '此外'], 0, ['⟦由此可见⟧.', '⟦由此可见⟧.']),
    Q('q6', ['____ 下大雨，比赛也不会取消。', 'Điền: ____ 下大雨，比赛也不会取消。'], ['哪怕', '之所以', '倘若', '难怪'], 0, ['Strong concession: ⟦哪怕⟧.', 'Nhượng bộ mạnh: ⟦哪怕⟧.']),
    Q('q7', ['In HSK 5 reading, the signal word 然而 usually introduces …', 'Trong đọc HSK 5, từ tín hiệu 然而 thường mở …'], [['a turn in meaning', 'một chỗ chuyển ý'], ['an example', 'một ví dụ'], ['a time', 'một mốc thời gian'], ['a list', 'một danh sách']], 0, ['⟦然而⟧ = however.', '⟦然而⟧ = tuy nhiên.']),
    Q('q8', ['Which pair is spoken → written?', 'Cặp nào là khẩu ngữ → văn viết?'], ['马上 → 立即', '立即 → 马上', '均 → 都', '因此 → 所以'], 0, ['⟦马上⟧ spoken, ⟦立即⟧ written.', '⟦马上⟧ khẩu ngữ, ⟦立即⟧ văn viết.']),
  ]) ]);

